def _crm_obter_aba(criar: bool = False):
    """Obtém a aba exclusiva do CRM; cria somente quando solicitado."""
    try:
        sh = conectar_sheets()
        if sh is None:
            return None
        try:
            return sh.worksheet(CRM_ABA)
        except Exception:
            if not criar:
                return None
            aba = sh.add_worksheet(title=CRM_ABA, rows=2000, cols=len(CRM_CABECALHOS))
            aba.append_row(CRM_CABECALHOS, value_input_option="RAW")
            try:
                aba.format("A1:Y1", {
                    "backgroundColor": {"red": 0.04, "green": 0.24, "blue": 0.46},
                    "textFormat": {"foregroundColor": {"red": 1, "green": 1, "blue": 1}, "bold": True},
                })
                aba.freeze(rows=1)
            except Exception:
                pass
            return aba
    except Exception as e:
        _log_sheets_erro("_crm_obter_aba", e)
        st.session_state["_crm_ultimo_erro"] = str(e)
        return None


def sheets_crm_inicializar() -> bool:
    return _crm_obter_aba(criar=True) is not None


def _crm_texto(valor) -> str:
    return str(valor or "").strip()


def _crm_valor_numero(valor) -> float:
    texto = re.sub(r"[^0-9,.-]", "", _crm_texto(valor))
    if not texto:
        return 0.0
    if "," in texto:
        texto = texto.replace(".", "").replace(",", ".")
    try:
        return float(texto)
    except Exception:
        return 0.0


def _crm_novo_id() -> str:
    return f"CRM-{datetime.now().strftime('%Y%m%d%H%M%S%f')[:-3]}"


def sheets_crm_listar() -> list[dict]:
    """Lista oportunidades sem misturar empresas; o filtro ocorre na tela administrativa."""
    try:
        aba = _crm_obter_aba(criar=False)
        if aba is None:
            return []
        valores = aba.get_all_values()
        if len(valores) <= 1:
            return []
        cabecalho = valores[0]
        resultado = []
        for numero_linha, linha in enumerate(valores[1:], start=2):
            linha = list(linha) + [""] * max(0, len(cabecalho) - len(linha))
            item = {cabecalho[i]: linha[i] for i in range(len(cabecalho))}
            if _crm_texto(item.get("ID")):
                item["_linha"] = numero_linha
                resultado.append(item)
        return resultado
    except Exception as e:
        _log_sheets_erro("sheets_crm_listar", e)
        st.session_state["_crm_ultimo_erro"] = str(e)
        return []


def sheets_crm_salvar(dados: dict) -> tuple[bool, str]:
    """Registra nova oportunidade na aba exclusiva do CRM."""
    try:
        aba = _crm_obter_aba(criar=True)
        if aba is None:
            return False, "Não foi possível acessar a planilha do CRM."
        agora = datetime.now().strftime("%d/%m/%Y %H:%M")
        registro = dict(dados or {})
        registro["ID"] = registro.get("ID") or _crm_novo_id()
        registro["Data_Cadastro"] = registro.get("Data_Cadastro") or agora
        registro["Data_Atualizacao"] = agora
        registro["Status"] = registro.get("Status") or "Ativo"
        aba.append_row([_crm_texto(registro.get(c)) for c in CRM_CABECALHOS], value_input_option="USER_ENTERED")
        return True, registro["ID"]
    except Exception as e:
        _log_sheets_erro("sheets_crm_salvar", e)
        st.session_state["_crm_ultimo_erro"] = str(e)
        return False, str(e)


def sheets_crm_atualizar(id_oportunidade: str, alteracoes: dict) -> bool:
    """Atualiza somente a linha identificada pelo ID; não exclui histórico."""
    try:
        aba = _crm_obter_aba(criar=False)
        if aba is None:
            return False
        ids = aba.col_values(1)
        alvo = _crm_texto(id_oportunidade)
        if alvo not in ids:
            return False
        numero_linha = ids.index(alvo) + 1
        registro_atual = {c: "" for c in CRM_CABECALHOS}
        valores_linha = aba.row_values(numero_linha)
        for i, valor in enumerate(valores_linha[:len(CRM_CABECALHOS)]):
            registro_atual[CRM_CABECALHOS[i]] = valor
        registro_atual.update(alteracoes or {})
        registro_atual["ID"] = alvo
        registro_atual["Data_Atualizacao"] = datetime.now().strftime("%d/%m/%Y %H:%M")
        aba.update(
            range_name=f"A{numero_linha}:Y{numero_linha}",
            values=[[_crm_texto(registro_atual.get(c)) for c in CRM_CABECALHOS]],
            value_input_option="USER_ENTERED",
        )
        return True
    except Exception as e:
        _log_sheets_erro("sheets_crm_atualizar", e)
        st.session_state["_crm_ultimo_erro"] = str(e)
        return False


def _crm_data_br_para_date(valor: str, padrao: date | None = None) -> date:
    try:
        return datetime.strptime(_crm_texto(valor), "%d/%m/%Y").date()
    except Exception:
        return padrao or date.today()


def _crm_moeda(valor: float) -> str:
    return f"R$ {valor:,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")


def _crm_numero_proposta(id_oportunidade: str, empresa_codigo: str) -> str:
    """Gera uma referência legível e única sem depender de outras abas."""
    prefixo = "AG" if empresa_codigo == "aqua_gestao" else "BS"
    digitos = re.sub(r"\D", "", _crm_texto(id_oportunidade))
    sufixo = digitos[-8:] if digitos else datetime.now().strftime("%m%d%H%M")
    return f"{prefixo}-{date.today().year}-{sufixo}"


def _crm_numero_contrato(id_oportunidade: str, empresa_codigo: str) -> str:
    """Gera referência do contrato vinculada à oportunidade do CRM."""
    prefixo = "CT-AG" if empresa_codigo == "aqua_gestao" else "CT-BS"
    digitos = re.sub(r"\D", "", _crm_texto(id_oportunidade))
    sufixo = digitos[-8:] if digitos else datetime.now().strftime("%m%d%H%M")
    return f"{prefixo}-{date.today().year}-{sufixo}"


def _crm_escopo_proposta(empresa_codigo: str, servico: str) -> list[str]:
    """Retorna um escopo comercial orientativo conforme empresa e serviço."""
    servico_norm = normalizar_texto_busca(servico)
    if empresa_codigo == "aqua_gestao":
        if "responsabilidade tecnica" in servico_norm:
            return [
                "Acompanhamento técnico especializado da operação da piscina coletiva.",
                "Orientações técnicas, registros, documentos e relatórios previstos na proposta.",
                "Suporte ao controle de parâmetros e à organização dos procedimentos operacionais.",
                "Condições de ART, visitas e documentos conforme detalhamento comercial contratado.",
            ]
        if "manutencao operacional" in servico_norm:
            return [
                "Limpeza física e manutenção operacional periódica da piscina coletiva.",
                "Verificação e ajuste operacional dos parâmetros previstos para cada visita.",
                "Registro dos serviços executados e comunicação de ocorrências ao contratante.",
                "Serviço operacional sem inclusão automática de Responsabilidade Técnica ou ART.",
            ]
        if "consumo humano" in servico_norm:
            return [
                "Avaliação técnica da qualidade da água nos pontos definidos com o contratante.",
                "Medições de campo e organização dos registros de coleta e rastreabilidade.",
                "Encaminhamento laboratorial quando previsto nas condições comerciais.",
                "Emissão de relatório ou registro técnico conforme o serviço contratado.",
            ]
        if "diagnostico" in servico_norm:
            return [
                "Inspeção técnica do local, equipamentos, operação e condições da água.",
                "Identificação das causas prováveis das não conformidades observadas.",
                "Recomendações de correção, prioridades e próximos passos.",
                "Entrega técnica conforme a abrangência definida nesta proposta.",
            ]
        if "relatorio" in servico_norm or "parecer" in servico_norm:
            return [
                "Levantamento e análise das informações disponibilizadas pelo contratante.",
                "Organização das evidências, resultados e registros aplicáveis.",
                "Elaboração do documento técnico correspondente ao escopo contratado.",
            ]
        if "treinamento" in servico_norm or "pop" in servico_norm:
            return [
                "Levantamento da rotina e das necessidades da equipe operacional.",
                "Orientação prática sobre procedimentos, segurança e registros.",
                "Elaboração ou revisão dos POPs previstos nas condições comerciais.",
            ]
    else:
        if "produto" in servico_norm or "equipamento" in servico_norm:
            return [
                "Fornecimento dos produtos ou equipamentos descritos nas condições comerciais.",
                "Orientações básicas de utilização, instalação ou conservação, quando aplicáveis.",
                "Garantias conforme fabricante e condições indicadas na proposta.",
            ]
        if "cerca" in servico_norm:
            return [
                "Fornecimento e instalação da cerca de proteção conforme medidas confirmadas no local.",
                "Definição de acessos, pontos de fixação e acabamento conforme vistoria.",
                "Condições de prazo, garantia e preparação do piso conforme esta proposta.",
            ]
        if "recuperacao" in servico_norm:
            return [
                "Avaliação das condições da piscina e definição do tratamento de recuperação.",
                "Execução dos procedimentos operacionais descritos nas condições comerciais.",
                "Orientação ao cliente após a conclusão do serviço.",
            ]
        if "instalacao" in servico_norm:
            return [
                "Instalação dos itens descritos, condicionada à avaliação do local.",
                "Testes básicos de funcionamento após a execução.",
                "Garantias e exclusões conforme equipamentos e condições comerciais.",
            ]
        if "manutencao" in servico_norm:
            return [
                "Limpeza física e manutenção periódica da piscina na frequência contratada.",
                "Aplicação operacional dos produtos definidos para o tratamento.",
                "Verificação visual dos equipamentos e comunicação de ocorrências ao cliente.",
                "Serviço operacional que não constitui Responsabilidade Técnica ou ART.",
            ]
    return [
        "Prestação do serviço descrito nesta proposta conforme alinhamento com o contratante.",
        "Detalhamento final de atividades, prazos e responsabilidades antes do aceite.",
    ]


def gerar_proposta_crm_pdf(dados: dict) -> bytes:
    """Gera proposta comercial premium pelo CRM, preservando os fluxos existentes."""
    import io
    from xml.sax.saxutils import escape
    from reportlab.lib import colors
    from reportlab.lib.enums import TA_CENTER, TA_JUSTIFY, TA_LEFT, TA_RIGHT
    from reportlab.lib.pagesizes import A4
    from reportlab.lib.styles import ParagraphStyle
    from reportlab.lib.units import mm
    import reportlab
    from reportlab.pdfbase import pdfmetrics
    from reportlab.pdfbase.ttfonts import TTFont
    from reportlab.platypus import (
        SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle,
        PageBreak, KeepTogether, HRFlowable, Image as RLImage,
    )

    empresa_codigo = _crm_texto(dados.get("empresa_codigo"))
    aqua = empresa_codigo == "aqua_gestao"
    empresa = "Aqua Gestão" if aqua else "Bem Star Piscinas"
    marca_txt = "ACQUA GESTÃO" if aqua else empresa.upper()  # grafia aprovada da marca
    assinatura_empresa = "Aqua Gestão - Controle Técnico de Piscinas" if aqua else "Bem Star Piscinas Ltda."
    subtitulo_empresa = "Controle Técnico de Piscinas" if aqua else "Piscinas limpas e seguras para sua família"
    cnpj_empresa = "66.008.795/0001-92" if aqua else "26.799.958/0001-88"
    azul_escuro = colors.HexColor("#07182E") if aqua else colors.HexColor("#082B57")
    azul = colors.HexColor("#0B4F83") if aqua else colors.HexColor("#12579B")
    dourado = colors.HexColor("#D7A719")
    azul_claro = colors.HexColor("#EEF5FB")
    cinza = colors.HexColor("#526174")
    borda = colors.HexColor("#C9D5E3")
    texto_cor = colors.HexColor("#152235")
    branco = colors.white

    fonte = "Helvetica"
    fonte_bold = "Helvetica-Bold"
    try:
        # As fontes Vera acompanham o próprio ReportLab. Assim, o PDF sempre
        # incorpora a fonte mesmo no Streamlit Cloud, evitando letras espaçadas.
        _reportlab_dir = Path(reportlab.__file__).resolve().parent
        _fonte_regular = _reportlab_dir / "fonts" / "Vera.ttf"
        _fonte_bold = _reportlab_dir / "fonts" / "VeraBd.ttf"
        if not (_fonte_regular.exists() and _fonte_bold.exists()):
            _fonte_regular = Path("/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf")
            _fonte_bold = Path("/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf")
        if _fonte_regular.exists() and _fonte_bold.exists():
            if "CRMDejaVu" not in pdfmetrics.getRegisteredFontNames():
                pdfmetrics.registerFont(TTFont("CRMDejaVu", str(_fonte_regular)))
            if "CRMDejaVu-Bold" not in pdfmetrics.getRegisteredFontNames():
                pdfmetrics.registerFont(TTFont("CRMDejaVu-Bold", str(_fonte_bold)))
            fonte = "CRMDejaVu"
            fonte_bold = "CRMDejaVu-Bold"
    except Exception:
        pass

    corpo = ParagraphStyle(
        "CRMPCorpo", fontName=fonte, fontSize=9.2, leading=14.2,
        textColor=texto_cor, alignment=TA_JUSTIFY, spaceAfter=2.2 * mm,
    )
    corpo_esq = ParagraphStyle("CRMPCEsq", parent=corpo, alignment=TA_LEFT)
    pequeno = ParagraphStyle(
        "CRMPCPequeno", parent=corpo_esq, fontSize=7.2, leading=10,
        textColor=cinza, spaceAfter=0,
    )
    rotulo = ParagraphStyle(
        "CRMPCRotulo", parent=corpo_esq, fontName=fonte_bold,
        fontSize=8.2, leading=11, textColor=azul_escuro, spaceAfter=0,
    )
    rotulo_branco = ParagraphStyle(
        "CRMPCRotuloBranco", parent=rotulo, textColor=branco,
        alignment=TA_CENTER,
    )
    secao = ParagraphStyle(
        "CRMPCSecao", parent=corpo_esq, fontName=fonte_bold,
        fontSize=11.2, leading=14, textColor=azul_escuro,
        spaceBefore=2.5 * mm, spaceAfter=2 * mm,
    )
    titulo_branco = ParagraphStyle(
        "CRMPCTituloBranco", parent=corpo_esq, fontName=fonte_bold,
        fontSize=19, leading=22, textColor=branco, alignment=TA_CENTER, spaceAfter=0,
    )
    marca_branca = ParagraphStyle(
        "CRMPCMarcaBranca", parent=corpo_esq, fontName=fonte_bold,
        fontSize=17, leading=19, textColor=branco, alignment=TA_CENTER, spaceAfter=0,
    )
    marca_sub = ParagraphStyle(
        "CRMPCMarcaSub", parent=corpo_esq, fontName=fonte,
        fontSize=8.3, leading=11, textColor=dourado, alignment=TA_CENTER, spaceAfter=0,
    )
    centro = ParagraphStyle("CRMPCCentro", parent=corpo_esq, alignment=TA_CENTER)
    direita = ParagraphStyle("CRMPCDireita", parent=pequeno, alignment=TA_RIGHT)
    valor_estilo = ParagraphStyle(
        "CRMPCValor", parent=corpo_esq, fontName=fonte_bold,
        fontSize=17, leading=20, textColor=azul_escuro, alignment=TA_CENTER, spaceAfter=0,
    )

    def txt(valor, padrao="-"):
        valor = _crm_texto(valor)
        return escape(valor) if valor else padrao

    def secao_titulo(texto):
        return [
            Paragraph(texto, secao),
            HRFlowable(width="100%", thickness=0.9, color=dourado, spaceBefore=0, spaceAfter=3 * mm),
        ]

    def linha_cliente(rotulo_txt, valor):
        return [Paragraph(rotulo_txt.upper(), rotulo), Paragraph(txt(valor), corpo_esq)]

    def tabela_cliente():
        contato = " | ".join(x for x in [_crm_texto(dados.get("telefone")), _crm_texto(dados.get("email"))] if x)
        endereco = " - ".join(x for x in [_crm_texto(dados.get("endereco")), _crm_texto(dados.get("cidade"))] if x)
        tipo_cliente_norm = normalizar_texto_busca(dados.get("tipo_cliente"))
        linhas = [
            linha_cliente("Cliente", dados.get("cliente")),
            linha_cliente("CPF / CNPJ", dados.get("documento")),
        ]
        if tipo_cliente_norm != "residencial":
            linhas.append(linha_cliente("Responsável / síndico", dados.get("responsavel")))
        linhas += [
            linha_cliente("Endereço", endereco),
            linha_cliente("Contato", contato),
            linha_cliente("Data da proposta", dados.get("emissao")),
            linha_cliente("Validade", f"Até {txt(dados.get('validade'))}"),
        ]
        tabela = Table(linhas, colWidths=[52 * mm, 128 * mm])
        tabela.setStyle(TableStyle([
            ("BOX", (0, 0), (-1, -1), 0.6, borda),
            ("INNERGRID", (0, 0), (-1, -1), 0.35, borda),
            ("BACKGROUND", (0, 0), (0, -1), azul_claro),
            ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
            ("LEFTPADDING", (0, 0), (-1, -1), 7),
            ("RIGHTPADDING", (0, 0), (-1, -1), 7),
            ("TOPPADDING", (0, 0), (-1, -1), 5.5),
            ("BOTTOMPADDING", (0, 0), (-1, -1), 5.5),
        ]))
        return tabela

    def cabecalho_capa():
        _logo = None
        try:
            _logo_path = encontrar_logo() if aqua else encontrar_logo_bem_star()
            if _logo_path:
                _logo = RLImage(str(_logo_path), width=31 * mm, height=22 * mm, kind="proportional")
        except Exception:
            _logo = None
        marca = Paragraph(f"{escape(marca_txt)}<br/><font size='8' color='#D7A719'>{escape(subtitulo_empresa)}</font>", marca_branca)
        celula_marca = Table([[_logo, marca]], colWidths=[37 * mm, 77 * mm]) if _logo else marca
        if isinstance(celula_marca, Table):
            celula_marca.setStyle(TableStyle([
                ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
                ("LEFTPADDING", (0, 0), (-1, -1), 0),
                ("RIGHTPADDING", (0, 0), (-1, -1), 3),
                ("TOPPADDING", (0, 0), (-1, -1), 0),
                ("BOTTOMPADDING", (0, 0), (-1, -1), 0),
            ]))
        proposta = Paragraph(
            f"PROPOSTA COMERCIAL<br/><font size='8'>{txt(dados.get('numero'))}</font>",
            titulo_branco,
        )
        tabela = Table([[celula_marca, proposta]], colWidths=[114 * mm, 66 * mm], rowHeights=[38 * mm])
        tabela.setStyle(TableStyle([
            ("BACKGROUND", (0, 0), (-1, -1), azul_escuro),
            ("LINEBELOW", (0, 0), (-1, -1), 1.8, dourado),
            ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
            ("LEFTPADDING", (0, 0), (-1, -1), 10),
            ("RIGHTPADDING", (0, 0), (-1, -1), 10),
            ("TOPPADDING", (0, 0), (-1, -1), 7),
            ("BOTTOMPADDING", (0, 0), (-1, -1), 7),
        ]))
        return tabela

    def apresentacao_texto():
        cliente = txt(dados.get("cliente"), "cliente")
        servico = txt(dados.get("servico"), "serviço selecionado")
        if aqua:
            return [
                f"A Aqua Gestão apresenta ao <b>{cliente}</b> esta proposta para <b>{servico}</b>, com atuação organizada, registros digitais e acompanhamento compatível com as necessidades informadas.",
                "Nosso objetivo é entregar segurança operacional, rastreabilidade e clareza para a administração, mantendo histórico das atividades e comunicação objetiva sobre as condições observadas.",
            ]
        return [
            f"A Bem Star Piscinas apresenta ao <b>{cliente}</b> esta proposta para <b>{servico}</b>, com atendimento profissional, organização operacional e acompanhamento próximo do cliente.",
            "Nosso objetivo é oferecer uma solução prática, confiável e transparente, com execução cuidadosa e comunicação ágil durante todo o atendimento.",
        ]

    def escopo_completo():
        servico_norm = normalizar_texto_busca(dados.get("servico"))
        frequencia = _crm_texto(dados.get("frequencia"))
        itens = []
        if frequencia:
            itens.append(f"Atendimento previsto: {frequencia}.")
        if aqua and "manutencao operacional" in servico_norm:
            itens += [
                "Limpeza física, aspiração, escovação e cuidados operacionais compatíveis com a rotina contratada.",
                "Análise e acompanhamento dos parâmetros físico-químicos aplicáveis à piscina.",
                "Dosagem operacional e ajustes com os produtos disponibilizados conforme a condição comercial.",
                "Verificação visual da piscina, sistema de filtração e casa de máquinas.",
                "Registro digital das visitas, serviços realizados e ocorrências identificadas.",
                "Comunicação à administração quando houver necessidade de correção, manutenção ou intervenção específica.",
            ]
        else:
            itens += _crm_escopo_proposta(empresa_codigo, _crm_texto(dados.get("servico")))
        return itens

    def diferenciais():
        if aqua:
            return [
                "Atuação especializada em piscinas coletivas e controle técnico da água.",
                "Profissional habilitado e registrado no CRQ-MG, quando aplicável ao serviço contratado.",
                "Sistema informatizado próprio, com histórico e rastreabilidade dos atendimentos.",
                "Relatórios padronizados e comunicação objetiva com síndicos e administradoras.",
                "Separação clara entre serviço operacional e Responsabilidade Técnica.",
            ]
        return [
            "Experiência prática em manutenção, recuperação e soluções para piscinas.",
            "Equipe de campo treinada e atendimento próximo ao cliente.",
            "Registro organizado dos serviços e comunicação ágil sobre ocorrências.",
            "Suporte na escolha de produtos, equipamentos e soluções adequadas.",
        ]

    def lista_itens(itens):
        resultado = []
        for item in itens:
            resultado += [Paragraph(f"<font color='#D7A719'>-</font> {escape(item)}", corpo_esq), Spacer(1, 1.2 * mm)]
        return resultado

    def rodape(canvas, doc_obj):
        canvas.saveState()
        canvas.setStrokeColor(dourado)
        canvas.setLineWidth(0.7)
        canvas.line(15 * mm, 12 * mm, 195 * mm, 12 * mm)
        canvas.setFillColor(cinza)
        canvas.setFont(fonte, 7)
        canvas.drawString(15 * mm, 8 * mm, f"{assinatura_empresa} | CNPJ {cnpj_empresa} | Uberlândia/MG")
        canvas.drawRightString(195 * mm, 8 * mm, f"Proposta {txt(dados.get('numero'))} | Página {canvas.getPageNumber()}")
        canvas.restoreState()

    buffer = io.BytesIO()
    doc = SimpleDocTemplate(
        buffer, pagesize=A4, leftMargin=15 * mm, rightMargin=15 * mm,
        topMargin=14 * mm, bottomMargin=18 * mm,
        title=f"Proposta Comercial {_crm_texto(dados.get('numero'))}",
        author=assinatura_empresa,
    )
    story = [cabecalho_capa(), Spacer(1, 7 * mm), tabela_cliente(), Spacer(1, 6 * mm)]

    story += secao_titulo("APRESENTAÇÃO")
    for paragrafo in apresentacao_texto():
        story.append(Paragraph(paragrafo, corpo))

    story += secao_titulo("ESCOPO DOS SERVIÇOS")
    story.append(Paragraph(
        f"<b>Modalidade:</b> {txt(dados.get('servico'))}<br/>"
        f"<b>Local / piscina:</b> {txt(dados.get('piscinas'))}",
        corpo_esq,
    ))
    story += lista_itens(escopo_completo())
    story.append(PageBreak())

    valor_num = _crm_valor_numero(dados.get("valor"))
    valor_exibicao = _crm_moeda(valor_num) if valor_num else txt(dados.get("valor"))
    story += secao_titulo("INVESTIMENTO")
    investimento = Table([
        [Paragraph("SERVIÇO CONTRATADO", rotulo_branco), Paragraph("INVESTIMENTO", rotulo_branco)],
        [Paragraph(
            f"<b>{txt(dados.get('servico'))}</b><br/>"
            f"<font size='8'>{txt(dados.get('frequencia'))}</font>", corpo_esq),
         Paragraph(valor_exibicao, valor_estilo)],
    ], colWidths=[120 * mm, 60 * mm])
    investimento.setStyle(TableStyle([
        ("BACKGROUND", (0, 0), (-1, 0), azul_escuro),
        ("TEXTCOLOR", (0, 0), (-1, 0), branco),
        ("BOX", (0, 0), (-1, -1), 0.8, borda),
        ("INNERGRID", (0, 0), (-1, -1), 0.4, borda),
        ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
        ("LEFTPADDING", (0, 0), (-1, -1), 9),
        ("RIGHTPADDING", (0, 0), (-1, -1), 9),
        ("TOPPADDING", (0, 0), (-1, -1), 8),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 8),
    ]))
    story += [investimento, Spacer(1, 4 * mm)]

    condicoes = Table([
        linha_cliente("Forma de pagamento", dados.get("pagamento")),
        linha_cliente("Vencimento", dados.get("vencimento")),
        linha_cliente("Produtos / materiais", dados.get("produtos")),
        linha_cliente("Validade da proposta", dados.get("validade")),
    ], colWidths=[52 * mm, 128 * mm])
    condicoes.setStyle(TableStyle([
        ("BOX", (0, 0), (-1, -1), 0.6, borda),
        ("INNERGRID", (0, 0), (-1, -1), 0.35, borda),
        ("BACKGROUND", (0, 0), (0, -1), azul_claro),
        ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
        ("LEFTPADDING", (0, 0), (-1, -1), 7),
        ("RIGHTPADDING", (0, 0), (-1, -1), 7),
        ("TOPPADDING", (0, 0), (-1, -1), 5.5),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 5.5),
    ]))
    story += [condicoes, Spacer(1, 5 * mm)]

    story += secao_titulo(f"DIFERENCIAIS {marca_txt}")
    story += lista_itens(diferenciais())

    story += secao_titulo("CONDIÇÕES E OBSERVAÇÕES")
    observacoes = _crm_texto(dados.get("observacoes"))
    if observacoes:
        story.append(Paragraph(escape(observacoes).replace("\n", "<br/>"), corpo))
    else:
        story.append(Paragraph(
            "O início dos serviços, o cronograma e os detalhes finais serão confirmados após o aceite. "
            "Serviços, materiais ou intervenções não descritos nesta proposta serão avaliados e orçados separadamente.",
            corpo,
        ))
    produtos_txt = normalizar_texto_busca(dados.get("produtos"))
    servico_norm = normalizar_texto_busca(dados.get("servico"))
    if "nao inclus" in produtos_txt:
        story.append(Paragraph("Os produtos químicos, materiais e equipamentos não estão incluídos no investimento apresentado.", corpo))
    if aqua and "manutencao operacional" in servico_norm:
        story.append(Paragraph(
            "Esta modalidade possui caráter operacional e não inclui Responsabilidade Técnica, emissão de ART ou documentos privativos de RT, salvo contratação específica em separado.",
            corpo,
        ))

    story += [Spacer(1, 3 * mm), Paragraph(
        "Ficamos à disposição para esclarecimentos e para o planejamento do início dos trabalhos.", corpo_esq,
    ), Spacer(1, 9 * mm)]
    assinatura = Table([
        [Paragraph("________________________________________<br/><b>CONTRATANTE</b><br/><font size='7'>Nome, assinatura e data</font>", centro),
         Paragraph(f"________________________________________<br/><b>{escape(assinatura_empresa)}</b><br/><font size='7'>Responsável comercial</font>", centro)],
    ], colWidths=[90 * mm, 90 * mm])
    assinatura.setStyle(TableStyle([("VALIGN", (0, 0), (-1, -1), "TOP")]))
    story.append(KeepTogether(assinatura))

    doc.build(story, onFirstPage=rodape, onLaterPages=rodape)
    return buffer.getvalue()


def gerar_contrato_crm_pdf(dados: dict) -> bytes:
    """Gera contrato comercial pelo CRM sem alterar os geradores tradicionais."""
    import io
    from xml.sax.saxutils import escape
    from reportlab.lib import colors
    from reportlab.lib.enums import TA_CENTER, TA_JUSTIFY, TA_LEFT
    from reportlab.lib.pagesizes import A4
    from reportlab.lib.styles import ParagraphStyle
    from reportlab.lib.units import mm
    import reportlab
    from reportlab.pdfbase import pdfmetrics
    from reportlab.pdfbase.ttfonts import TTFont
    from reportlab.platypus import (
        SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle,
        PageBreak, KeepTogether, HRFlowable, Image as RLImage,
    )

    empresa_codigo = _crm_texto(dados.get("empresa_codigo"))
    aqua = empresa_codigo == "aqua_gestao"
    empresa = "Aqua Gestão" if aqua else "Bem Star Piscinas"
    marca_txt = "ACQUA GESTÃO" if aqua else empresa.upper()  # grafia aprovada da marca
    razao = "AQUA GESTÃO CONTROLE TÉCNICO LTDA" if aqua else "BEM STAR PISCINAS LTDA"
    cnpj = "66.008.795/0001-92" if aqua else "26.799.958/0001-88"
    endereco_empresa = "Uberlândia/MG" if aqua else "Av. Getúlio Vargas, 4411, Jardim das Palmeiras, Uberlândia/MG"
    assinatura_empresa = "Aqua Gestão - Controle Técnico de Piscinas" if aqua else "Bem Star Piscinas Ltda."
    azul_escuro = colors.HexColor("#07182E") if aqua else colors.HexColor("#082B57")
    azul = colors.HexColor("#0B4F83") if aqua else colors.HexColor("#12579B")
    dourado = colors.HexColor("#D7A719")
    azul_claro = colors.HexColor("#EEF5FB")
    cinza = colors.HexColor("#526174")
    borda = colors.HexColor("#C9D5E3")
    texto_cor = colors.HexColor("#152235")

    fonte = "Helvetica"
    fonte_bold = "Helvetica-Bold"
    try:
        reportlab_dir = Path(reportlab.__file__).resolve().parent
        fonte_regular_path = reportlab_dir / "fonts" / "Vera.ttf"
        fonte_bold_path = reportlab_dir / "fonts" / "VeraBd.ttf"
        if not (fonte_regular_path.exists() and fonte_bold_path.exists()):
            fonte_regular_path = Path("/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf")
            fonte_bold_path = Path("/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf")
        if fonte_regular_path.exists() and fonte_bold_path.exists():
            if "CRMContrato" not in pdfmetrics.getRegisteredFontNames():
                pdfmetrics.registerFont(TTFont("CRMContrato", str(fonte_regular_path)))
            if "CRMContrato-Bold" not in pdfmetrics.getRegisteredFontNames():
                pdfmetrics.registerFont(TTFont("CRMContrato-Bold", str(fonte_bold_path)))
            fonte = "CRMContrato"
            fonte_bold = "CRMContrato-Bold"
    except Exception:
        pass

    corpo = ParagraphStyle(
        "CRMContratoCorpo", fontName=fonte, fontSize=8.7, leading=13.2,
        textColor=texto_cor, alignment=TA_JUSTIFY, spaceAfter=2.2 * mm,
    )
    corpo_esq = ParagraphStyle("CRMContratoEsq", parent=corpo, alignment=TA_LEFT)
    pequeno = ParagraphStyle(
        "CRMContratoPequeno", parent=corpo_esq, fontSize=7.1, leading=9.5,
        textColor=cinza, spaceAfter=0,
    )
    titulo = ParagraphStyle(
        "CRMContratoTitulo", parent=corpo_esq, fontName=fonte_bold,
        fontSize=17, leading=21, textColor=colors.white, alignment=TA_CENTER,
    )
    secao = ParagraphStyle(
        "CRMContratoSecao", parent=corpo_esq, fontName=fonte_bold,
        fontSize=10.5, leading=13.5, textColor=azul_escuro,
        spaceBefore=2.2 * mm, spaceAfter=1.5 * mm,
    )
    rotulo = ParagraphStyle(
        "CRMContratoRotulo", parent=corpo_esq, fontName=fonte_bold,
        fontSize=7.7, leading=10, textColor=azul_escuro, spaceAfter=0,
    )
    centro = ParagraphStyle("CRMContratoCentro", parent=corpo_esq, alignment=TA_CENTER)

    def txt(valor, padrao="Não informado"):
        valor = _crm_texto(valor)
        return escape(valor) if valor else padrao

    def titulo_clausula(numero, nome):
        return [
            Paragraph(f"CLÁUSULA {numero} — {nome}", secao),
            HRFlowable(width="100%", thickness=0.65, color=dourado, spaceAfter=1.8 * mm),
        ]

    numero = txt(dados.get("numero"), "Sem referência")
    cliente = txt(dados.get("cliente"))
    tipo_cliente = _crm_texto(dados.get("tipo_cliente")) or "Condomínio"
    residencial = normalizar_texto_busca(tipo_cliente) == "residencial"
    documento = txt(dados.get("documento"))
    responsavel = txt(dados.get("responsavel"))
    doc_responsavel = txt(dados.get("documento_responsavel"))
    rg = txt(dados.get("rg"))
    endereco_completo = " - ".join(
        x for x in [_crm_texto(dados.get("endereco")), _crm_texto(dados.get("cidade"))] if x
    )
    endereco_completo = escape(endereco_completo) if endereco_completo else "Não informado"
    telefone = txt(dados.get("telefone"))
    email = txt(dados.get("email"))
    servico = txt(dados.get("servico"))
    frequencia = txt(dados.get("frequencia"))
    piscinas = txt(dados.get("piscinas"), "Local e piscina(s) conforme vistoria e proposta comercial")
    produtos = txt(dados.get("produtos"))
    valor = txt(dados.get("valor"))
    natureza_valor = txt(dados.get("natureza_valor"), "mensal")
    pagamento = txt(dados.get("pagamento"))
    vencimento = txt(dados.get("vencimento"))
    primeiro_vencimento = txt(dados.get("primeiro_vencimento"))
    inicio = txt(dados.get("inicio"))
    fim = txt(dados.get("fim"))
    renovacao = txt(dados.get("renovacao"), "mediante acordo entre as partes")
    observacoes = _crm_texto(dados.get("observacoes"))
    servico_norm = normalizar_texto_busca(dados.get("servico"))
    manutencao_operacional_aqua = aqua and "manutencao operacional" in servico_norm
    manutencao_bem_star = (not aqua) and "manutencao" in servico_norm

    if residencial:
        qualificacao = (
            f"{cliente}, pessoa física, inscrita no CPF sob nº {documento}, RG nº {rg}, "
            f"residente e domiciliada em {endereco_completo}, telefone {telefone}, e-mail {email}, "
            "doravante denominada CONTRATANTE"
        )
        representante_tabela = "Não aplicável — contratação residencial"
    else:
        qualificacao = (
            f"{cliente}, inscrita no CPF/CNPJ sob nº {documento}, estabelecida em {endereco_completo}, "
            f"neste ato representada por {responsavel}, CPF nº {doc_responsavel}, telefone {telefone}, "
            f"e-mail {email}, doravante denominada CONTRATANTE"
        )
        representante_tabela = f"{responsavel}\nCPF: {doc_responsavel}"

    escopo = _crm_escopo_proposta(empresa_codigo, _crm_texto(dados.get("servico")))
    if manutencao_operacional_aqua:
        escopo = [
            "Limpeza física, aspiração, escovação, peneiração e cuidados operacionais previstos na rotina contratada.",
            "Análise e ajuste operacional dos parâmetros físico-químicos aplicáveis em cada visita.",
            "Verificação visual da piscina, filtração, circulação e casa de máquinas.",
            "Registro digital dos serviços e comunicação de ocorrências ao contratante.",
            "Atuação estritamente operacional, sem Responsabilidade Técnica ou ART incluída.",
        ]

    def cabecalho():
        logo = None
        try:
            logo_path = encontrar_logo() if aqua else encontrar_logo_bem_star()
            if logo_path:
                logo = RLImage(str(logo_path), width=29 * mm, height=20 * mm, kind="proportional")
        except Exception:
            logo = None
        marca = Paragraph(
            f"<b>{escape(marca_txt)}</b><br/><font size='7' color='#D7A719'>{escape(assinatura_empresa)}</font>",
            ParagraphStyle("CRMContratoMarca", parent=centro, fontName=fonte_bold, fontSize=15, leading=18, textColor=colors.white),
        )
        esquerda = Table([[logo, marca]], colWidths=[34 * mm, 75 * mm]) if logo else marca
        if isinstance(esquerda, Table):
            esquerda.setStyle(TableStyle([
                ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
                ("LEFTPADDING", (0, 0), (-1, -1), 0),
                ("RIGHTPADDING", (0, 0), (-1, -1), 3),
            ]))
        direita = Paragraph(f"CONTRATO DE PRESTAÇÃO<br/>DE SERVIÇOS<br/><font size='8'>{numero}</font>", titulo)
        tabela = Table([[esquerda, direita]], colWidths=[110 * mm, 70 * mm], rowHeights=[37 * mm])
        tabela.setStyle(TableStyle([
            ("BACKGROUND", (0, 0), (-1, -1), azul_escuro),
            ("LINEBELOW", (0, 0), (-1, -1), 1.8, dourado),
            ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
            ("LEFTPADDING", (0, 0), (-1, -1), 9),
            ("RIGHTPADDING", (0, 0), (-1, -1), 9),
        ]))
        return tabela

    def rodape(canvas, doc_obj):
        canvas.saveState()
        canvas.setStrokeColor(dourado)
        canvas.setLineWidth(0.7)
        canvas.line(15 * mm, 12 * mm, 195 * mm, 12 * mm)
        canvas.setFillColor(cinza)
        canvas.setFont(fonte, 6.8)
        canvas.drawString(15 * mm, 8 * mm, f"{assinatura_empresa} | CNPJ {cnpj} | Uberlândia/MG")
        canvas.drawRightString(195 * mm, 8 * mm, f"Contrato {numero} | Página {canvas.getPageNumber()}")
        canvas.restoreState()

    buffer = io.BytesIO()
    doc = SimpleDocTemplate(
        buffer, pagesize=A4, leftMargin=15 * mm, rightMargin=15 * mm,
        topMargin=14 * mm, bottomMargin=18 * mm,
        title=f"Contrato {numero}", author=assinatura_empresa,
    )
    story = [cabecalho(), Spacer(1, 6 * mm)]

    identificacao = Table([
        [Paragraph("CONTRATADA", rotulo), Paragraph(f"<b>{razao}</b><br/>CNPJ {cnpj}<br/>{escape(endereco_empresa)}", corpo_esq)],
        [Paragraph("CONTRATANTE", rotulo), Paragraph(f"<b>{cliente}</b><br/>Tipo: {escape(tipo_cliente)}<br/>CPF/CNPJ: {documento}<br/>Endereço: {endereco_completo}", corpo_esq)],
        [Paragraph("REPRESENTANTE", rotulo), Paragraph(escape(representante_tabela).replace("\n", "<br/>"), corpo_esq)],
        [Paragraph("SERVIÇO", rotulo), Paragraph(f"{servico}<br/>Frequência/prazo: {frequencia}<br/>Local/piscina(s): {piscinas}", corpo_esq)],
        [Paragraph("CONDIÇÕES", rotulo), Paragraph(f"Valor {natureza_valor}: {valor}<br/>Primeiro vencimento: {primeiro_vencimento}<br/>Demais vencimentos: {vencimento}<br/>Pagamento: {pagamento}", corpo_esq)],
    ], colWidths=[42 * mm, 138 * mm])
    identificacao.setStyle(TableStyle([
        ("BOX", (0, 0), (-1, -1), 0.7, borda),
        ("INNERGRID", (0, 0), (-1, -1), 0.35, borda),
        ("BACKGROUND", (0, 0), (0, -1), azul_claro),
        ("VALIGN", (0, 0), (-1, -1), "TOP"),
        ("LEFTPADDING", (0, 0), (-1, -1), 7),
        ("RIGHTPADDING", (0, 0), (-1, -1), 7),
        ("TOPPADDING", (0, 0), (-1, -1), 6),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 6),
    ]))
    story += [identificacao, Spacer(1, 5 * mm)]
    story.append(Paragraph(
        f"Pelo presente instrumento particular, de um lado {razao}, inscrita no CNPJ sob nº {cnpj}, "
        f"doravante denominada CONTRATADA; e, de outro, {qualificacao}, resolvem celebrar o presente contrato, "
        "vinculado à proposta comercial informada no CRM, mediante as cláusulas seguintes.", corpo,
    ))
    story.append(PageBreak())

    story += titulo_clausula("1", "DO OBJETO E DO ESCOPO")
    story.append(Paragraph(f"O presente contrato tem por objeto a prestação do serviço de <b>{servico}</b>, no local indicado pela CONTRATANTE.", corpo))
    for item in escopo:
        story.append(Paragraph(f"• {escape(item)}", corpo_esq))

    story += titulo_clausula("2", "DA EXECUÇÃO E DA FREQUÊNCIA")
    story.append(Paragraph(
        f"Os serviços serão executados conforme a frequência, prazo ou entrega definida: <b>{frequencia}</b>. "
        "Datas e horários poderão ser ajustados por necessidade operacional, climática, feriados, impedimento de acesso, "
        "caso fortuito ou força maior, com comunicação ao CONTRATANTE. Atividades extraordinárias ou fora do escopo serão avaliadas separadamente.", corpo,
    ))

    story += titulo_clausula("3", "DOS PRODUTOS, MATERIAIS E EQUIPAMENTOS")
    story.append(Paragraph(
        f"A condição comercial dos produtos e materiais é: <b>{produtos}</b>. Itens extraordinários, reposições por contaminação, "
        "eventos, drenagens, falhas estruturais, mau uso, peças e intervenções não previstas dependerão de autorização e orçamento específico.", corpo,
    ))

    story += titulo_clausula("4", "DO VALOR E DO PAGAMENTO")
    story.append(Paragraph(
        f"Pelos serviços contratados, a CONTRATANTE pagará à CONTRATADA o valor <b>{natureza_valor} de {valor}</b>. "
        f"O primeiro vencimento ocorrerá em <b>{primeiro_vencimento}</b>; os demais, em <b>{vencimento}</b>, mediante {pagamento}. "
        "O atraso sujeitará a CONTRATANTE à multa de 2%, juros de mora de 1% ao mês pro rata die e correção monetária pelo índice oficial aplicável.", corpo,
    ))

    story += titulo_clausula("5", "DA VIGÊNCIA E DA RENOVAÇÃO")
    story.append(Paragraph(
        f"A vigência terá início em <b>{inicio}</b> e término em <b>{fim}</b>. A renovação ocorrerá {renovacao}. "
        "Quando o contrato ultrapassar 12 meses, o valor poderá ser reajustado anualmente pelo IPCA/IBGE ou índice que o substitua.", corpo,
    ))

    story += titulo_clausula("6", "DAS OBRIGAÇÕES DAS PARTES")
    story.append(Paragraph(
        "A CONTRATADA executará o escopo com zelo, boa-fé e organização, registrando ou comunicando ocorrências relevantes. "
        "A CONTRATANTE garantirá acesso ao local, fornecerá informações corretas, comunicará alterações de uso ou eventos, "
        "manterá instalações e equipamentos em condições de operação e efetuará os pagamentos nos prazos pactuados.", corpo,
    ))

    story += titulo_clausula("7", "DOS LIMITES DO SERVIÇO E DA RESPONSABILIDADE")
    limite = (
        "A modalidade contratada possui natureza operacional e não inclui Responsabilidade Técnica química, ART, laudos periciais ou documentos privativos de RT, salvo contratação específica e independente. "
        if manutencao_operacional_aqua or manutencao_bem_star else
        "A contratação limita-se ao escopo expressamente descrito e não inclui Responsabilidade Técnica ou ART, salvo quando o objeto específico e documento próprio dispuserem de forma diferente. "
    )
    story.append(Paragraph(
        limite + "Não estão incluídas obras civis, reformas hidráulicas, reparos elétricos, falhas estruturais, substituição de equipamentos, "
        "danos por mau uso, intervenção de terceiros, vandalismo, intempéries ou situações não atribuíveis à execução direta da CONTRATADA.", corpo,
    ))

    story += titulo_clausula("8", "DA RESCISÃO")
    story.append(Paragraph(
        "O contrato poderá ser rescindido por mútuo acordo; por qualquer das partes mediante aviso prévio escrito de 30 dias; "
        "ou imediatamente após descumprimento contratual relevante não sanado após comunicação. Permanecem devidos os valores vencidos, "
        "serviços prestados, materiais utilizados e obrigações constituídas até o encerramento.", corpo,
    ))

    clausula_nove = titulo_clausula("9", "DA PROTEÇÃO DE DADOS, COMUNICAÇÕES E DISPOSIÇÕES GERAIS")
    clausula_nove.append(Paragraph(
        "Os dados fornecidos serão utilizados para execução contratual, comunicação operacional, cobrança e registros administrativos. "
        "E-mails, mensagens eletrônicas, registros digitais, relatórios e documentos assinados física ou eletronicamente serão meios válidos de comunicação e prova. "
        "Alterações relevantes de escopo, frequência, prazo ou preço deverão ser formalizadas por escrito.", corpo,
    ))
    if observacoes:
        clausula_nove.append(Paragraph(f"<b>Condições adicionais:</b> {escape(observacoes).replace(chr(10), '<br/>')}", corpo))
    story.append(KeepTogether(clausula_nove))

    story += titulo_clausula("10", "DO FORO")
    story.append(Paragraph(
        "Fica eleito o foro da Comarca de Uberlândia/MG para dirimir controvérsias oriundas deste instrumento, "
        "com renúncia a qualquer outro, por mais privilegiado que seja.", corpo,
    ))

    story += [Spacer(1, 5 * mm), Paragraph(
        f"Uberlândia/MG, {txt(dados.get('data_assinatura'))}.", centro,
    ), Spacer(1, 10 * mm)]
    assinatura_cliente = cliente if residencial else f"{cliente}<br/><font size='7'>Representante: {responsavel}</font>"
    assinaturas = Table([
        [Paragraph("________________________________________<br/><b>CONTRATADA</b><br/>" + escape(razao), centro),
         Paragraph("________________________________________<br/><b>CONTRATANTE</b><br/>" + assinatura_cliente, centro)],
        [Spacer(1, 7 * mm), Spacer(1, 7 * mm)],
        [Paragraph("________________________________________<br/><b>TESTEMUNHA 1</b><br/><font size='7'>Nome e CPF</font>", centro),
         Paragraph("________________________________________<br/><b>TESTEMUNHA 2</b><br/><font size='7'>Nome e CPF</font>", centro)],
    ], colWidths=[90 * mm, 90 * mm])
    assinaturas.setStyle(TableStyle([
        ("VALIGN", (0, 0), (-1, -1), "TOP"),
        ("ALIGN", (0, 0), (-1, -1), "CENTER"),
    ]))
    story.append(KeepTogether(assinaturas))

    doc.build(story, onFirstPage=rodape, onLaterPages=rodape)
    return buffer.getvalue()


def limpar_payload_para_sheets(dados: dict) -> dict:
    """Remove campos pesados antes de salvar payload no Google Sheets.

    O Google Sheets limita cada célula a 50.000 caracteres.
    Fotos/base64/assinaturas/canvas não devem ser salvos em célula.
    """
    if not isinstance(dados, dict):
        return {}

    proibidos = {
        "foto", "fotos", "imagem", "imagens", "image", "images",
        "base64", "bytes", "arquivo", "arquivos", "upload",
        "assinatura", "assinatura_base64", "signature",
        "canvas", "drawing", "pdf", "html"
    }

    limpo = {}

    for k, v in dados.items():
        chave = str(k).lower()

        if any(p in chave for p in proibidos):
            continue

        if isinstance(v, dict):
            limpo[k] = limpar_payload_para_sheets(v)

        elif isinstance(v, list):
            nova_lista = []
            for item in v:
                if isinstance(item, dict):
                    nova_lista.append(limpar_payload_para_sheets(item))
                else:
                    texto = str(item)
                    if len(texto) <= 1000:
                        nova_lista.append(item)
            limpo[k] = nova_lista

        else:
            texto = str(v)
            if len(texto) > 1000:
                limpo[k] = texto[:1000] + "..."
            else:
                limpo[k] = v

    return limpo


def sheets_salvar_lancamento_campo(lancamento: dict, nome_condominio: str):
    """Salva lançamento de campo na aba 🔬 Visitas do Google Sheets.

    Esta função é crítica para o relatório mensal: PDF de visita não alimenta relatório
    se a linha não for gravada no Sheets. Por isso, grava dados básicos e também um
    Payload JSON completo para preservar múltiplas piscinas, fotos e dosagens.
    """
    try:
        sh = conectar_sheets()
        if sh is None:
            return False

        # obter_aba_sheets devolve None (não exceção) quando a aba não existe:
        # numa planilha nova a visita nunca era gravada. Cria a aba nesse caso.
        try:
            aba = obter_aba_sheets("🔬 Visitas")
        except Exception:
            aba = None
        if aba is None:
            aba = sh.add_worksheet(title="🔬 Visitas", rows=1000, cols=26)
            try:
                obter_aba_sheets.clear()  # descarta o "aba ausente" guardado em cache
            except Exception:
                pass
            aba.update(
                "A1:Z1",
                [[
                    "", "ID Visita", "Data", "ID Cliente", "Condomínio",
                    "pH", "CRL", "CT", "Alcalinidade", "Dureza", "CYA",
                    "Foto Antes", "Foto Depois", "Foto Casa Máquinas", "Observação",
                    "Dosagem Cloro", "Dosagem Bicarb", "Alerta pH", "Alerta Cloro",
                    "Status", "Operador", "Problemas", "Payload JSON", "Salvo em",
                    "Fonte", "Mês/Ano",
                ]]
            )

        todos = aba.get_all_values()
        visitas_existentes = [
            r for r in todos
            if len(r) > 1 and str(r[1]).strip().startswith("V")
        ]
        proximo_num = len(visitas_existentes) + 1
        id_visita = f"V{proximo_num:05d}"

        data_normalizada = normalizar_data_visita(lancamento.get("data", ""))
        nome_condominio = str(nome_condominio or lancamento.get("condominio", "")).strip()

        # Busca ID do cliente por nome normalizado
        id_cliente = ""
        try:
            aba_clientes = obter_aba_sheets("👥 Clientes")
            clientes = aba_clientes.get_all_values()
            for row in clientes:
                if len(row) > 2 and nomes_condominio_equivalentes(nome_condominio, row[2]):
                    id_cliente = row[1]
                    break
        except Exception:
            id_cliente = ""

        # Se houver múltiplas piscinas, grava os parâmetros principais com a primeira piscina,
        # mas conserva tudo no Payload JSON.
        piscinas = lancamento.get("piscinas", []) or []
        base_param = piscinas[0] if isinstance(piscinas, list) and piscinas and isinstance(piscinas[0], dict) else lancamento

        dosagem_txt = _montar_resumo_dosagens_lancamento(lancamento)

        # Payload para Google Sheets: mantém dados técnicos, nomes e IDs das fotos,
        # mas remove base64/bytes para não estourar o limite de célula do Sheets.
        payload = dict(lancamento)
        for _k_payload in list(payload.keys()):
            _k_norm = str(_k_payload).lower()
            if (
                _k_norm.endswith("_b64")
                or _k_norm.endswith("_base64")
                or "base64" in _k_norm
                or "bytes" in _k_norm
            ):
                payload.pop(_k_payload, None)

        payload["data"] = data_normalizada
        payload["condominio"] = nome_condominio
        payload["id_visita"] = id_visita
        payload["status"] = payload.get("status", "Concluída")
        try:
            payload_json = json.dumps(payload, ensure_ascii=False)
        except Exception:
            payload_json = ""

        mes_ano = ""
        try:
            dt = datetime.strptime(data_normalizada, "%d/%m/%Y")
            mes_ano = dt.strftime("%m/%Y")
        except Exception:
            pass

        nova_linha = [
            "",                                      # A
            id_visita,                               # B
            data_normalizada,                        # C
            id_cliente,                              # D
            nome_condominio,                         # E
            base_param.get("ph", lancamento.get("ph", "")),
            base_param.get("cloro_livre", lancamento.get("cloro_livre", "")),
            base_param.get("cloro_total", lancamento.get("cloro_total", "")),
            base_param.get("alcalinidade", lancamento.get("alcalinidade", "")),
            base_param.get("dureza", lancamento.get("dureza", "")),
            base_param.get("cianurico", lancamento.get("cianurico", "")),
            "",                                      # L foto antes
            "",                                      # M foto depois
            "",                                      # N foto casa máquinas
            lancamento.get("observacao", ""),        # O
            dosagem_txt,                              # P
            "", "", "",                              # Q/R/S
            "Concluída",                             # T
            lancamento.get("operador", ""),          # U
            lancamento.get("problemas", ""),         # V
            payload_json,                             # W
            _agora_brasilia(),
            "Modo Campo",                             # Y
            mes_ano,                                  # Z
        ]

        linha_destino = max(len(todos) + 1, 8)
        aba.update(
            f"A{linha_destino}:Z{linha_destino}",
            [nova_linha],
            value_input_option="RAW"
        )
        # O chamador grava a cópia local com este ID: sem ele, a mesma visita
        # aparecia duas vezes no relatório mensal (local sem ID + Sheets com ID).
        lancamento["id_visita"] = id_visita
        st.cache_data.clear()
        return True

    except Exception as e:
        _log_sheets_erro("sheets_salvar_lancamento_campo", e)
        return False


def sheets_salvar_cliente(nome: str, cnpj: str, endereco: str, contato: str, telefone: str,
                           vol_adulto: float = 0, vol_infantil: float = 0, vol_family: float = 0,
                           empresa: str = "Aqua Gestão", cep: str = "", piscinas_cadastro: str | None = None):
    """Salva novo cliente na aba Clientes do Google Sheets.
    
    Insere sempre logo após o último cliente real (C001, C002...),
    mantendo a formatação da planilha com cabeçalho e linha de total intactos.
    Colunas J/K/L = Vol_Adulto_m3, Vol_Infantil_m3, Vol_Family_m3
    """
    try:
        import re as _re

        sh = conectar_sheets()
        if sh is None:
            return False

        aba = obter_aba_sheets("👥 Clientes")
        todos = aba.get_all_values()

        # Identifica linhas reais de clientes: col B começa com C + dígitos
        ultima_linha_cliente = 0  # índice 0-based
        nums = []
        nomes_existentes = []

        for i, row in enumerate(todos):
            if len(row) > 2:
                id_val = str(row[1]).strip()
                nome_val = str(row[2]).strip()
                if _re.match(r"^C[0-9]+$", id_val) and nome_val:
                    ultima_linha_cliente = i
                    nomes_existentes.append(nome_val.lower())
                    m = _re.match(r"^C([0-9]+)$", id_val)
                    if m:
                        nums.append(int(m.group(1)))

        # Verifica duplicata
        if nome.lower().strip() in nomes_existentes:
            # Não sobrescrever cadastro local de cliente já existente.
            try:
                st.session_state["_cc_erro_salvar"] = "Já existe um cliente com esse nome. Use Editar cliente existente."
            except Exception:
                pass
            return False

        # Próximo ID baseado no maior existente
        proximo_num = (max(nums) + 1) if nums else 1
        id_cliente = f"C{proximo_num:03d}"

        vol_total = (vol_adulto or 0) + (vol_infantil or 0) + (vol_family or 0)
        _meta_piscinas = ler_piscinas_cadastro(piscinas_cadastro)
        if _meta_piscinas is not None:
            vol_total += sum(volume_cadastro(p.get("vol")) for p in _meta_piscinas["extras"])
        nova_linha = [
            "",                                    # A - vazia
            id_cliente,                            # B - ID
            nome,                                  # C - Nome
            str(vol_total) if vol_total else "",   # D - Volume total m3
            formatar_telefone(telefone),           # E - Telefone
            contato,                               # F - Contato síndico
            endereco,                              # G - Endereço
            datetime.now().strftime("%Y-%m-%d"),   # H - Data cadastro
            "Ativo",                               # I - Status
            str(vol_adulto) if vol_adulto else "", # J - Vol Adulto m3
            str(vol_infantil) if vol_infantil else "", # K - Vol Infantil m3
            str(vol_family) if vol_family else "", # L - Vol Family m3
            empresa,                               # M - Empresa
            cnpj,                                  # N - CNPJ # _CNPJ_COLUNA_N_
            cep,                                   # O - CEP
        ]

        if piscinas_cadastro is not None:
            nova_linha.append(piscinas_cadastro)

        # Determina posicao alfabetica dentro do bloco de clientes
        nome_novo_lower = nome.lower().strip()
        linha_insercao = ultima_linha_cliente + 2  # fallback: final do bloco
        for i, row in enumerate(todos):
            if len(row) > 2:
                id_val2 = str(row[1]).strip()
                nome_val2 = str(row[2]).strip()
                if _re.match(r"^C[0-9]+$", id_val2) and nome_val2:
                    if nome_val2.lower().strip() > nome_novo_lower:
                        linha_insercao = i + 1
                        break
        if piscinas_cadastro is not None and getattr(aba, "col_count", 16) < 16:
            aba.add_cols(16 - aba.col_count)
        # USER_ENTERED como antes do PR: mantém a tipagem legada de volumes e data (H).
        aba.insert_row(nova_linha, linha_insercao, value_input_option="USER_ENTERED")
        st.cache_data.clear()
        return True
    except Exception as e:
        _log_sheets_erro("sheets_salvar_cliente", e)
        return False


@st.cache_data(ttl=45, show_spinner=False)
def sheets_listar_clientes() -> list[str]:
    """Retorna lista de nomes de clientes da aba Clientes."""
    try:
        sh = conectar_sheets()
        if sh is None:
            return []
        aba = obter_aba_sheets("👥 Clientes")
        todos = aba.get_all_values()
        nomes = []
        for row in todos:
            if len(row) > 2 and str(row[1]).startswith("C") and row[2].strip():
                nomes.append(row[2].strip())
        return nomes
    except Exception:
        return []


@st.cache_data(ttl=45, show_spinner=False)
def sheets_listar_clientes_completo() -> list[dict]:
    """Retorna lista de dicts com dados completos de cada cliente do Sheets.
    
    Mapeamento das colunas da planilha:
      B=ID, C=Nome, D=Volume_m3, E=Contato_Sindico/Telefone, 
      F=Email_Sindico, G=Endereco, H=Data_Cadastro, I=Status
    """
    import re as _re
    try:
        sh = conectar_sheets()
        if sh is None:
            return []
        aba = obter_aba_sheets("👥 Clientes")
        todos = aba.get_all_values()
        clientes = []
        for row in todos:
            if not row or len(row) < 3:
                continue
            id_val = str(row[1]).strip() if len(row) > 1 else ""
            if not _re.match(r"^C[0-9]+$", id_val):
                continue
            nome = str(row[2]).strip() if len(row) > 2 else ""
            if not nome:
                continue
            # Detecta se col E é telefone ou email
            col_e = str(row[4]).strip() if len(row) > 4 else ""
            col_f = str(row[5]).strip() if len(row) > 5 else ""
            # Se col_e tem @ é email do síndico; senão é telefone
            if "@" in col_e:
                telefone = ""
                contato  = ""
                email    = col_e
            else:
                telefone = formatar_telefone(col_e) if col_e else ""
                contato  = col_f if col_f else ""
                email    = ""
            # Volumes das piscinas (colunas J=9, K=10, L=11)
            def _vol(r, idx):
                try: return float(str(r[idx]).replace(",",".").strip() or 0) if len(r) > idx else 0.0
                except: return 0.0
            vol_adulto   = _vol(row, 9)
            vol_infantil = _vol(row, 10)
            vol_family   = _vol(row, 11)
            vol_total    = _vol(row, 3) or (vol_adulto + vol_infantil + vol_family)

            # Preserve vazio para cadastros legados. O filtro por empresa trata
            # cliente sem vínculo definido como legado e o disponibiliza nos
            # dois painéis; convertê-lo aqui para Aqua Gestão escondia esses
            # clientes do relatório Bem Star.
            _empresa_cl = str(row[12]).strip() if len(row) > 12 else ""
            _cnpj_cl = str(row[13]).strip() if len(row) > 13 else ""  # _CNPJ_LER_COLUNA_N_
            _cep_cl = str(row[14]).strip() if len(row) > 14 else ""
            cliente_base = {
                "id":           id_val,
                "nome":         nome,
                "cnpj":         _cnpj_cl,
                "cep":          _cep_cl,
                "telefone":     telefone,
                "contato":      contato,
                "email":        email,
                "endereco":     str(row[6]).strip() if len(row) > 6 else "",
                "status":       str(row[8]).strip() if len(row) > 8 else "Ativo",
                "vol_total":    vol_total,
                "vol_adulto":   vol_adulto,
                "vol_infantil": vol_infantil,
                "vol_family":   vol_family,
                "empresa":      _empresa_cl,
                "piscinas_extras": [],  # carregado do JSON local se disponível
            }
            try:
                _meta_piscinas = ler_piscinas_cadastro(row[15] if len(row) > 15 else "")
            except ValueError as _erro_piscinas_remotas:
                _meta_piscinas = None
                cliente_base["erro_cadastro_piscinas"] = str(_erro_piscinas_remotas)
            if _meta_piscinas is not None:
                cliente_base["cadastro_piscinas"] = _meta_piscinas
                cliente_base["tipos_piscinas"] = _meta_piscinas["tipos"]
                cliente_base["piscinas_extras"] = _meta_piscinas["extras"]
            clientes.append(_enriquecer_cliente_com_dados_locais(cliente_base))
        return clientes
    except Exception as e:
        _log_sheets_erro("sheets_listar_clientes_completo", e)
        return []


def sheets_editar_cliente(id_cliente: str, nome: str, cnpj: str, endereco: str,
                           contato: str, telefone: str,
                           vol_adulto: float = 0, vol_infantil: float = 0, vol_family: float = 0,
                           empresa: str = "", cep: str = "", piscinas_cadastro: str | None = None) -> bool:
    """Edita cliente existente na aba Clientes pelo ID."""
    import re as _re
    try:
        sh = conectar_sheets()
        if sh is None:
            return False
        aba = obter_aba_sheets("👥 Clientes")
        todos = aba.get_all_values()
        vol_total = (vol_adulto or 0) + (vol_infantil or 0) + (vol_family or 0)
        _meta_piscinas = ler_piscinas_cadastro(piscinas_cadastro)
        if _meta_piscinas is not None:
            vol_total += sum(volume_cadastro(p.get("vol")) for p in _meta_piscinas["extras"])
        for i, row in enumerate(todos):
            if len(row) > 1 and str(row[1]).strip() == id_cliente.strip():
                linha_sheets = i + 1
                # Preserva empresa existente se não informada
                _empresa_atual = str(row[12]).strip() if len(row) > 12 else ""
                _empresa_final = empresa if empresa else (_empresa_atual or "Aqua Gestão")
                # Um volume total legado sem distribuição não é atribuído a uma
                # piscina por inferência nem apagado ao informar apenas os tipos.
                if vol_total == 0 and not any(volume_cadastro(row[j]) for j in (9, 10, 11) if len(row) > j):
                    _antigo_meta = ler_piscinas_cadastro(row[15] if len(row) > 15 else "")
                    if not _antigo_meta or not _antigo_meta["extras"]:
                        vol_total = volume_cadastro(row[3] if len(row) > 3 else "")
                nova = [
                    "",
                    id_cliente,
                    nome,
                    str(vol_total) if vol_total else "",
                    formatar_telefone(telefone),
                    contato,
                    endereco,
                    str(row[7]).strip() if len(row) > 7 else datetime.now().strftime("%Y-%m-%d"),
                    str(row[8]).strip() if len(row) > 8 else "Ativo",
                    str(vol_adulto) if vol_adulto else "",
                    str(vol_infantil) if vol_infantil else "",
                    str(vol_family) if vol_family else "",
                    _empresa_final,                # M - Empresa
                    cnpj,                          # N - CNPJ
                    cep,                           # O - CEP
                ]
                _fim_coluna = "O"
                if piscinas_cadastro is not None:
                    ler_piscinas_cadastro(row[15] if len(row) > 15 else "")
                    nova.append(piscinas_cadastro)
                    _fim_coluna = "P"
                    if getattr(aba, "col_count", 16) < 16:
                        aba.add_cols(16 - aba.col_count)
                aba.update(range_name=f"A{linha_sheets}:{_fim_coluna}{linha_sheets}", values=[nova], value_input_option="USER_ENTERED")
                return True
        return False
    except Exception as e:
        _log_sheets_erro("sheets_editar_cliente", e)
        return False

def sheets_atualizar_cliente_empresa_status(id_cliente: str, empresa: str | None = None, status: str | None = None) -> bool:
    """Atualiza somente empresa (coluna M) e/ou status (coluna I) do cliente.

    Usado pela área administrativa para transferir cliente entre Aqua Gestão,
    Bem Star Piscinas ou Ambas, e para desativar sem apagar histórico.
    """
    try:
        id_limpo = str(id_cliente or "").strip()
        if not id_limpo:
            return False

        sh = conectar_sheets()
        if sh is None:
            return False
        aba = obter_aba_sheets("👥 Clientes")
        todos = aba.get_all_values()

        for i, row in enumerate(todos):
            if len(row) > 1 and str(row[1]).strip() == id_limpo:
                linha_sheets = i + 1

                if status is not None:
                    status_limpo = re.sub(r"\s+", " ", str(status or "").strip()) or "Ativo"
                    aba.update(
                        range_name=f"I{linha_sheets}:I{linha_sheets}",
                        values=[[status_limpo]],
                        value_input_option="USER_ENTERED",
                    )

                if empresa is not None:
                    empresa_limpa = re.sub(r"\s+", " ", str(empresa or "").strip()) or "Aqua Gestão"
                    aba.update(
                        range_name=f"M{linha_sheets}:M{linha_sheets}",
                        values=[[empresa_limpa]],
                        value_input_option="USER_ENTERED",
                    )

                st.cache_data.clear()
                return True

        return False
    except Exception as e:
        _log_sheets_erro("sheets_atualizar_cliente_empresa_status", e)
        return False


def sheets_carregar_cliente_por_nome(nome: str) -> dict:
    """Retorna dict com dados do cliente pelo nome (busca parcial)."""
    clientes = sheets_listar_clientes_completo()
    nome_lower = nome.lower().strip()
    for c in clientes:
        if c["nome"].lower().strip() == nome_lower:
            return c
    # Busca parcial
    for c in clientes:
        if nome_lower in c["nome"].lower():
            return c
    return {}


# =========================================
# GESTÃO DE OPERADORES
# =========================================

OPERADORES_JSON = None  # será inicializado após BASE_DIR

def _get_operadores_path():
    return BASE_DIR / "_operadores.json"

def carregar_operadores() -> list[dict]:
    """Carrega lista de operadores do arquivo JSON local."""
    try:
        p = _get_operadores_path()
        if p.exists():
            return json.loads(p.read_text(encoding="utf-8"))
        return []
    except Exception:
        return []

def salvar_operadores(lista: list):
    """Salva lista de operadores no arquivo JSON local."""
    try:
        p = _get_operadores_path()
        p.write_text(json.dumps(lista, ensure_ascii=False, indent=2), encoding="utf-8")
    except Exception:
        pass

def _secret_pin(secao: str, chave: str = "pin") -> str:
    """Lê um PIN do Streamlit Secrets. Retorna vazio quando não configurado
    (nesse caso o acesso correspondente fica desativado)."""
    try:
        return str(st.secrets.get(secao, {}).get(chave, "") or "").strip()
    except Exception:
        return ""


def _pin_confere(digitado, esperado) -> bool:
    """Compara PINs em tempo constante. PIN vazio nunca autentica."""
    digitado = str(digitado or "").strip()
    esperado = str(esperado or "").strip()
    if not digitado or not esperado:
        return False
    return hmac.compare_digest(digitado.encode("utf-8"), esperado.encode("utf-8"))


def _pin_mestre_operador() -> str:
    """PIN mestre do Modo Operador: somente Secrets [operador] pin_mestre."""
    return _secret_pin("operador", "pin_mestre")


def _pin_reservado(pin: str) -> bool:
    """Indica se o PIN coincide com o PIN mestre, do RT ou administrativo (sem expor valores)."""
    return any(_pin_confere(pin, p) for p in (_pin_mestre_operador(), _secret_pin("rt"), _secret_pin("admin")))


def validar_pin_operador(pin: str) -> dict | None:
    """Valida PIN do operador. Retorna dict do operador ou None se inválido.
    PINs especiais vêm exclusivamente do Streamlit Secrets: [rt] pin (Responsável Técnico)
    e [operador] pin_mestre (acesso geral). Sem o Secret, o acesso correspondente fica desativado."""
    pin_limpo = str(pin or "").strip()
    if not pin_limpo:
        return None
    # PIN do Responsável Técnico — lido do secrets [rt] pin
    if _pin_confere(pin_limpo, _secret_pin("rt")):
        return {
            "nome": "Thyago Fernando da Silveira",
            "pin": pin_limpo,
            "condomínios": ["TODOS"],
            "acesso_total": True,
            "is_rt": True,
        }
    # PIN mestre — somente quando configurado no Secrets
    if _pin_confere(pin_limpo, _pin_mestre_operador()):
        return {"nome": "Operador", "pin": pin_limpo, "condomínios": ["TODOS"], "acesso_total": True}
    # Busca nos operadores do Sheets
    try:
        operadores = sheets_listar_operadores()
        for op in operadores:
            if _pin_confere(pin_limpo, op.get("pin", "")) and op.get("ativo", True):
                op["condomínios"] = _condominios_organizar(op.get("condomínios", []))
                # Acesso total só com marcação explícita ("TODOS"); lista vazia não libera nada.
                op["acesso_total"] = op.get("acesso_total", False) or any(
                    _normalizar_chave_acesso(c) == "todos" for c in op["condomínios"]
                )
                return op
    except Exception:
        pass
    # Fallback: JSON local
    operadores_local = carregar_operadores()
    for op in operadores_local:
        if _pin_confere(pin_limpo, op.get("pin", "")) and op.get("ativo", True):
            op["condomínios"] = _condominios_organizar(op.get("condomínios", []))
            op["acesso_total"] = op.get("acesso_total", False) or any(
                _normalizar_chave_acesso(c) == "todos" for c in op["condomínios"]
            )
            return op
    return None

class _ClientesIndisponiveis(Exception):
    """O cadastro de clientes não pôde ser lido: sem ele não dá para confirmar a qual
    condomínio uma visita pertence."""


class _VisitasIndisponiveis(Exception):
    """A aba 🔬 Visitas não pôde ser lida: o resultado não é "nenhuma visita"."""


def _ler_cadastro_identificacao() -> list[dict]:
    """ID, nome e empresa dos cadastros da aba 👥 Clientes, para identificar visitas.

    Conta os clientes com ID (C + número, como no restante do app) e também linhas sem
    ID que tenham status ou empresa (cadastro incompleto), ativos ou não. Lança
    _ClientesIndisponiveis se a aba não puder ser lida — nunca devolve lista vazia
    no lugar de uma falha."""
    try:
        if conectar_sheets() is None:
            raise _ClientesIndisponiveis("sem conexão com a planilha")
        linhas = obter_aba_sheets("👥 Clientes").get_all_values()
    except _ClientesIndisponiveis:
        raise
    except Exception as e:
        raise _ClientesIndisponiveis(f"{type(e).__name__}: {e}") from e
    cadastro = []
    for row in linhas:
        _c = lambda i: str(row[i]).strip() if len(row) > i else ""  # noqa: E731
        id_cli, nome, status, empresa = _c(1), _c(2), _c(8), _c(12)
        if nome and (re.fullmatch(r"C[0-9]+", id_cli) or (not id_cli and (status or empresa))):
            cadastro.append({"id": id_cli, "nome": nome, "empresa": empresa})
    return cadastro


def _resolver_condominio_da_visita(alvo_n: str, linha_n: str, nomes_n: set) -> str:
    """Decide se uma visita (nome normalizado linha_n) pertence ao condomínio alvo_n.

    Retorna "sim", "nao" ou "ambigua". Nome igual vale sempre. Nome abreviado (um
    contido no outro, como "Aurora" e "Residencial Aurora") só vale quando corresponde
    a um único condomínio cadastrado; se for exatamente o nome de outro cadastro, não
    pertence; se corresponder a mais de um, é ambíguo e não é importado."""
    if not alvo_n or not linha_n:
        return "nao"
    if linha_n == alvo_n:
        return "sim"
    if not (linha_n in alvo_n or alvo_n in linha_n):
        return "nao"
    if linha_n in nomes_n:
        return "nao"  # é exatamente o nome de outro condomínio cadastrado
    candidatos = {n for n in (nomes_n | {alvo_n}) if n and (n in linha_n or linha_n in n)}
    return "sim" if candidatos == {alvo_n} else "ambigua"


@st.cache_data(ttl=45, show_spinner=False)
def _situacao_visitas_cache(nome_condominio: str) -> dict:
    """Visitas do condomínio na aba 🔬 Visitas e o motivo de qualquer exclusão.

    Lança _ClientesIndisponiveis ou _VisitasIndisponiveis quando a planilha não pode
    ser lida: exceções não ficam em cache, então uma falha nunca vira "sem visitas".
    Retorna {"status", "visitas", "bloqueio", "aviso", "ambiguas"}, com status "ok"
    (consulta feita e completa, com ou sem visitas), "ambiguo" (consulta feita, mas
    visitas de identificação duvidosa ficaram de fora: a lista é incompleta) ou
    "bloqueio" (o próprio nome do condomínio é duvidoso)."""
    resultado = {"status": "ok", "visitas": [], "bloqueio": "", "aviso": "", "ambiguas": []}
    cadastro = _ler_cadastro_identificacao()
    alvo_n = normalizar_texto_busca(nome_condominio)
    mesmos = [c for c in cadastro if normalizar_texto_busca(c["nome"]) == alvo_n]
    if len(mesmos) > 1:
        # O "ID Cliente" gravado nas visitas antigas vinha do primeiro nome igual: não separa.
        lista = "; ".join(f"{c['id'] or 'sem ID'} – {c['empresa'] or 'empresa não informada'}" for c in mesmos)
        resultado["status"], resultado["bloqueio"] = "bloqueio", "nome_duplicado"
        resultado["aviso"] = (
            f"⚠️ Há {len(mesmos)} cadastros com o nome “{nome_condominio}” ({lista}). As visitas não foram "
            "importadas, para não misturar dados de cadastros diferentes. Os registros continuam na planilha; "
            "diferencie os nomes no cadastro de clientes para liberar a importação."
        )
        return resultado
    if len(mesmos) == 1:
        resultado["id_cliente"] = mesmos[0]["id"]  # identidade estável do cliente (vazio se o cadastro não tem ID)
        resultado["empresa_cliente"] = mesmos[0]["empresa"]
    if not mesmos:
        # Nome digitado que não é um cadastro, mas pode representar um (abreviado, com
        # erro de digitação ou com complemento): não importa nada de outro cliente.
        semelhantes = []
        for c in cadastro:
            n = normalizar_texto_busca(c["nome"])
            if n and (n in alvo_n or alvo_n in n):
                semelhantes.append(c)
        if alvo_n and semelhantes:
            lista = "; ".join(f"{c['nome']} ({c['id'] or 'sem ID'} – {c['empresa'] or 'empresa não informada'})"
                              for c in semelhantes[:5])
            resultado["status"], resultado["bloqueio"] = "bloqueio", "nome_semelhante"
            resultado["aviso"] = (
                f"⚠️ O nome “{nome_condominio}” não corresponde exatamente a um cadastro e pode representar: {lista}. "
                "As visitas não foram importadas automaticamente e os dados do formulário foram mantidos. "
                "Para importar, carregue o cliente cadastrado pelo nome exato."
            )
            return resultado
    nomes_n = {normalizar_texto_busca(c["nome"]) for c in cadastro} - {""}
    try:
        sh = conectar_sheets()
        if sh is None:
            raise _VisitasIndisponiveis("sem conexão com a planilha")
        aba = obter_aba_sheets("🔬 Visitas")
        todos = aba.get_all_values()
    except _VisitasIndisponiveis:
        raise
    except Exception as e:
        _log_sheets_erro("sheets_listar_lancamentos", e)
        raise _VisitasIndisponiveis(f"{type(e).__name__}: {e}") from e
    try:
        lancamentos = []
        ambiguas = []

        for row in todos:
            if len(row) < 5:
                continue

            id_visita = str(row[1]).strip() if len(row) > 1 else ""
            data_raw = str(row[2]).strip() if len(row) > 2 else ""
            cond_linha = str(row[4]).strip() if len(row) > 4 else ""

            # Ignora cabeçalho e linhas que não são visita real.
            if not id_visita.startswith("V"):
                continue

            pertence = _resolver_condominio_da_visita(alvo_n, normalizar_texto_busca(cond_linha), nomes_n)
            if pertence == "ambigua":
                ambiguas.append(f"{id_visita} ({cond_linha})")
            if pertence != "sim":
                continue

            def _r(i):
                return row[i] if len(row) > i else ""

            data_norm = normalizar_data_visita(data_raw)
            payload = {}
            payload_raw = _r(22)  # Coluna W
            if payload_raw:
                try:
                    payload = json.loads(payload_raw)
                except Exception:
                    payload = {}

            if payload:
                payload["id_visita"] = payload.get("id_visita", id_visita)
                payload["data"] = normalizar_data_visita(payload.get("data", data_norm))
                payload["condominio"] = payload.get("condominio", cond_linha)
                payload["status"] = payload.get("status", _r(19))
                payload["operador"] = payload.get("operador", _r(20))
                lancamentos.append(payload)
                continue

            # Compatibilidade com linhas antigas sem Payload JSON.
            lancamentos.append({
                "id_visita": id_visita,
                "data": data_norm,
                "condominio": cond_linha,
                "ph": _r(5),
                "cloro_livre": _r(6),
                "cloro_total": _r(7),
                "alcalinidade": _r(8),
                "dureza": _r(9),
                "cianurico": _r(10),
                "observacao": _r(14),
                "dosagem_resumo": _r(15),
                "status": _r(19),
                "operador": _r(20),
                "problemas": _r(21),
            })

        resultado["visitas"] = lancamentos
        resultado["ambiguas"] = ambiguas
        if ambiguas:
            resultado["status"] = "ambiguo"  # lista incompleta: não vale como "sem visitas" nem como lista final
            resultado["aviso"] = (
                f"⚠️ {len(ambiguas)} visita(s) gravada(s) com nome que corresponde a mais de um condomínio cadastrado "
                f"não foram importadas: {', '.join(ambiguas[:5])}{'…' if len(ambiguas) > 5 else ''}. "
                "Os registros continuam na planilha e os dados já preenchidos no relatório foram mantidos; "
                "a importação automática fica suspensa até a identificação ser resolvida."
            )
        return resultado

    except Exception as e:
        _log_sheets_erro("sheets_listar_lancamentos", e)
        raise _VisitasIndisponiveis(f"{type(e).__name__}: {e}") from e


def situacao_visitas_condominio(nome_condominio: str) -> dict:
    """Situação da consulta de visitas de um condomínio, sem lançar exceção.

    status "ok": consulta feita e completa (visitas pode estar vazia: ausência legítima);
    status "ambiguo": consulta feita, mas visitas duvidosas ficaram de fora (incompleta);
    status "bloqueio": o nome do condomínio é duvidoso (duplicado ou semelhante);
    status "falha": cadastro de clientes ou aba 🔬 Visitas não puderam ser lidos.
    Fora de "ok", nada é importado ou retirado automaticamente; "ambiguo" e "bloqueio"
    exigem validação explícita para gerar, e "falha" suspende a geração."""
    try:
        return _situacao_visitas_cache(nome_condominio)
    except _ClientesIndisponiveis:
        return {"status": "falha", "visitas": [], "bloqueio": "cadastro_indisponivel", "ambiguas": [], "aviso": (
            "⚠️ Não foi possível consultar o cadastro de clientes para confirmar a qual condomínio cada visita "
            "pertence. Nenhuma visita foi importada agora e os dados do relatório foram mantidos. "
            "Tente novamente em instantes.")}
    except _VisitasIndisponiveis:
        return {"status": "falha", "visitas": [], "bloqueio": "visitas_indisponiveis", "ambiguas": [], "aviso": (
            "⚠️ Não foi possível ler a aba 🔬 Visitas da planilha. Isto é uma falha de consulta, não ausência de "
            "visitas: nada foi importado nem retirado e os dados do relatório foram mantidos. "
            "Tente novamente em instantes.")}


def chave_validacao_origem(relatorio: str, nome_condominio: str, mes, ano) -> str:
    """Chave da confirmação explícita de que os dados do relatório pertencem ao
    condomínio e período; muda com o condomínio e o período, e não entra em rascunhos."""
    return f"_validar_origem_{relatorio}_{slugify_nome(str(nome_condominio or ''))}_{str(mes or '').zfill(2)}_{ano or ''}"


def origem_validada(situacao: dict, chave: str) -> bool:
    """Pode gerar? "ok" sim; "falha" e "bloqueio" (cliente sem identificação segura)
    nunca; "ambiguo" (visitas duvidosas de fora) só com confirmação explícita."""
    status = situacao.get("status", "ok")
    if status == "ok":
        return True
    if status in ("falha", "bloqueio"):
        return False
    return bool(st.session_state.get(chave))


def caixa_validacao_origem(situacao: dict, chave: str, nome_condominio: str, periodo: str):
    """Mostra a confirmação explícita quando visitas duvidosas ficaram de fora ("ambiguo").
    Em "bloqueio" não há confirmação: o cliente precisa ser identificado."""
    if situacao.get("status") == "ambiguo":
        st.checkbox(
            f"Revisei os dados do relatório e confirmo que pertencem a {nome_condominio} ({periodo}), "
            "apesar do aviso de identificação das visitas.",
            key=chave,
        )


def sheets_listar_lancamentos(nome_condominio: str) -> list[dict]:
    """Retorna lançamentos de visitas de um condomínio a partir da aba 🔬 Visitas.
    Visitas de identificação duvidosa ficam de fora; o motivo está em
    situacao_visitas_condominio(nome)["aviso"]."""
    return situacao_visitas_condominio(nome_condominio)["visitas"]


@st.cache_data(ttl=45, show_spinner=False)
def sheets_listar_todas_visitas() -> list[dict]:
    """Lê a aba 🔬 Visitas uma única vez e retorna todas as visitas.

    Use esta função no dashboard e em relatórios que precisam de totais,
    em vez de chamar sheets_listar_lancamentos() em loop por cliente.
    Evita erro 429 (Quota exceeded) do Google Sheets.
    """
    try:
        aba = obter_aba_sheets("🔬 Visitas")
        todos = aba.get_all_values()
        visitas = []

        for row in todos:
            if len(row) < 5:
                continue
            id_visita = str(row[1]).strip() if len(row) > 1 else ""
            if not id_visita.startswith("V"):
                continue

            def _r(i):
                return row[i] if len(row) > i else ""

            payload_raw = _r(22)
            payload = {}
            if payload_raw:
                try:
                    payload = json.loads(payload_raw)
                except Exception:
                    payload = {}

            visitas.append({
                "id_visita": id_visita,
                "data": normalizar_data_visita(_r(2)),
                "id_cliente": _r(3),
                "condominio": _r(4),
                "ph": _r(5),
                "crl": _r(6),
                "ct": _r(7),
                "alcalinidade": _r(8),
                "dureza": _r(9),
                "cya": _r(10),
                "observacao": _r(14),
                "dosagem": _r(15),
                "status": _r(19),
                "operador": _r(20),
                "problemas": _r(21),
                "payload_json": payload_raw,
                "salvo_em": _r(23),
                "fonte": _r(24),
                "mes_ano": _r(25),
                "_payload": payload,
            })

        return visitas

    except Exception as e:
        _log_sheets_erro("sheets_listar_todas_visitas", e)
        return []


def extrair_lancamento_de_pdf_visita(pdf_bytes: bytes, nome_condominio_padrao: str = "") -> dict:
    """Extrai dados básicos de um PDF de Relatório de Visita Aqua Gestão.

    Uso: permite recuperar visitas antigas que geraram PDF, mas não foram gravadas
    na aba 🔬 Visitas do Google Sheets. Não inventa dados: só preenche o que achar no PDF.
    """
    try:
        import fitz  # PyMuPDF
        doc = fitz.open(stream=pdf_bytes, filetype="pdf")
        texto = "\n".join(page.get_text("text") for page in doc)
    except Exception as e:
        _log_sheets_erro("extrair_lancamento_de_pdf_visita/fitz", e)
        return {}

    linhas = [re.sub(r"\s+", " ", l).strip() for l in texto.splitlines() if str(l).strip()]

    def _apos(rotulo: str) -> str:
        rot = normalizar_texto_busca(rotulo)
        for i, linha in enumerate(linhas):
            if normalizar_texto_busca(linha) == rot and i + 1 < len(linhas):
                return linhas[i + 1].strip()
        return ""

    nome_cond = _apos("CONDOMÍNIO / LOCAL") or nome_condominio_padrao
    data_vis = normalizar_data_visita(_apos("DATA DA VISITA"))
    operador = _apos("OPERADOR")
    resp = _apos("RESP. TÉCNICO")

    observacao = ""
    for i, linha in enumerate(linhas):
        if normalizar_texto_busca(linha) == "observacoes" and i + 1 < len(linhas):
            prox = linhas[i + 1].strip().strip('"')
            if normalizar_texto_busca(prox) not in ("registro fotografico", "antes do tratamento"):
                observacao = prox
            break

    def _extrair_bloco(nome_piscina: str, inicio_idx: int, fim_idx: int) -> dict:
        bloco = linhas[inicio_idx:fim_idx]

        def _valor(prefixos: list[str]) -> str:
            for ln in bloco:
                ln_limpa = ln.strip()
                ln_norm = normalizar_texto_busca(ln_limpa)
                for pref in prefixos:
                    pref_norm = normalizar_texto_busca(pref)
                    if ln_norm.startswith(pref_norm):
                        resto = ln_limpa
                        for alvo in ["pH", "CRL mg/L", "CRL", "CT mg/L", "CT", "Alc. mg/L (15d)", "Alc", "Dureza mg/L (15d)", "Dureza", "CYA mg/L (15d)", "CYA", "Cloraminas"]:
                            if normalizar_texto_busca(resto).startswith(normalizar_texto_busca(alvo)):
                                resto = re.sub(re.escape(alvo), "", resto, count=1, flags=re.IGNORECASE).strip()
                                break
                        m = re.search(r"(—|-|\d+(?:[,.]\d+)?)", resto)
                        return m.group(1) if m else ""
            return ""

        return {
            "nome": nome_piscina,
            "ph": _valor(["pH"]),
            "cloro_livre": _valor(["CRL mg/L", "CRL"]),
            "cloro_total": _valor(["CT mg/L", "CT"]),
            "alcalinidade": _valor(["Alc. mg/L (15d)", "Alc"]),
            "dureza": _valor(["Dureza mg/L (15d)", "Dureza"]),
            "cianurico": _valor(["CYA mg/L (15d)", "CYA"]),
            "cloraminas": _valor(["Cloraminas"]),
        }

    indices_piscinas = []
    for i, linha in enumerate(linhas):
        ln = normalizar_texto_busca(linha)
        if "piscina adulto" in ln:
            indices_piscinas.append(("Piscina Adulto", i))
        elif "piscina infantil" in ln:
            indices_piscinas.append(("Piscina Infantil", i))
        elif "piscina family" in ln or "piscina spa" in ln:
            indices_piscinas.append((linha.replace("■", "").strip(), i))

    piscinas = []
    for pos, (nome_pisc, idx) in enumerate(indices_piscinas):
        fim = indices_piscinas[pos + 1][1] if pos + 1 < len(indices_piscinas) else len(linhas)
        for j in range(idx + 1, fim):
            if normalizar_texto_busca(linhas[j]) in ("alertas tecnicos", "dosagens aplicadas", "observacoes", "registro fotografico"):
                fim = j
                break
        p = _extrair_bloco(nome_pisc, idx, fim)
        if any(p.get(k) for k in ["ph", "cloro_livre", "cloro_total", "alcalinidade", "dureza", "cianurico", "cloraminas"]):
            piscinas.append(p)

    dosagens = []
    for i, linha in enumerate(linhas):
        if normalizar_texto_busca(linha) == "dosagens aplicadas":
            for ln in linhas[i + 1:i + 8]:
                ln_norm = normalizar_texto_busca(ln)
                if ln_norm in ("produto quantidade finalidade", "observacoes", "registro fotografico"):
                    continue
                if ln_norm.startswith("observacoes") or ln_norm.startswith("registro fotografico"):
                    break
                m = re.match(r"(.+?)\s+(\d+(?:[,.]\d+)?\s*(?:kg|g|ml|l|litros?))\s+(.+)$", ln, flags=re.IGNORECASE)
                if m:
                    dosagens.append({
                        "produto": m.group(1).strip(),
                        "quantidade": m.group(2).strip(),
                        "unidade": "",
                        "finalidade": m.group(3).strip(),
                    })
                    break
            break

    problemas = []
    coletando = False
    for ln in linhas:
        ln_norm = normalizar_texto_busca(ln)
        if ln_norm == "alertas tecnicos":
            coletando = True
            continue
        if coletando and ln_norm in ("dosagens aplicadas", "observacoes", "registro fotografico"):
            break
        if coletando:
            problemas.append(ln.replace("■", "").strip())

    base = piscinas[0] if piscinas else {}
    lancamento = {
        "data": data_vis,
        "operador": operador,
        "responsavel_tecnico_pdf": resp,
        "condominio": nome_cond,
        "ph": base.get("ph", ""),
        "cloro_livre": base.get("cloro_livre", ""),
        "cloro_total": base.get("cloro_total", ""),
        "cloraminas": base.get("cloraminas", ""),
        "alcalinidade": base.get("alcalinidade", ""),
        "dureza": base.get("dureza", ""),
        "cianurico": base.get("cianurico", ""),
        "piscinas": piscinas,
        "problemas": " | ".join(problemas),
        "observacao": observacao,
        "dosagens": dosagens,
        "parecer": "Importado de PDF de visita",
        "salvo_em": _agora_brasilia(),
        "fonte": "PDF de Relatório de Visita",
    }
    if not lancamento.get("data") and not piscinas and not dosagens:
        return {}
    if not lancamento.get("condominio"):
        lancamento["condominio"] = nome_condominio_padrao
    return lancamento

# =========================================
# OPERADORES — CONTROLE DE ACESSO
# =========================================


def filtrar_condomínios_por_operador(nome_operador: str, todos_condomínios: list[str]) -> list[str]:
    """Retorna lista de condomínios que o operador tem permissão de ver."""
    if not nome_operador.strip():
        return todos_condomínios  # sem nome → mostra todos (modo antigo)
    operadores = sheets_listar_operadores()
    for op in operadores:
        if _normalizar_chave_acesso(op["nome"]) == _normalizar_chave_acesso(nome_operador):
            conds = _condominios_organizar(op.get("condomínios", []))
            if any(_normalizar_chave_acesso(c) == "todos" for c in conds) or not conds:
                return todos_condomínios
            return _resolver_condominios_permitidos_exatos(conds, todos_condomínios)
    # Operador não cadastrado → mostra todos (retrocompatibilidade)
    return todos_condomínios


# =========================================
# MOTOR DE SUGESTÕES DE DOSAGEM
# =========================================

# Doses padrão APSP/WHO
DOSE_HIPOCLORITO_65  = 13.0   # g/m³ por ppm de CRL
DOSE_DICLORO_56      = 15.0   # g/m³ por ppm de CRL
DOSE_ACIDO_MURIATICO = 18.0   # mL/m³ por 0,1 de pH
DOSE_BICARBONATO     = 15.0   # g/m³ por 10 ppm de Alc
DOSE_CLORETO_CALCIO  = 17.0   # g/m³ por 10 ppm de Dureza
FATOR_DEMANDA        = 1.20   # +20% por demanda orgânica/UV

# Metas ideais (centro da faixa)
META_CRL        = 3.0    # ppm
META_PH         = 7.35   # centro entre 7,2-7,5
META_ALC        = 100.0  # ppm
META_DUREZA     = 225.0  # ppm
META_CYA        = 40.0   # ppm (só monitoramento)

# Faixas ideais
FAIXA_PH_MIN    = 7.2;  FAIXA_PH_MAX    = 7.8
FAIXA_CRL_MIN   = 0.5;  FAIXA_CRL_MAX   = 5.0
FAIXA_ALC_MIN   = 80;   FAIXA_ALC_MAX   = 120
FAIXA_DC_MIN    = 150;  FAIXA_DC_MAX    = 300
FAIXA_CYA_MIN   = 30;   FAIXA_CYA_MAX   = 50


def calcular_sugestoes_dosagem(ph: float | None, crl: float | None,
                                alc: float | None, dc: float | None,
                                cya: float | None, volume_m3: float) -> list[dict]:
    """
    Calcula sugestões de produtos e doses baseado nos parâmetros medidos.
    Retorna lista de dicts com: produto, quantidade, unidade, prioridade, justificativa.
    """
    sugestoes = []

    if volume_m3 <= 0:
        return sugestoes

    # ── 1. pH — SEMPRE CORRIGIR ANTES DO CLORO ───────────────────────────────
    if ph is not None:
        if ph > 7.8:
            # pH muito alto — reduzir antes de clorar
            deficit_ph = round(ph - 7.5, 1)
            dose_ml = round(deficit_ph / 0.1 * DOSE_ACIDO_MURIATICO * volume_m3 * FATOR_DEMANDA)
            sugestoes.append({
                "prioridade": 1,
                "produto": "Ácido muriático 31%",
                "quantidade": dose_ml,
                "unidade": "mL",
                "acao": "Reduzir pH",
                "justificativa": f"pH {ph:.1f} acima de 7,8 — reduzir para 7,4–7,5 antes de clorar. "
                                 f"Cloro perde >50% eficiência com pH alto.",
                "norma": "APSP / ABNT NBR 10339",
            })
        elif ph < 7.2:
            # pH baixo — hipoclorito vai elevar naturalmente
            sugestoes.append({
                "prioridade": 1,
                "produto": "Observação",
                "quantidade": 0,
                "unidade": "",
                "acao": "pH baixo — Hipoclorito de cálcio vai elevar",
                "justificativa": f"pH {ph:.1f} abaixo de 7,2 — aplicar Hipoclorito de cálcio 65% "
                                 f"(pH ~11,5) vai elevar o pH naturalmente enquanto desinfeta.",
                "norma": "APSP / WHO",
            })

    # ── 2. CLORO — produto baseado no pH ─────────────────────────────────────
    if crl is not None and crl < META_CRL:
        deficit_crl = round(META_CRL - crl, 2)

        # Seleciona produto pelo pH
        if ph is None or ph <= 7.5:
            produto_cloro = "Hipoclorito de cálcio 65%"
            fator_cloro   = DOSE_HIPOCLORITO_65
            motivo_cloro  = f"pH {ph:.1f} ≤ 7,5 — produto ideal nesta faixa" if ph else "pH não medido — usando padrão"
        else:
            produto_cloro = "Dicloro 56%"
            fator_cloro   = DOSE_DICLORO_56
            motivo_cloro  = f"pH {ph:.1f} entre 7,5–7,8 — Dicloro é mais indicado (mais ácido)"

        dose_g = round(deficit_crl * volume_m3 * fator_cloro * FATOR_DEMANDA)

        if dose_g >= 1000:
            qtd_fmt = round(dose_g / 1000, 2)
            unid = "kg"
        else:
            qtd_fmt = dose_g
            unid = "g"

        sugestoes.append({
            "prioridade": 2,
            "produto": produto_cloro,
            "quantidade": qtd_fmt,
            "unidade": unid,
            "acao": f"Elevar CRL de {crl:.1f} → {META_CRL:.1f} ppm",
            "justificativa": f"CRL {crl:.1f} ppm abaixo da meta ({META_CRL} ppm). "
                             f"Déficit: {deficit_crl} ppm × {volume_m3}m³ × {fator_cloro}g × 1,2 dem. "
                             f"| {motivo_cloro}.",
            "norma": "APSP / WHO",
        })

    elif crl is not None and crl > FAIXA_CRL_MAX:
        sugestoes.append({
            "prioridade": 2,
            "produto": "Aeração + aguardar",
            "quantidade": 0,
            "unidade": "",
            "acao": f"CRL {crl:.1f} ppm — acima de {FAIXA_CRL_MAX} ppm",
            "justificativa": "Cloro excessivo — não adicionar mais. "
                             "Aeração (agitação da água) e luz solar reduzem naturalmente.",
            "norma": "ABNT NBR 10339",
        })

    # ── 3. ALCALINIDADE ───────────────────────────────────────────────────────
    if alc is not None:
        if alc < FAIXA_ALC_MIN:
            deficit_alc = round(META_ALC - alc, 1)
            dose_g = round((deficit_alc / 10) * DOSE_BICARBONATO * volume_m3)
            qtd_fmt = round(dose_g / 1000, 2) if dose_g >= 1000 else dose_g
            unid = "kg" if dose_g >= 1000 else "g"
            sugestoes.append({
                "prioridade": 3,
                "produto": "Bicarbonato de sódio",
                "quantidade": qtd_fmt,
                "unidade": unid,
                "acao": f"Elevar alcalinidade de {alc:.0f} → {META_ALC:.0f} ppm",
                "justificativa": f"Alcalinidade {alc:.0f} ppm abaixo de {FAIXA_ALC_MIN} ppm. "
                                 f"Déficit: {deficit_alc:.0f} ppm ÷ 10 × {DOSE_BICARBONATO}g × {volume_m3}m³.",
                "norma": "WHO / ABNT NBR 10339",
            })
        elif alc > FAIXA_ALC_MAX:
            excesso_alc = round(alc - META_ALC, 1)
            dose_ml = round((excesso_alc / 0.1) * DOSE_ACIDO_MURIATICO * volume_m3 * 0.5)
            sugestoes.append({
                "prioridade": 3,
                "produto": "Ácido muriático 31%",
                "quantidade": dose_ml,
                "unidade": "mL",
                "acao": f"Reduzir alcalinidade de {alc:.0f} → {META_ALC:.0f} ppm",
                "justificativa": f"Alcalinidade {alc:.0f} ppm acima de {FAIXA_ALC_MAX} ppm. "
                                 "Aplicar ácido muriático com bomba desligada.",
                "norma": "APSP",
            })

    # ── 4. DUREZA ─────────────────────────────────────────────────────────────
    if dc is not None:
        if dc < FAIXA_DC_MIN:
            deficit_dc = round(META_DUREZA - dc, 1)
            dose_g = round((deficit_dc / 10) * DOSE_CLORETO_CALCIO * volume_m3)
            qtd_fmt = round(dose_g / 1000, 2) if dose_g >= 1000 else dose_g
            unid = "kg" if dose_g >= 1000 else "g"
            sugestoes.append({
                "prioridade": 4,
                "produto": "Cloreto de cálcio",
                "quantidade": qtd_fmt,
                "unidade": unid,
                "acao": f"Elevar dureza de {dc:.0f} → {META_DUREZA:.0f} ppm",
                "justificativa": f"Dureza {dc:.0f} ppm abaixo de {FAIXA_DC_MIN} ppm. "
                                 "Água agressiva corrói equipamentos e pisos.",
                "norma": "APSP / WHO",
            })
        elif dc > FAIXA_DC_MAX:
            sugestoes.append({
                "prioridade": 4,
                "produto": "Troca parcial de água",
                "quantidade": round(volume_m3 * 0.2),
                "unidade": "m³",
                "acao": f"Reduzir dureza de {dc:.0f} ppm",
                "justificativa": f"Dureza {dc:.0f} ppm acima de {FAIXA_DC_MAX} ppm. "
                                 "Trocar ~20% da água e reequilibrar.",
                "norma": "APSP",
            })

    # ── 5. CYA — só monitoramento ─────────────────────────────────────────────
    if cya is not None:
        if cya > FAIXA_CYA_MAX:
            sugestoes.append({
                "prioridade": 5,
                "produto": "Troca parcial de água",
                "quantidade": round(volume_m3 * 0.3),
                "unidade": "m³",
                "acao": f"CYA {cya:.0f} ppm acima do limite",
                "justificativa": f"CYA {cya:.0f} ppm acima de {FAIXA_CYA_MAX} ppm. "
                                 "CYA alto inibe o cloro (efeito bloqueio). Trocar ~30% da água.",
                "norma": "WHO",
            })
        elif cya < FAIXA_CYA_MIN and cya > 0:
            sugestoes.append({
                "prioridade": 5,
                "produto": "Monitorar CYA",
                "quantidade": 0,
                "unidade": "",
                "acao": f"CYA {cya:.0f} ppm — abaixo do ideal",
                "justificativa": f"CYA {cya:.0f} ppm abaixo de {FAIXA_CYA_MIN} ppm. "
                                 "Sem ácido cianúrico puro no estoque — monitorar.",
                "norma": "APSP",
            })

    # Ordena por prioridade
    sugestoes.sort(key=lambda x: x["prioridade"])
    return sugestoes


def exibir_sugestoes_dosagem(sugestoes: list[dict]):
    """Exibe as sugestões de dosagem formatadas no Streamlit."""
    if not sugestoes:
        st.success("✅ Todos os parâmetros dentro da faixa ideal. Nenhuma correção necessária.")
        return

    st.markdown("**💊 Sugestões de correção (APSP/WHO):**")
    for s in sugestoes:
        prod = s["produto"]
        qtd  = s["quantidade"]
        unid = s["unidade"]
        acao = s["acao"]
        just = s["justificativa"]
        prio = s["prioridade"]

        if prio == 1:
            icon = "🔴"
        elif prio == 2:
            icon = "🟡"
        else:
            icon = "🔵"

        if qtd and qtd > 0:
            st.markdown(f"{icon} **{prod}** — **{qtd} {unid}** → _{acao}_")
        else:
            st.markdown(f"{icon} **{prod}** → _{acao}_")

        with st.expander("ℹ️ Detalhes técnicos", expanded=False):
            st.caption(f"📐 {just}")
            st.caption(f"📚 Norma: {s.get('norma','')}")

