def calcular_linhas_analises_por_frequencia(verificacoes_semanais: int | str | None = None, mes: str | None = None, ano: str | None = None) -> int:
    """Calcula quantas linhas de análise o relatório deve abrir.

    Regra operacional adotada: 12 linhas como padrão mínimo.
    Para clientes com rotina cadastrada, usa verificações semanais × 4 semanas.
    Se o mês tiver mais lançamentos reais importados, o sistema expande automaticamente.
    """
    try:
        freq = int(float(str(verificacoes_semanais or "").replace(",", ".")))
    except Exception:
        freq = 3
    freq = max(1, min(freq, 7))
    return max(ANALISES_PADRAO, min(freq * 4, ANALISES_MAX_SUGERIDO))


def calcular_linhas_analises_rt_mensal(verificacoes_semanais: int | str | None = None, mes: str | None = None, ano: str | None = None) -> int:
    """Calcula as linhas do relatório RT: exatamente um lançamento por semana.

    O parâmetro ``verificacoes_semanais`` é mantido apenas por compatibilidade com
    chamadas antigas. A frequência operacional do cliente não deve dimensionar o
    relatório de RT, pois limpeza/manutenção e supervisão técnica são rotinas
    independentes.
    """
    freq = 1

    try:
        mes_i = int(str(mes or "").strip())
        ano_i = int(str(ano or "").strip())
        if mes_i < 1 or mes_i > 12:
            raise ValueError("mes fora da faixa")
    except Exception:
        hoje = datetime.now()
        mes_i = hoje.month
        ano_i = hoje.year

    try:
        primeiro_dia = date(ano_i, mes_i, 1)
        if mes_i == 12:
            proximo_mes = date(ano_i + 1, 1, 1)
        else:
            proximo_mes = date(ano_i, mes_i + 1, 1)
        dias_no_mes = max((proximo_mes - primeiro_dia).days, 28)
        # As visitas semanais do RT são lançadas às terças-feiras.
        # Conta as terças reais do mês, evitando abrir uma quinta linha em meses
        # com 31 dias que possuam somente quatro terças.
        qtd_tercas = sum(
            1 for dia in range(1, dias_no_mes + 1)
            if date(ano_i, mes_i, dia).weekday() == 1
        )
    except Exception:
        qtd_tercas = 4

    return max(1, min(qtd_tercas, ANALISES_MAX_SUGERIDO))


def obter_verificacoes_semanais_cliente(cliente_ou_dados: dict | None) -> int:
    """Obtém a frequência semanal cadastrada para o cliente, com fallback para 3x/semana."""
    dados = cliente_ou_dados or {}
    for chave in ["verificacoes_semanais", "frequencia_verificacoes_semanais", "visitas_semanais", "frequencia_semanal"]:
        valor = dados.get(chave)
        try:
            iv = int(float(str(valor or "").replace(",", ".")))
            if iv > 0:
                return max(1, min(iv, 7))
        except Exception:
            pass
    return 3


