def encontrar_assinatura_rt() -> Path | None:
    for caminho in ASSINATURA_RT_CANDIDATOS:
        if caminho.exists() and caminho.is_file():
            return caminho
    return None


def preparar_assinatura_rt_para_relatorio() -> Path | None:
    assinatura = encontrar_assinatura_rt()
    if not assinatura:
        return None

    destino = GENERATED_DIR / "_assinatura_rt_relatorio.png"
    try:
        with Image.open(assinatura) as img:
            img = img.convert("RGBA")
            fundo = Image.new("RGBA", img.size, (255, 255, 255, 255))
            fundo.alpha_composite(img)
            fundo = fundo.convert("RGB")
            fundo = ImageOps.expand(fundo, border=18, fill="white")
            fundo.save(destino, format="PNG")
        return destino
    except Exception:
        return assinatura


def encontrar_logo() -> Path | None:
    """Retorna somente a logo institucional aprovada da ACQUA GESTÃO.

    Não há varredura genérica de arquivos "logo": ela poderia escolher a arte
    antiga "AQUA GESTÃO" ou a marca da Bem Star. Sem a arte aprovada, os
    geradores usam marca textual.
    """
    for caminho in LOGO_CANDIDATOS:
        nome = caminho.name.lower()
        if "bem_star" in nome or "bemstar" in nome:
            continue
        if caminho.exists() and caminho.is_file():
            return caminho
    return None


def encontrar_logo_bem_star() -> Path | None:
    for caminho in LOGO_BEM_STAR_CANDIDATOS:
        if caminho.exists() and caminho.is_file():
            return caminho
    for extensao in ("*.png", "*.jpg", "*.jpeg", "*.webp"):
        for pasta in [BASE_DIR, BASE_DIR / "assets", BASE_DIR / "images"]:
            if pasta.exists():
                for arq in pasta.glob(extensao):
                    if "bem_star" in arq.name.lower() and "logo" in arq.name.lower():
                        return arq
    return None


def inserir_foto_docx_exif(doc_or_run, foto_path: Path, width_inches: float = 5.5):
    """Insere foto em DOCX com rotação EXIF corrigida automaticamente.
    Salva temporariamente a imagem corrigida e insere no documento.
    """
    import io as _io
    try:
        from PIL import Image as _PIL, ImageOps as _IOS
        _img = _PIL.open(str(foto_path))
        _img = _IOS.exif_transpose(_img)  # Corrige rotação EXIF
        _img.thumbnail((1800, 1800), _PIL.LANCZOS)
        _buf = _io.BytesIO()
        _img.convert("RGB").save(_buf, format="JPEG", quality=88)
        _buf.seek(0)
        if hasattr(doc_or_run, "add_picture"):
            # É um run
            doc_or_run.add_picture(_buf, width=Inches(width_inches))
        else:
            # É um parágrafo ou doc — adicionar run
            doc_or_run.add_run().add_picture(_buf, width=Inches(width_inches))
        return True
    except Exception:
        # Fallback sem correção EXIF
        try:
            if hasattr(doc_or_run, "add_picture"):
                doc_or_run.add_picture(str(foto_path), width=Inches(width_inches))
            else:
                doc_or_run.add_run().add_picture(str(foto_path), width=Inches(width_inches))
            return True
        except Exception:
            return False


def logo_para_base64(path) -> str:
    """Converte imagem para string base64 para exibicao HTML inline."""
    if path is None or not path.exists():
        return ""
    try:
        import base64 as _b64
        ext = path.suffix.lower().lstrip(".")
        mime = {"jpg": "jpeg", "jpeg": "jpeg", "png": "png", "webp": "webp"}.get(ext, "png")
        with open(path, "rb") as f:
            dados = _b64.b64encode(f.read()).decode()
        return f"data:image/{mime};base64,{dados}"
    except Exception:
        return ""


def _agora_brasilia() -> str:
    """Retorna horario atual no fuso de Brasilia (UTC-3)."""
    from datetime import timezone, timedelta
    return datetime.now(tz=timezone(timedelta(hours=-3))).strftime("%d/%m/%Y %H:%M:%S")

def salvar_rascunho_operador(nome_cond: str, dados: dict, salvar_sheets: bool = False) -> bool:
    """Salva rascunho. Por padrão salva APENAS localmente (evita reruns pesados durante digitação).
    
    v5: o parâmetro salvar_sheets=True deve ser usado APENAS quando o operador
    clicar explicitamente em "Salvar rascunho". Nunca chamar com sheets=True
    a partir de on_change ou de autosave automático.
    """
    dados["_rascunho_salvo_em"] = _agora_brasilia()
    dados["_rascunho_cond"] = nome_cond.strip()
    salvo_local = salvo_sheets = False

    # 1. Arquivo local (rápido — sempre executado)
    try:
        pasta = GENERATED_DIR / slugify_nome(nome_cond.strip())
        pasta.mkdir(parents=True, exist_ok=True)
        dados_local = {k: v for k, v in dados.items()
                       if not any(p in str(k).lower() for p in ["b64","base64","assinatura_responsavel_b64"])}
        with open(pasta / "_rascunho_operador.json", "w", encoding="utf-8") as f:
            json.dump(dados_local, f, ensure_ascii=False, indent=2)
        salvo_local = True
    except Exception:
        pass

    # 2. Google Sheets aba _Rascunhos — SOMENTE quando solicitado explicitamente
    # v5: não chamar durante digitação/on_change para evitar reruns e instabilidade
    # (nunca no Codespaces: ver _rascunho_usa_sheets)
    if salvar_sheets and _rascunho_usa_sheets():
        try:
            sh = conectar_sheets()
            if sh:
                # obter_aba_sheets devolve None (não exceção) quando a aba não existe
                # e guarda esse None em cache; numa planilha nova o rascunho nunca era
                # gravado. Consulta direta e cria a aba quando necessário.
                try:
                    aba_rasc = sh.worksheet("_Rascunhos")
                except Exception:
                    aba_rasc = None
                if aba_rasc is None:
                    aba_rasc = sh.add_worksheet(title="_Rascunhos", rows=500, cols=4)
                    aba_rasc.update(range_name="A1:D1", values=[["Condomínio", "Operador", "Salvo em", "Dados JSON"]])
                dados_sh = {k: v for k, v in dados.items()
                            if not any(p in str(k).lower() for p in ["b64","base64","assinatura_responsavel_b64"])}
                payload = json.dumps(dados_sh, ensure_ascii=False)
                if len(payload) > 45000:
                    payload = payload[:45000] + "..."
                todos = aba_rasc.get_all_values()
                chave = nome_cond.strip().lower()
                linha_existente = None
                for i, row in enumerate(todos[1:], start=2):
                    if row and str(row[0]).strip().lower() == chave:
                        linha_existente = i
                        break
                nova = [nome_cond.strip(), dados.get("operador",""), dados["_rascunho_salvo_em"], payload]
                if linha_existente:
                    aba_rasc.update(range_name=f"A{linha_existente}:D{linha_existente}", values=[nova], value_input_option="RAW")
                else:
                    proxima = max(len(todos) + 1, 2)
                    aba_rasc.update(range_name=f"A{proxima}:D{proxima}", values=[nova], value_input_option="RAW")
                salvo_sheets = True
        except Exception:
            pass

    return salvo_local or salvo_sheets  # False: o rascunho não foi gravado em lugar nenhum


def carregar_rascunho_operador(nome_cond: str) -> dict:
    """Carrega rascunho: arquivo local primeiro, fallback no Sheets apos sleep.

    Falhas de leitura não são ignoradas: o motivo fica em _op_rascunho_erro para a tela
    avisar, e um arquivo local ilegível é copiado à parte (nunca apagado) antes que o
    salvamento automático grave por cima."""
    st.session_state.pop("_op_rascunho_erro", None)
    # 1. Arquivo local
    try:
        pasta = GENERATED_DIR / slugify_nome(nome_cond.strip())
        rascunho_path = pasta / "_rascunho_operador.json"
        if rascunho_path.exists():
            with open(rascunho_path, "r", encoding="utf-8") as f:
                return json.load(f)
    except Exception as e:
        erro = f"rascunho local ilegível ({type(e).__name__})"
        try:
            copia = rascunho_path.with_name(f"_rascunho_operador_ilegivel_{datetime.now():%Y%m%d_%H%M%S}.json")
            shutil.copy2(rascunho_path, copia)
            erro += f"; uma cópia foi guardada em {copia.name}"
        except Exception:
            pass
        st.session_state["_op_rascunho_erro"] = erro

    # 2. Fallback Google Sheets (nunca no Codespaces)
    if not _rascunho_usa_sheets():
        return {}
    try:
        sh = conectar_sheets()
        if sh:
            try:
                aba_rasc = sh.worksheet("_Rascunhos")  # sem o cache de "aba ausente"
            except Exception:
                return {}
            todos = aba_rasc.get_all_values()
            chave = nome_cond.strip().lower()
            for row in todos[1:]:
                if row and str(row[0]).strip().lower() == chave and len(row) >= 4 and row[3].strip():
                    dados = json.loads(row[3])
                    try:
                        pasta = GENERATED_DIR / slugify_nome(nome_cond.strip())
                        pasta.mkdir(parents=True, exist_ok=True)
                        with open(pasta / "_rascunho_operador.json", "w", encoding="utf-8") as f:
                            json.dump(dados, f, ensure_ascii=False, indent=2)
                    except Exception:
                        pass
                    return dados
    except Exception as e:
        anterior = st.session_state.get("_op_rascunho_erro")
        st.session_state["_op_rascunho_erro"] = (f"{anterior}; " if anterior else "") + \
            f"não foi possível ler o rascunho na planilha ({type(e).__name__})"

    return {}


def deletar_rascunho_operador(nome_cond: str):
    """Remove rascunho apos salvar lancamento definitivo (local + Sheets)."""
    try:
        pasta = GENERATED_DIR / slugify_nome(nome_cond.strip())
        rascunho_path = pasta / "_rascunho_operador.json"
        if rascunho_path.exists():
            rascunho_path.unlink()
    except Exception:
        pass
    if not _rascunho_usa_sheets():
        return
    try:
        sh = conectar_sheets()
        if sh:
            try:
                aba_rasc = obter_aba_sheets("_Rascunhos")
                todos = aba_rasc.get_all_values()
                chave = nome_cond.strip().lower()
                for i, row in enumerate(todos[1:], start=2):
                    if row and str(row[0]).strip().lower() == chave:
                        aba_rasc.update(range_name=f"A{i}:D{i}", values=[["","","",""]], value_input_option="RAW")
                        break
            except Exception:
                pass
    except Exception:
        pass


_SLUG_PISCINAS_OPERADOR = {"Piscina Adulto": "adulto", "Piscina Infantil": "infantil", "Piscina Family": "family"}


def _slug_piscina_operador(nome: str) -> str:
    """Sufixo das chaves dos campos do operador (op_<slug>_ph...), igual ao do formulário."""
    return _SLUG_PISCINAS_OPERADOR.get(nome, slugify_nome(nome)[:12])


def coletar_rascunho_operador(nome_cond: str, piscinas_ativas: list) -> dict:
    """Coleta estado atual do formulário do operador para salvar como rascunho."""
    dados = {
        "data_visita":  st.session_state.get("op_data_visita", ""),
        "operador":     st.session_state.get("op_operador", ""),
        "obs":          st.session_state.get("op_obs_campo", ""),
        "problemas":    st.session_state.get("op_problemas", ""),
        "resp_local":   st.session_state.get("op_resp_local", ""),
        "parecer":      st.session_state.get("op_parecer_visita", "✅ Satisfatório"),
        "assinatura_responsavel_b64": st.session_state.get("op_assinatura_responsavel_b64", ""),
        "assinatura_responsavel_data": st.session_state.get("op_assinatura_responsavel_data", ""),
        "piscinas": [],
        "dosagens": [],
        "dosagens_por_piscina": {},
        "op_apos_ativo": bool(st.session_state.get("op_apos_ativo", False)),
        "parametros_apos": {
            "ph_apos":           re.sub(r"[^0-9.,]", "", str(st.session_state.get("op_ph_apos", ""))).replace(",", "."),
            "cloro_livre_apos":  re.sub(r"[^0-9.,]", "", str(st.session_state.get("op_crl_apos", ""))).replace(",", "."),
            "cloro_total_apos":  re.sub(r"[^0-9.,]", "", str(st.session_state.get("op_ct_apos", ""))).replace(",", "."),
            "alcalinidade_apos": re.sub(r"[^0-9.,]", "", str(st.session_state.get("op_alc_apos", ""))).replace(",", "."),
            "dureza_apos":       re.sub(r"[^0-9.,]", "", str(st.session_state.get("op_dc_apos", ""))).replace(",", "."),
            "cianurico_apos":    re.sub(r"[^0-9.,]", "", str(st.session_state.get("op_cya_apos", ""))).replace(",", "."),
        },
    }
    # Parâmetros por piscina
    for pisc_nome in piscinas_ativas:
        abrev = _slug_piscina_operador(pisc_nome)
        _pisc_rasc = {
            "nome":        pisc_nome,
            "ph":          st.session_state.get(f"op_{abrev}_ph", ""),
            "cloro_livre": st.session_state.get(f"op_{abrev}_crl", ""),
            "cloro_total": st.session_state.get(f"op_{abrev}_ct", ""),
            "alcalinidade":st.session_state.get(f"op_{abrev}_alc", ""),
            "dureza":      st.session_state.get(f"op_{abrev}_dc", ""),
            "cianurico":   st.session_state.get(f"op_{abrev}_cya", ""),
        }
        _eh_rt_rasc = bool((st.session_state.get("op_dados_atual") or {}).get("is_rt", False))
        if _eh_rt_rasc:
            _pisc_rasc.update({
                "turbidez":    st.session_state.get(f"op_{abrev}_turbidez", ""),
                "orp":         st.session_state.get(f"op_{abrev}_orp", ""),
                "tds":         st.session_state.get(f"op_{abrev}_tds", ""),
                "temperatura": st.session_state.get(f"op_{abrev}_temperatura", ""),
            })
        # Parâmetros pós-tratamento são globais no formulário do operador;
        # também ficam dentro da piscina para o PDF e reprocessamentos futuros.
        if dados.get("op_apos_ativo") or any(dados.get("parametros_apos", {}).values()):
            _pisc_rasc.update(dados.get("parametros_apos", {}))
        dados["piscinas"].append(_pisc_rasc)
    # Dosagens por piscina
    _slug_map_r = {"Piscina Adulto":"adulto","Piscina Infantil":"infantil","Piscina Family":"family"}
    for pisc_nome in piscinas_ativas:
        _slug_r = _slug_map_r.get(pisc_nome, slugify_nome(pisc_nome)[:12])
        _dos_p = []
        for i in range(5):
            prod = st.session_state.get(f"op_dos_{_slug_r}_prod_{i}", "").strip()
            if prod:
                _dos_p.append({
                    "produto":    prod,
                    "quantidade": st.session_state.get(f"op_dos_{_slug_r}_qtd_{i}", ""),
                    "unidade":    st.session_state.get(f"op_dos_{_slug_r}_un_{i}", ""),
                    "finalidade": st.session_state.get(f"op_dos_{_slug_r}_fin_{i}", ""),
                })
        if _dos_p:
            dados["dosagens"].extend(_dos_p)
            dados["dosagens_por_piscina"][pisc_nome] = _dos_p
    # Fallback: campos legados op_dos_prod_i
    if not dados["dosagens"]:
        for i in range(5):
            prod = st.session_state.get(f"op_dos_prod_{i}", "").strip()
            if prod:
                dados["dosagens"].append({
                    "produto":    prod,
                    "quantidade": st.session_state.get(f"op_dos_qtd_{i}", ""),
                    "unidade":    st.session_state.get(f"op_dos_un_{i}", ""),
                    "finalidade": st.session_state.get(f"op_dos_fin_{i}", ""),
                })
    # Fotos já salvas na pasta de rascunho
    _pasta_fotos_rasc = GENERATED_DIR / slugify_nome(nome_cond.strip()) / "fotos_rascunho"
    dados["fotos_rascunho"] = {"antes": [], "depois": [], "cmaq": [], "extras": []}
    if _pasta_fotos_rasc.exists():
        for _fp in sorted(_pasta_fotos_rasc.glob("rasc_*")):
            for _cat in ["antes", "depois", "cmaq", "extras"]:
                if f"rasc_{_cat}_" in _fp.name:
                    dados["fotos_rascunho"][_cat].append(_fp.name)
    return dados


def restaurar_rascunho_operador(rascunho: dict):
    """Restaura rascunho nos campos do formulário do operador."""
    if rascunho.get("data_visita"):
        st.session_state["op_data_visita"] = rascunho["data_visita"]
    if rascunho.get("operador"):
        st.session_state["op_operador"] = rascunho["operador"]
    if rascunho.get("obs"):
        st.session_state["op_obs_campo"] = rascunho["obs"]
    if rascunho.get("problemas"):
        st.session_state["op_problemas"] = rascunho["problemas"]
    if rascunho.get("resp_local"):
        st.session_state["op_resp_local"] = rascunho["resp_local"]
    if rascunho.get("parecer"):
        st.session_state["op_parecer_visita"] = rascunho["parecer"]
    if rascunho.get("assinatura_responsavel_b64"):
        st.session_state["op_assinatura_responsavel_b64"] = rascunho.get("assinatura_responsavel_b64", "")
    if rascunho.get("assinatura_responsavel_data"):
        st.session_state["op_assinatura_responsavel_data"] = rascunho.get("assinatura_responsavel_data", "")
    if "op_apos_ativo" in rascunho:
        st.session_state["op_apos_ativo"] = bool(rascunho.get("op_apos_ativo"))
    _param_apos = rascunho.get("parametros_apos", {}) if isinstance(rascunho.get("parametros_apos", {}), dict) else {}
    _map_restore_apos = {
        "ph_apos": "op_ph_apos",
        "cloro_livre_apos": "op_crl_apos",
        "cloro_total_apos": "op_ct_apos",
        "alcalinidade_apos": "op_alc_apos",
        "dureza_apos": "op_dc_apos",
        "cianurico_apos": "op_cya_apos",
    }
    for _campo_apos, _key_apos in _map_restore_apos.items():
        _valor_apos = _param_apos.get(_campo_apos) or rascunho.get(_campo_apos, "")
        if _valor_apos not in (None, ""):
            st.session_state[_key_apos] = str(_valor_apos).replace(".", ",")
    # Parâmetros por piscina
    for p in rascunho.get("piscinas", []):
        abrev = _slug_piscina_operador(p.get("nome", ""))
        for campo, key in [
            ("ph", f"op_{abrev}_ph"), ("cloro_livre", f"op_{abrev}_crl"),
            ("cloro_total", f"op_{abrev}_ct"), ("alcalinidade", f"op_{abrev}_alc"),
            ("dureza", f"op_{abrev}_dc"), ("cianurico", f"op_{abrev}_cya"),
            ("turbidez", f"op_{abrev}_turbidez"), ("orp", f"op_{abrev}_orp"),
            ("tds", f"op_{abrev}_tds"), ("temperatura", f"op_{abrev}_temperatura"),
        ]:
            if p.get(campo) not in (None, ""):  # "0" é medição válida
                st.session_state[key] = str(p[campo])
        # Compatibilidade: rascunhos salvos com os campos pós-tratamento dentro da piscina.
        for _campo_apos, _key_apos in _map_restore_apos.items():
            if p.get(_campo_apos) and not st.session_state.get(_key_apos):
                st.session_state[_key_apos] = str(p.get(_campo_apos)).replace(".", ",")
    # Dosagens: o formulário usa chaves por piscina (op_dos_<slug>_prod_<i>).
    # Rascunhos antigos só têm a lista geral: ela vai para a primeira piscina.
    _dos_por_pisc = rascunho.get("dosagens_por_piscina")
    if not isinstance(_dos_por_pisc, dict) or not _dos_por_pisc:
        _primeira = next((p.get("nome") for p in rascunho.get("piscinas", []) if p.get("nome")), "Piscina Adulto")
        _dos_por_pisc = {_primeira: rascunho.get("dosagens", [])}
    for _nome_pisc_d, _lista_d in _dos_por_pisc.items():
        _slug_d = _slug_piscina_operador(_nome_pisc_d)
        for i, d in enumerate((_lista_d or [])[:5]):
            st.session_state[f"op_dos_{_slug_d}_prod_{i}"] = str(d.get("produto", "") or "")
            st.session_state[f"op_dos_{_slug_d}_qtd_{i}"]  = str(d.get("quantidade", "") if d.get("quantidade") is not None else "")
            st.session_state[f"op_dos_{_slug_d}_un_{i}"]   = str(d.get("unidade", "") or "")
            st.session_state[f"op_dos_{_slug_d}_fin_{i}"]  = str(d.get("finalidade", "") or "")


def aplicar_restauracao_pendente_operador():
    """Aplica restauração pendente antes de instanciar os widgets do formulário."""
    rasc = st.session_state.pop("_rascunho_operador_pendente", None)
    if not rasc:
        return False
    restaurar_rascunho_operador(rasc)
    st.session_state["_rascunho_operador_restaurado_msg"] = True
    return True


_RE_CAMPO_PISCINA_OP = re.compile(r"^op_(?!dos_).+_(ph|crl|ct|alc|dc|cya|turbidez|orp|tds|temperatura)$")
_RE_CAMPO_DOSAGEM_OP = re.compile(r"^op_dos_.+_(prod|qtd|un|fin)_\d+$")


def limpar_formulario_operador():
    """Esvazia os campos da visita do operador (antes da criação dos widgets).

    Cobre também piscinas com nome personalizado e as dosagens por piscina."""
    ss = st.session_state
    for pisc in ["adulto", "infantil", "family", "outra"]:
        for k in ["ph", "crl", "ct", "alc", "dc", "cya", "turbidez", "orp", "tds", "temperatura"]:
            ss[f"op_{pisc}_{k}"] = ""
    for i in range(5):
        for c in ["prod", "qtd", "un", "fin"]:
            ss[f"op_dos_{c}_{i}"] = ""
    for k in list(ss.keys()):
        if _RE_CAMPO_PISCINA_OP.match(str(k)) or _RE_CAMPO_DOSAGEM_OP.match(str(k)):
            ss[k] = ""
        elif str(k).startswith("_sug_pisc_"):
            ss.pop(k, None)
    ss["op_obs_campo"] = ""
    ss["op_problemas"] = ""
    ss["op_resp_local"] = ""
    ss["op_parecer_visita"] = "✅ Satisfatório"
    ss["op_assinatura_responsavel_b64"] = ""
    ss["op_assinatura_responsavel_data"] = ""
    ss["_op_ass_canvas_nonce"] = ss.get("_op_ass_canvas_nonce", 0) + 1
    for _k_apos in ["op_ph_apos", "op_crl_apos", "op_ct_apos", "op_alc_apos", "op_dc_apos", "op_cya_apos"]:
        ss[_k_apos] = ""
    ss["op_apos_ativo"] = False


def _chave_fotos_operador(categoria: str) -> str:
    """Chave do upload de fotos do operador; muda ao trocar de condomínio para que
    as fotos de um local não continuem anexadas (nem sejam gravadas) no outro."""
    nonce = st.session_state.get("_op_fotos_nonce", 0)
    return f"op_fotos_{categoria}" if not nonce else f"op_fotos_{categoria}__{nonce}"


def trocar_condominio_operador(anterior: str, novo: str) -> bool:
    """Isola o formulário ao trocar de condomínio: guarda o rascunho do anterior
    (só se houver conteúdo) e limpa campos e fotos antes de exibir o novo.

    Se o rascunho do anterior não puder ser guardado (falha, exceção ou assinatura
    coletada, que o rascunho local não guarda), nada é limpo: grava o motivo em
    _op_troca_bloqueada e retorna False para a tela manter o condomínio anterior."""
    ss = st.session_state
    motivo = ""
    if anterior:
        try:
            dados = coletar_rascunho_operador(anterior, ss.get("_op_piscinas_form") or ["Piscina Adulto"])
            tem_conteudo = (
                any(str(v).strip() for p in dados.get("piscinas", []) for k, v in p.items() if k != "nome")
                or dados.get("dosagens")
                or any(str(dados.get(k) or "").strip() for k in ("obs", "problemas", "resp_local", "assinatura_responsavel_b64"))
            )
            if str(dados.get("assinatura_responsavel_b64") or "").strip():
                motivo = "há uma assinatura do responsável coletada, e ela não fica guardada no rascunho"
            elif tem_conteudo and not salvar_rascunho_operador(anterior, dados, salvar_sheets=False):
                motivo = "não foi possível salvar o rascunho"
        except Exception as e:
            motivo = f"não foi possível salvar o rascunho ({type(e).__name__})"
    if motivo:
        ss["_op_troca_bloqueada"] = {"anterior": anterior, "novo": novo, "motivo": motivo}
        return False
    ss.pop("_op_troca_bloqueada", None)
    limpar_formulario_operador()
    ss["_op_fotos_nonce"] = ss.get("_op_fotos_nonce", 0) + 1
    ss.pop(f"_rascunho_visto_{slugify_nome(novo)}", None)
    ss["_op_cond_form"] = novo
    return True


def chave_fotos_rt() -> str:
    """Chave do upload de fotos do relatório RT; muda quando o RT troca de condomínio."""
    nonce = st.session_state.get("_rt_fotos_nonce", 0)
    return "rel_fotos_upload" if not nonce else f"rt_fotos_upload_{nonce}"


def uploads_fotos_rt_legiveis() -> list:
    """Arquivos do upload de fotos RT que abrem como imagem.

    Os ilegíveis ficam fora do relatório e vão para _rt_fotos_ilegiveis (nome só na
    tela). O log recebe só extensão, tamanho, início do SHA-256 e tipo do erro,
    uma vez por arquivo, sem nome nem conteúdo."""
    import io as _io
    import logging as _logging
    ss = st.session_state
    legiveis, ilegiveis = [], []
    logados = set(ss.get("_rt_fotos_ilegiveis_logados") or [])
    for up in ss.get(chave_fotos_rt()) or []:
        try:
            dados = bytes(up.getvalue())
        except Exception as erro:  # upload interrompido: sem bytes para ler
            dados, erro_leitura = b"", erro
        else:
            erro_leitura = None
            try:
                with Image.open(_io.BytesIO(dados)) as _img:
                    _img.verify()
            except Exception as erro:
                erro_leitura = erro
        if erro_leitura is None:
            legiveis.append(up)
            continue
        nome = str(getattr(up, "name", "") or "arquivo sem nome")
        ilegiveis.append(nome)
        digest = hashlib.sha256(dados).hexdigest()
        if digest not in logados:
            logados.add(digest)
            _logging.getLogger("aqua.rt_fotos").warning(
                "Foto do relatorio RT ilegivel ignorada: extensao=%s tamanho=%d sha256=%s erro=%s",
                Path(nome).suffix.lower() or "-", len(dados), digest[:12], type(erro_leitura).__name__)
    ss["_rt_fotos_ilegiveis"] = ilegiveis
    ss["_rt_fotos_ilegiveis_logados"] = sorted(logados)
    return legiveis


class _FotoPendenteRT:
    """Foto selecionada antes de carregar o contexto, no formato que sincronizar_fotos lê."""
    def __init__(self, name, dados):
        self.name, self._dados = name, dados

    def getvalue(self):
        return self._dados


def processar_fotos_rt() -> tuple[str, list, int]:
    """Incorpora o upload de fotos RT ao contexto carregado e mostra o resultado.

    Chamada logo depois do uploader, antes de qualquer contagem. As fotos só entram no
    relatório com condomínio e período carregados (rel_origem_dados). A tela separa
    arquivos selecionados de fotos incorporadas e avisa sobre arquivos ilegíveis.
    Retorna (chave do contexto, fotos incorporadas, quantidade de fotos novas)."""
    from utils.rt_contexto import ler_fotos, sincronizar_fotos
    ss = st.session_state
    selecionadas = ss.get(chave_fotos_rt()) or []
    legiveis = uploads_fotos_rt_legiveis()
    chave = str(ss.get("rel_origem_dados") or "")
    fotos, novas = [], 0
    if not chave:
        # O "Carregar" faz st.rerun() antes deste uploader, e o Streamlit descarta os
        # arquivos dele (o navegador continua mostrando os nomes). Guarda as fotos
        # legíveis selecionadas sem contexto para incorporá-las ao contexto carregado.
        if legiveis:
            ss["_rt_fotos_pendentes"] = [(str(getattr(up, "name", "") or "foto"), bytes(up.getvalue()))
                                         for up in legiveis]
        else:
            ss.pop("_rt_fotos_pendentes", None)
    if chave:
        try:
            antes = {f["sha256"] for f in ler_fotos(ss, chave)}
            pendentes = ss.pop("_rt_fotos_pendentes", None)
            if pendentes:
                hashes_upload = ss.get("_rt_upload_hashes")
                sincronizar_fotos(ss, chave, [_FotoPendenteRT(n, b) for n, b in pendentes])
                ss["_rt_upload_hashes"] = hashes_upload  # pendentes não são anexos do uploader atual
            fotos = sincronizar_fotos(ss, chave, legiveis)
            novas = len({f["sha256"] for f in fotos} - antes)
        except (ValueError, KeyError, TypeError) as erro:
            fotos = []
            st.warning(f"Fotografias do rascunho: {erro}")
    if selecionadas and not chave:
        st.warning(f"⚠️ Carregue o condomínio e o período para anexar as fotos. "
                   f"{len(selecionadas)} arquivo(s) selecionado(s), nenhum incorporado ao relatório ainda. "
                   "As fotos válidas entram no relatório do condomínio que você carregar.")
    elif selecionadas:
        st.info(f"📷 {len(selecionadas)} arquivo(s) selecionado(s) no upload · "
                f"{len(fotos)} foto(s) incorporada(s) ao relatório deste condomínio e período.")
    elif fotos:
        st.info(f"📷 {len(fotos)} foto(s) incorporada(s) ao relatório deste condomínio e período.")
    for nome in ss.get("_rt_fotos_ilegiveis") or []:
        st.warning(f"⚠️ Não foi possível ler a foto “{nome}”. Ela não foi incorporada ao relatório; "
                   "envie a imagem em JPG, PNG ou WEBP.")
    return chave, fotos, novas


# Campos de texto do relatório RT: na troca de condomínio recebem "" (gravado antes dos
# widgets, o valor vazio chega à tela). Os demais campos rel_ (seleções, marcações) saem
# do session_state e voltam ao padrão.
_RT_OP_PREFIXOS_TEXTO = ("rel_analise_", "rel_obs_", "rel_foto_legenda_", "rel_dos_")
_RT_OP_CAMPOS = ("rel_endereco_condominio", "rel_cnpj_condominio", "rel_representante", "rel_cpf_cnpj_representante",
                 "rel_diagnostico", "rel_parecer_complemento_rt", "rel_art_numero", "rel_observacoes_gerais", "rel_cep")
# Fora do rascunho por condomínio: período, data de emissão, nome (vem da seleção),
# contadores recalculados pelo próprio fluxo, uploads e seletores com índice próprio
# (rel_art_modo_rt2025/rel_art_numero_rt2025 são refeitos a partir de rel_art_numero/status).
_RT_OP_FORA_DO_RASCUNHO = {"rel_mes_referencia", "rel_ano_referencia", "rel_data_emissao", "rel_nome_condominio",
                           "rel_analises_total", "rel_verificacoes_semanais", "rel_fotos_upload",
                           "rel_pdf_visita_importador", "rel_regerar_pdf_visita_idx", "rel_status_agua_select",
                           "rel_art_modo_rt2025", "rel_art_numero_rt2025"}


def _campos_rt_do_condominio() -> dict:
    """Todos os campos rel_ que pertencem ao condomínio (análises, dosagens, observações,
    parecer, identificação, ART, EPI, NBR...), com os valores atuais."""
    ss = st.session_state
    return {k: ss[k] for k in list(ss.keys())
            if str(k).startswith("rel_") and k not in _RT_OP_FORA_DO_RASCUNHO}


def limpar_formulario_rt_operador():
    """Esvazia os dados específicos do condomínio no fluxo RT do operador
    (antes da criação dos widgets), para que nada de um local passe ao outro."""
    ss = st.session_state
    for k, v in _campos_rt_do_condominio().items():
        if isinstance(v, str) and (str(k).startswith(_RT_OP_PREFIXOS_TEXTO) or k in _RT_OP_CAMPOS):
            ss[k] = ""
        else:
            ss.pop(k, None)  # seleções/marcações voltam ao padrão; ART nunca é presumida para outro condomínio
    for k in _RT_OP_CAMPOS:
        ss.setdefault(k, "")
    for k in ("rel_art_modo_rt2025", "rel_art_numero_rt2025"):
        ss.pop(k, None)
    ss["_rt_fotos_nonce"] = ss.get("_rt_fotos_nonce", 0) + 1


def _rascunho_rt_operador_path(cond: str) -> Path:
    """Um arquivo por sessão e condomínio: outra sessão nunca lê nem sobrescreve este rascunho."""
    ss = st.session_state
    if not ss.get("_rt_op_sessao"):
        ss["_rt_op_sessao"] = os.urandom(6).hex()
    return GENERATED_DIR / slugify_nome(cond) / f"_rascunho_rt_operador_{ss['_rt_op_sessao']}.json"


def trocar_condominio_rt_operador(anterior: str, novo: str) -> bool:
    """Troca de condomínio no fluxo RT do operador sem descartar o que não foi salvo.

    Todos os campos do condomínio (ver _campos_rt_do_condominio) vão para um rascunho
    local desta sessão, com o período, antes da limpeza; a gravação é conferida lendo o
    arquivo de volta. Se algum campo não puder ser guardado, se a gravação falhar ou se
    houver fotos anexadas (o upload não pode ser guardado), nada é limpo: grava o motivo
    em _rt_troca_bloqueada e retorna False.
    Ao chegar a um condomínio com rascunho do mesmo período, os dados dele voltam uma
    única vez (o arquivo é apagado), sobre o formulário recém-limpo: edições feitas
    depois nunca são sobrescritas. Rascunho de outro mês não volta."""
    ss = st.session_state
    motivo = ""
    try:
        if ss.get(chave_fotos_rt()):
            motivo = "há fotos anexadas, e elas não ficam guardadas no rascunho"
        elif anterior:
            campos = _campos_rt_do_condominio()
            nao_gravaveis = [k for k, v in campos.items() if not (isinstance(v, (str, int, float, bool)) or v is None)]
            if nao_gravaveis:
                motivo = "o campo " + ", ".join(sorted(nao_gravaveis)[:3]) + " não pode ser guardado no rascunho"
            elif any(str(v if v is not None else "").strip() for v in campos.values()):
                dados = {"condominio": anterior, "mes": str(ss.get("rel_mes_referencia") or ""),
                         "ano": str(ss.get("rel_ano_referencia") or ""), "campos": campos}
                caminho = _rascunho_rt_operador_path(anterior)
                caminho.parent.mkdir(parents=True, exist_ok=True)
                caminho.write_text(json.dumps(dados, ensure_ascii=False), encoding="utf-8")
                if json.loads(caminho.read_text(encoding="utf-8")).get("campos") != campos:
                    motivo = "não foi possível confirmar o rascunho salvo"
    except Exception as e:
        motivo = f"não foi possível salvar o rascunho ({type(e).__name__})"
    if motivo:
        ss["_rt_troca_bloqueada"] = {"anterior": anterior, "novo": novo, "motivo": motivo}
        return False
    ss.pop("_rt_troca_bloqueada", None)
    limpar_formulario_rt_operador()
    ss.pop("_rt_rascunho_restaurado", None)
    ss.pop("_rt_restore_erro", None)
    try:
        caminho = _rascunho_rt_operador_path(novo)
        if caminho.exists():
            dados = json.loads(caminho.read_text(encoding="utf-8"))
            if (dados.get("mes"), dados.get("ano")) == (str(ss.get("rel_mes_referencia") or ""),
                                                       str(ss.get("rel_ano_referencia") or "")):
                for k, v in (dados.get("campos") or {}).items():
                    if str(k).startswith("rel_") and k not in _RT_OP_FORA_DO_RASCUNHO:
                        ss[k] = v
                ss["_rt_rascunho_restaurado"] = novo
                caminho.unlink()  # restaurado uma única vez; ao sair de novo é guardado outra vez
    except Exception as e:
        # O condomínio novo começa vazio; o arquivo fica no disco e o usuário é avisado.
        ss["_rt_restore_erro"] = f"{type(e).__name__}: {e}"[:200]
    return True


# Widgets rel_ criados com index=/value= próprios (gravar a chave geraria aviso do Streamlit)
_RT_CAMPOS_NAO_REAFIRMAR = {"rel_status_agua_select", "rel_art_modo_rt2025", "rel_art_numero_rt2025"}


def preservar_campos_rt():
    """Regrava os campos rel_ do relatório RT do escritório antes dos widgets.

    O Streamlit só reenvia ao navegador o valor gravado na mesma execução: sem isto,
    um valor gravado antes (mês padrão, dados do cliente carregado) aparece vazio na
    tela e o próximo envio, como o upload de uma foto, devolve o vazio ao servidor.
    A regravação também impede que um st.rerun() acima dos campos descarte os
    valores dos widgets ainda não desenhados."""
    ss = st.session_state
    for k in [k for k in ss.keys() if str(k).startswith("rel_")]:
        if k in _RASCUNHO_RT_NAO_RESTAURAR or k in _RT_CAMPOS_NAO_REAFIRMAR:
            continue  # uploads não aceitam valor via session_state; os demais têm índice próprio
        try:
            ss[k] = ss[k]
        except Exception:
            pass  # widget já desenhado nesta execução: o valor já está na tela


def periodo_relatorio_valido(mes, ano) -> bool:
    """Mês 1–12 e ano com 4 dígitos (2000–2100). Sem período válido nada é importado."""
    m, a = str(mes or "").strip(), str(ano or "").strip()
    return m.isdigit() and 1 <= int(m) <= 12 and len(a) == 4 and a.isdigit() and 2000 <= int(a) <= 2100


def _valores_importaveis_rt() -> dict:
    """Campos que a importação de visitas preenche: análises, dosagens e observações gerais."""
    ss = st.session_state
    return {k: ss.get(k) for k in list(ss.keys())
            if str(k).startswith(("rel_analise_", "rel_dos_")) or k == "rel_observacoes_gerais"}


def _preenchidos(valores: dict) -> dict:
    return {k: v for k, v in valores.items() if str(v if v is not None else "").strip()}


def tabela_rt_livre_para_importar() -> bool:
    """True se a tabela está vazia ou idêntica à última importação (sem edição do usuário).
    Dados digitados ou restaurados de rascunho nunca são sobrescritos automaticamente."""
    atuais = _preenchidos(_valores_importaveis_rt())
    return not atuais or atuais == _preenchidos(st.session_state.get("_rel_autoimport_snapshot") or {})


def registrar_importacao_rt(periodo: str):
    """Guarda o que a importação preencheu, para reconhecer depois se houve edição."""
    st.session_state["_rel_autoimport_snapshot"] = _valores_importaveis_rt()
    st.session_state["_rel_autoimport_periodo"] = periodo


def retirar_importacao_rt() -> str:
    """Esvazia os valores da última importação (só chamar com a tabela sem edição).
    Retorna o período que foi retirado ("" se não havia importação)."""
    ss = st.session_state
    for k in _preenchidos(ss.pop("_rel_autoimport_snapshot", None) or {}):
        ss[k] = ""
    ss["rel_lancamentos_origem"] = ""  # sem lançamentos importados na tabela
    return ss.pop("_rel_autoimport_periodo", "")


# ── Identidade dos dados da tabela do relatório RT ───────────────────────────
# Cada conjunto de análises pertence a uma empresa + cliente (ID estável do cadastro;
# nome apenas para relatório avulso) + período. A chave fica em rel_origem_dados (vai
# junto no rascunho); rascunhos antigos sem ela têm origem desconhecida.
_META_TABELA_RT = ("_rel_autoimport_snapshot", "_rel_autoimport_periodo", "_rel_autoimport_assinatura")


def identidade_dados_rt(empresa: str, situacao: dict, nome_condominio: str, mes, ano) -> dict:
    """Identidade do relatório atual. "comprovada" é False quando o cliente não pode ser
    identificado com segurança (nome duplicado ou semelhante a outro cadastro)."""
    periodo = f"{str(mes or '').strip().zfill(2)}/{str(ano or '').strip()}"
    id_cli = str((situacao or {}).get("id_cliente") or "").strip()
    cliente = f"id:{id_cli}" if id_cli else f"nome:{normalizar_texto_busca(nome_condominio)}"
    return {
        "chave": f"{empresa or 'aqua_gestao'}|{cliente}|{periodo}",
        "rotulo": f"{str(nome_condominio or '').strip()} ({periodo})",
        "nome_periodo": f"{normalizar_texto_busca(nome_condominio)}|{periodo}",
        "comprovada": (situacao or {}).get("status") in ("ok", "ambiguo"),
    }


def _tabela_rt_tem_dados() -> bool:
    ss = st.session_state
    conteudo = dict(_valores_importaveis_rt())
    conteudo.update({k: v for k, v in ss.items() if str(k).startswith(("rel_obs_", "rel_rec_"))
                    or k in ("rel_diagnostico", "rel_parecer_complemento_rt", "rel_art_numero",
                             "rel_fotos_preservadas", "rel_nbr_11238", "rel_nr_26", "rel_nr_06")})
    return bool(_preenchidos(conteudo))


def _relatorio_rt_preservar_localmente() -> bool:
    """Garante que o conteúdo RT da tela está gravado no disco local antes da troca.

    O registro local (utils.rascunho_sync) é a cópia autoritativa, gravado de forma
    atômica antes de qualquer envio; a sincronização com a planilha é reenviada
    depois. Retorna True quando o conteúdo atual já está num registro local não
    descartado (mesmo hash) ou foi gravado agora numa chave nova e conferido por
    releitura. Nenhuma cópia existente é alterada. Retorna False só se a
    gravação local falhar — aí a troca continua bloqueada.
    """
    from utils.rascunho_sync import escrever_atomico, hash_conteudo
    ss = st.session_state
    atual = _relatorio_rt_coletar_rascunho()
    if not _relatorio_rt_tem_conteudo(atual.get("campos")):
        return True  # nada digitado: nada a preservar
    gestor = _relatorio_rt_gestor_sync()
    digest = hash_conteudo(atual)
    for arquivo in sorted(gestor.pasta.glob("*.json")):
        try:
            registro = gestor.ler(json.loads(arquivo.read_text(encoding="utf-8"))["chave"])
        except Exception:
            continue
        if registro and registro["estado"] != "descartado" and registro["hash"] == digest:
            return True
    backup = f"{RASCUNHO_RT_USUARIO}#s#{os.urandom(6).hex()}"
    atual["_chave"] = backup
    gestor.preparar(backup, atual, local_apenas=_rascunho_backend() == "local")
    escrever_atomico(_relatorio_rt_arquivo_local(backup), atual)
    conferido = gestor.ler(backup)
    if not conferido or conferido["hash"] != digest:
        return False
    if _rascunho_backend() != "local":
        pendentes = list(ss.get("_rt_rasc_sync_pendente") or [])
        if backup not in pendentes:
            pendentes.append(backup)
        ss["_rt_rasc_sync_pendente"] = pendentes
        ss.setdefault("_rt_rasc_aviso", f"Cópia local pendente de envio {_rascunho_destino('a')}.")
    return True


def relatorio_rt_resultado_salvamento_manual() -> str:
    """Classifica um salvamento manual não confirmado na planilha.

    "pendente": falha de conexão; o conteúdo da tela está gravado no disco
    local e será reenviado. "conflito": a planilha tem versão divergente desta
    chave (as duas foram preservadas). "erro": nem a cópia local foi garantida.
    """
    ss = st.session_state
    motivo = f"{ss.get('_rt_rasc_aviso', '')} {ss.get('_relatorio_rt_autosave_erro', '')}"
    try:
        preservado = _relatorio_rt_preservar_localmente()
    except Exception as e:
        ss["_relatorio_rt_autosave_erro"] = f"{type(e).__name__}: {e}"
        return "erro"
    if not preservado:
        return "erro"
    return "conflito" if "divergente" in motivo else "pendente"


def _guardar_rascunho_rt_antes_da_troca(restauracao_explicita: bool = False) -> bool:
    """Preserva o contexto RT atual antes de trocar condomínio/período ou restaurar.

    Antes, a troca só prosseguia se o envio à planilha fosse confirmado na hora:
    uma falha transitória do Sheets (cota, rede, consulta de confirmação) bloqueava
    a troca de período ("Troca bloqueada…", o mês voltava ao anterior) e a
    restauração de outro rascunho, mesmo com o conteúdo já gravado no disco.
    Agora basta a cópia local íntegra (conferida); o envio segue pendente e é
    reenviado automaticamente. Falha da gravação local continua bloqueando.
    """
    ss = st.session_state
    try:
        ss["_rt_rasc_ref"] = {}
        gravado = _relatorio_rt_salvar_rascunho("troca_condominio")
    except Exception as e:
        ss["_relatorio_rt_autosave_erro"] = str(e)
        gravado = False
    if not gravado:
        try:
            gravado = _relatorio_rt_preservar_localmente()
        except Exception as e:
            ss["_relatorio_rt_autosave_erro"] = f"{type(e).__name__}: {e}"
            gravado = False
    if not gravado:
        ss["_rt_contexto_erro"] = "Troca bloqueada: não foi possível preservar o rascunho. Tente novamente após recuperar o armazenamento."
        return False
    _relatorio_rt_chave_sessao(nova=True)
    ss["_rt_rasc_ref"] = None
    return True

def guardar_tabela_rt(origem: str, rotulo: str = "", gravar_rascunho: bool = True, restauracao_explicita: bool = False) -> bool:
    """Transação: persiste o contexto completo antes de limpar qualquer campo."""
    from utils.rt_contexto import campos, limpar, sincronizar_fotos
    ss = st.session_state
    atual = ss.get("_rt_contexto_identificacao") or {}
    solicitados = {k: ss.get(k) for k in ("rel_nome_condominio", "rel_mes_referencia", "rel_ano_referencia")}
    # Nome/período digitados já podem ser do destino; o rascunho ainda é da origem.
    for k, v in atual.items():
        ss[k] = v
    try:
        if "chave_fotos_rt" in globals():
            sincronizar_fotos(ss, origem, uploads_fotos_rt_legiveis())
        valores = campos(ss)
        if gravar_rascunho:
            salvo = (_guardar_rascunho_rt_antes_da_troca(restauracao_explicita=True)
                     if restauracao_explicita else _guardar_rascunho_rt_antes_da_troca())
            if not salvo:
                return False
    except Exception as e:
        ss["_rt_contexto_erro"] = f"Troca bloqueada: {type(e).__name__}: {e}"
        return False
    ss.setdefault("_rel_por_identidade", {})[origem] = {
        "valores": valores, "meta": {k: ss.get(k) for k in _META_TABELA_RT if k in ss},
        "rotulo": rotulo or ss.get("rel_origem_rotulo", "")}
    limpar(ss)
    ss.update(solicitados)
    for k in _META_TABELA_RT:
        ss.pop(k, None)
    ss.pop("_rt_contexto_erro", None)
    return True

def recuperar_tabela_rt(chave: str) -> bool:
    """Devolve à tela a tabela guardada para esta identidade (uma única vez)."""
    ss = st.session_state
    guardado = (ss.get("_rel_por_identidade") or {}).pop(chave, None)
    if not guardado:
        return False
    for k, v in guardado["valores"].items():
        ss[k] = v
    for k, v in guardado["meta"].items():
        ss[k] = v
    return True


def conciliar_identidade_tabela_rt(identidade: dict) -> dict:
    """Garante que a tabela na tela pertence à identidade atual (chamar antes dos widgets).

    - mesma origem: nada muda;
    - tabela vazia: assume a identidade atual e recupera o que estiver guardado para ela;
    - origem conhecida e diferente: guarda a tabela sob a origem, deixa a tela vazia e
      recupera a tabela guardada da identidade atual (troca de condomínio ou período);
    - origem desconhecida (rascunho antigo) com dados: não associa; pede revisão.
    Retorna {"conflito", "guardada_de", "recuperada"}."""
    ss = st.session_state
    chave = identidade["chave"]
    origem = str(ss.get("rel_origem_dados") or "")
    resultado = {"conflito": "", "guardada_de": "", "recuperada": False}
    if origem == chave:
        return resultado
    if (not identidade["comprovada"] and origem
            and ss.get("rel_origem_nome_periodo") == identidade.get("nome_periodo")):
        # Mesmo condomínio e período na tela; só o cadastro ficou duvidoso (ex.: nome
        # duplicado cadastrado depois). A tabela fica como está e a geração é bloqueada.
        resultado["conflito"] = "identidade_nao_comprovada"
        return resultado
    if not origem and ss.get("_rt_origem_desconhecida"):
        resultado["conflito"] = "origem_desconhecida"
        return resultado
    if not origem and not _tabela_rt_tem_dados():
        resultado["recuperada"] = recuperar_tabela_rt(chave)
    elif not origem:
        resultado["conflito"] = "origem_desconhecida"
        return resultado
    else:
        # Identificação cadastral comprovada pode iniciar outro período do MESMO
        # cliente. ART, análises e textos técnicos continuam estritamente por período.
        mesma_pessoa = origem.rsplit("|", 1)[0] == chave.rsplit("|", 1)[0]
        cadastro = {k: ss.get(k, "") for k in ("rel_cnpj_condominio", "rel_endereco_condominio",
                    "rel_representante", "rel_cpf_cnpj_representante")} if mesma_pessoa else {}
        if not guardar_tabela_rt(origem):
            resultado["conflito"] = "falha_salvamento"
            return resultado
        resultado["guardada_de"] = (ss.get("_rel_por_identidade", {}).get(origem) or {}).get("rotulo") or origem
        resultado["recuperada"] = recuperar_tabela_rt(chave)
        if not resultado["recuperada"]:
            ss.update(cadastro)
    ss["_rt_contexto_identificacao"] = {k: ss.get(k) for k in ("rel_nome_condominio", "rel_mes_referencia", "rel_ano_referencia")}
    ss["rel_origem_dados"] = chave
    ss["rel_origem_rotulo"] = identidade["rotulo"]
    ss["rel_origem_nome_periodo"] = identidade.get("nome_periodo", "")
    return resultado


def resolver_origem_desconhecida_rt(identidade: dict, associar: bool):
    """Ação explícita do usuário para tabela de origem desconhecida: associar à identidade
    atual depois de revisar, ou guardar à parte (sem apagar) e começar com a tabela vazia."""
    ss = st.session_state
    if not associar:
        if not guardar_tabela_rt(f"origem_desconhecida|{datetime.now():%Y%m%d%H%M%S%f}", "origem desconhecida"):
            return False
    ss.pop("_rt_origem_desconhecida", None)
    ss["rel_origem_dados"] = identidade["chave"]
    ss["rel_origem_rotulo"] = identidade["rotulo"]
    ss["rel_origem_nome_periodo"] = identidade.get("nome_periodo", "")


def fotos_rt_de_outra_identidade(chave: str, ha_fotos: bool) -> str:
    """Registra a identidade em que as fotos do upload foram anexadas; devolve o rótulo
    dessa identidade se for diferente da atual ("" quando não há conflito)."""
    ss = st.session_state
    if not ha_fotos:
        ss.pop("_rel_fotos_origem", None)
        return ""
    origem = ss.setdefault("_rel_fotos_origem", {"chave": chave, "rotulo": ss.get("rel_origem_rotulo", "")})
    return "" if origem["chave"] == chave else (origem.get("rotulo") or origem["chave"])


def buscar_cep(cep: str) -> dict:
    """Consulta ViaCEP via requests com fallback para urllib."""
    cep_limpo = re.sub(r"\D", "", cep or "")
    if len(cep_limpo) != 8:
        return {}
    url = f"https://viacep.com.br/ws/{cep_limpo}/json/"
    # Tentativa 1: requests (mais compatível com Streamlit Cloud)
    try:
        import requests as _req
        resp = _req.get(url, timeout=5)
        if resp.status_code == 200:
            dados = resp.json()
            if not dados.get("erro"):
                return dados
    except Exception:
        pass
    # Tentativa 2: urllib fallback
    try:
        import urllib.request, json as _json
        with urllib.request.urlopen(url, timeout=5) as resp:
            dados = _json.loads(resp.read().decode())
        if not dados.get("erro"):
            return dados
    except Exception:
        pass
    return {}


def filtrar_clientes_por_empresa(clientes: list, empresa_ativa: str) -> list:
    """Filtra clientes por empresa compativel.
    empresa_ativa: 'aqua_gestao' | 'bem_star'
    Critério: servico marcado OU campo empresa do cadastro bate.
    Clientes sem empresa/servico definido aparecem em ambos (legado).
    """
    resultado = []
    for c in clientes:
        _status_cliente = normalizar_texto_busca(c.get("status", "Ativo"))
        if _status_cliente in ("inativo", "desativado", "excluido", "cancelado"):
            continue

        servicos = _normalizar_servicos_cliente(c)
        # Campo empresa do cadastro (col M do Sheets)
        _emp = str(c.get("empresa", "") or "").strip().lower()
        _tem_empresa = bool(_emp)
        _is_bem_star = "bem star" in _emp or "bemstar" in _emp
        _is_aqua     = "aqua" in _emp
        _tem_servico_limpeza = servicos.get("limpeza", False)
        _tem_servico_rt      = servicos.get("rt", False)
        _sem_definicao = not _tem_empresa and not _tem_servico_limpeza and not _tem_servico_rt

        if empresa_ativa == "bem_star":
            # Inclui se: servico limpeza marcado, OU empresa = bem star, OU sem definicao (legado)
            if _tem_servico_limpeza or _is_bem_star or _sem_definicao:
                resultado.append(c)
        elif empresa_ativa == "aqua_gestao":
            # Inclui se: servico rt marcado, OU empresa = aqua gestao, OU sem definicao (legado)
            if _tem_servico_rt or _is_aqua or _sem_definicao:
                resultado.append(c)
    return resultado


def _cliente_vinculado_aqua_gestao_strict(cliente: dict | None) -> bool:
    """Retorna True somente quando o vínculo de empresa inclui Aqua Gestão.

    Regras para seleção RT:
    - usa exclusivamente o campo de vínculo de empresa do cadastro;
    - não usa serviço executado/visita RT como critério de inclusão;
    - não considera vínculo vazio como Aqua.
    """
    cliente = cliente or {}
    empresa_original = str(cliente.get("empresa", "") or "")
    if not empresa_original.strip():
        return False

    empresa_norm = normalizar_texto_busca(empresa_original)
    if not empresa_norm:
        return False
    if "aqua" in empresa_norm:
        return True
    if "ambas" in empresa_norm:
        return True
    return False


def _resolver_condominios_rt_permitidos_exatos(condominios_permitidos: list[str], condominios_aqua_exatos: list[str]) -> list[str]:
    """Resolve permissões de condomínio preservando o nome original cadastrado."""
    return _resolver_condominios_permitidos_exatos(
        condominios_permitidos or [],
        list(condominios_aqua_exatos or []),
    )


def _listar_condominios_rt_aqua(clientes: list[dict] | None, condominios_permitidos: list[str] | None = None,
                                incluir_todos_preview: bool = True) -> list[str]:
    """Lista condomínios do modo RT usando vínculo estrito com Aqua Gestão.

    Preserva exatamente o nome original cadastrado em `clientes[*]["nome"]`.
    """
    nomes_aqua = []
    vistos = set()

    for cliente in clientes or []:
        nome_original = str((cliente or {}).get("nome", "") or "")
        if not nome_original.strip():
            continue

        status_cliente = normalizar_texto_busca((cliente or {}).get("status", "Ativo"))
        if status_cliente in ("inativo", "desativado", "excluido", "cancelado"):
            continue

        if not _cliente_vinculado_aqua_gestao_strict(cliente):
            continue

        chave_nome = normalizar_texto_busca(nome_original)
        if chave_nome in vistos:
            continue
        vistos.add(chave_nome)
        nomes_aqua.append(nome_original)

    permitidos = []
    acesso_total = False
    for nome_perm in condominios_permitidos or []:
        nome_perm = str(nome_perm or "")
        if not nome_perm.strip():
            continue
        if _normalizar_chave_acesso(nome_perm).strip() == "todos":
            acesso_total = True
            continue
        permitidos.append(nome_perm)

    if acesso_total:
        nomes_filtrados = list(nomes_aqua)
    elif permitidos:
        nomes_filtrados = _resolver_condominios_rt_permitidos_exatos(permitidos, nomes_aqua)
    else:
        nomes_filtrados = list(nomes_aqua)

    nomes_filtrados = sorted(nomes_filtrados, key=lambda n: normalizar_texto_busca(n))

    if incluir_todos_preview and nomes_filtrados:
        return ["TODOS"] + nomes_filtrados
    return nomes_filtrados


def _empresa_ativa_codigo() -> str:
    """Retorna o painel administrativo ativo.

    O operador não usa esta escolha; operador é filtrado por PIN/condomínios.
    Fallback: lê admin_empresa_fixa se empresa_ativa não estiver definida corretamente.
    """
    valor = st.session_state.get("empresa_ativa", "")
    if valor not in ("aqua_gestao", "bem_star"):
        # Fallback para empresa fixada no login admin
        valor = st.session_state.get("admin_empresa_fixa", "")
    if valor not in ("aqua_gestao", "bem_star"):
        valor = "aqua_gestao"
    st.session_state["empresa_ativa"] = valor
    return valor

def _empresa_ativa_nome() -> str:
    return "Bem Star Piscinas" if _empresa_ativa_codigo() == "bem_star" else "Aqua Gestão"



def _servicos_padrao_empresa_ativa() -> dict:
    """Serviços gravados automaticamente no cadastro conforme o painel ativo."""
    return {"rt": _empresa_ativa_codigo() == "aqua_gestao", "limpeza": _empresa_ativa_codigo() == "bem_star"}


def _filtrar_clientes_painel_ativo(clientes: list[dict]) -> list[dict]:
    """Mantém os clientes separados visualmente por empresa/painel."""
    return filtrar_clientes_por_empresa(clientes or [], _empresa_ativa_codigo())


def _normalizar_lista_textos_unicos(valores) -> list[str]:
    resultado = []
    vistos = set()
    for item in valores or []:
        valor = re.sub(r"\s+", " ", str(item or "").strip())
        if not valor:
            continue
        chave = _normalizar_chave_acesso(valor)
        if chave in vistos:
            continue
        vistos.add(chave)
        resultado.append(valor)
    return resultado


def _empresa_para_servicos(empresa: str) -> dict:
    emp = _normalizar_chave_acesso(empresa)
    if emp == "ambas":
        return {"rt": True, "limpeza": True}
    if "bem star" in emp:
        return {"rt": False, "limpeza": True}
    return {"rt": True, "limpeza": False}


def _normalizar_servicos_cliente(dados: dict | None) -> dict:
    dados = dados or {}
    servicos = dados.get("servicos") if isinstance(dados.get("servicos"), dict) else {}
    rt = bool(servicos.get("rt"))
    limpeza = bool(servicos.get("limpeza"))
    if not rt and not limpeza:
        legado = _empresa_para_servicos(str(dados.get("empresa", "Aqua Gestão") or "Aqua Gestão"))
        rt = legado["rt"]
        limpeza = legado["limpeza"]
    return {"rt": rt, "limpeza": limpeza}


def _cliente_relatorio_visita_bem_star_sem_rt(nome_condominio: str) -> bool:
    """Define se o PDF de visita deve usar identidade Bem Star.

    Regra: condomínios com limpeza Bem Star e sem RT Aqua devem gerar o
    relatório operacional Bem Star, sem assinatura/rodapé de RT Aqua.
    """
    nome_condominio = str(nome_condominio or "").strip()
    if not nome_condominio:
        return False

    cliente = {}
    try:
        cliente = sheets_carregar_cliente_por_nome(nome_condominio) or {}
    except Exception:
        cliente = {}

    if not cliente:
        try:
            for _c in sheets_listar_clientes_completo():
                if nomes_condominio_equivalentes(_c.get("nome", ""), nome_condominio):
                    cliente = _c
                    break
        except Exception:
            cliente = {}

    servicos = _normalizar_servicos_cliente(cliente)
    return bool(servicos.get("limpeza")) and not bool(servicos.get("rt"))


def _servicos_para_empresa(servicos: dict | None) -> str:
    servicos_norm = _normalizar_servicos_cliente({"servicos": servicos or {}})
    if servicos_norm.get("rt") and servicos_norm.get("limpeza"):
        return "Ambas"
    if servicos_norm.get("limpeza"):
        return "Bem Star Piscinas"
    return "Aqua Gestão"


def _carregar_dados_cliente_local(nome_condominio: str) -> dict:
    nome_limpo = str(nome_condominio or "").strip()
    if not nome_limpo:
        return {}
    pasta = GENERATED_DIR / slugify_nome(nome_limpo)
    if not pasta.exists():
        return {}
    dados = carregar_dados_condominio(pasta) or {}
    if not isinstance(dados, dict):
        return {}
    # O JSON local também é criado por fluxos que não definem empresa (visita do
    # operador, rascunhos, relatórios). Só marca o vínculo como definido quando
    # o próprio arquivo traz empresa ou serviços; caso contrário o padrão
    # "Aqua Gestão" de _normalizar_servicos_cliente passava a valer sobre a
    # coluna M do Sheets e movia clientes Bem Star para a Aqua Gestão.
    dados["_empresa_definida_localmente"] = _vinculo_empresa_definido(dados)
    dados["servicos"] = _normalizar_servicos_cliente(dados)
    dados["operadores_vinculados"] = _normalizar_lista_textos_unicos(dados.get("operadores_vinculados", []))
    dados["empresa"] = _servicos_para_empresa(dados.get("servicos"))
    return dados


def _vinculo_empresa_definido(dados: dict | None) -> bool:
    """True quando o registro informa empresa (texto) ou algum serviço marcado."""
    dados = dados or {}
    servicos = dados.get("servicos") if isinstance(dados.get("servicos"), dict) else {}
    if servicos.get("rt") or servicos.get("limpeza"):
        return True
    return bool(str(dados.get("empresa", "") or "").strip())


def _servicos_cliente_resolvidos(cliente_sheets: dict | None, dados_locais: dict | None) -> dict:
    """Resolve o vínculo de empresa com a planilha como fonte principal.

    Ordem: coluna M (Empresa) do Sheets → empresa/serviços gravados no JSON
    local → padrão legado. O JSON local é efêmero no Streamlit Cloud e todos
    os fluxos de cadastro/transferência gravam a coluna M antes dele.
    """
    cliente_sheets = cliente_sheets or {}
    dados_locais = dados_locais or {}
    if _vinculo_empresa_definido(cliente_sheets):
        return _normalizar_servicos_cliente({
            "servicos": cliente_sheets.get("servicos"),
            "empresa": cliente_sheets.get("empresa"),
        })
    if dados_locais.get("_empresa_definida_localmente"):
        return _normalizar_servicos_cliente({
            "servicos": dados_locais.get("servicos"),
            "empresa": dados_locais.get("empresa"),
        })
    return _normalizar_servicos_cliente({"empresa": "Aqua Gestão"})


def _enriquecer_cliente_com_dados_locais(cliente: dict | None) -> dict:
    cliente_final = dict(cliente or {})
    nome = str(cliente_final.get("nome", "") or "").strip()
    dados_locais = _carregar_dados_cliente_local(nome)

    servicos = _servicos_cliente_resolvidos(cliente_final, dados_locais)
    cliente_final["servicos"] = servicos
    cliente_final["empresa"] = _servicos_para_empresa(servicos)
    cliente_final["operadores_vinculados"] = _normalizar_lista_textos_unicos(
        dados_locais.get("operadores_vinculados", cliente_final.get("operadores_vinculados", []))
    )

    for chave in ["cnpj", "cep", "telefone", "contato", "endereco", "vol_adulto", "vol_infantil", "vol_family", "verificacoes_semanais", "analises_mensais_padrao"]:
        valor_local = dados_locais.get(chave)
        if chave.startswith("vol_") and cliente_final.get("cadastro_piscinas") is not None:
            continue
        if valor_local not in (None, ""):
            cliente_final[chave] = valor_local

    # Compatibilidade com nomes usados por versões anteriores do cadastro.
    _aliases_cliente = {
        "cnpj": ["cnpj_condominio", "documento_cliente", "cpf_cnpj"],
        "cep": ["cep_condominio", "codigo_postal"],
        "telefone": ["telefone_sindico", "celular", "whatsapp"],
        "contato": ["nome_sindico", "responsavel", "responsavel_contato"],
        "endereco": ["endereco_condominio", "endereco_completo"],
    }
    for _destino, _origens in _aliases_cliente.items():
        if cliente_final.get(_destino) not in (None, ""):
            continue
        for _origem in _origens:
            _valor_alias = dados_locais.get(_origem)
            if _valor_alias not in (None, ""):
                cliente_final[_destino] = _valor_alias
                break

    if dados_locais.get("endereco_condominio"):
        cliente_final["endereco"] = dados_locais.get("endereco_condominio", cliente_final.get("endereco", ""))
    if dados_locais.get("cnpj_condominio"):
        cliente_final["cnpj"] = dados_locais.get("cnpj_condominio", cliente_final.get("cnpj", ""))
    if dados_locais.get("nome_sindico") and not cliente_final.get("contato"):
        cliente_final["contato"] = dados_locais.get("nome_sindico", "")
    if cliente_final.get("cadastro_piscinas") is None:
        if "piscinas_extras" in dados_locais:
            cliente_final["piscinas_extras"] = dados_locais.get("piscinas_extras", [])
        cliente_final["tipos_piscinas"] = dados_locais.get("tipos_piscinas", {})

    return cliente_final


def carregar_imagem_corrigida_orientacao(origem):
    """Corrige orientação EXIF para preview no Streamlit sem alterar o upload original."""
    try:
        import io as _io
        from PIL import Image as _PILImg, ImageOps as _IOps

        if hasattr(origem, "getbuffer"):
            dados = bytes(origem.getbuffer())
        elif isinstance(origem, (str, Path)):
            dados = Path(origem).read_bytes()
        elif isinstance(origem, bytes):
            dados = origem
        else:
            return origem

        img = _PILImg.open(_io.BytesIO(dados))
        img = _IOps.exif_transpose(img)
        return img
    except Exception:
        return origem


def deduplicar_fotos(lista):
    """Remove fotos duplicadas de uma lista de uploads ou paths.

    Deduplica pelo hash do conteúdo, tanto de uploads quanto de arquivos existentes,
    para que a mesma foto como upload e como arquivo (ou em duas pastas) apareça uma
    vez só. Caminho inexistente ou ilegível é comparado pelo texto, como antes.
    Evita que rascunho + upload atual resultem em foto repetida no PDF.
    """
    resultado = []
    vistos = set()
    import hashlib as _hashlib

    for item in lista or []:
        try:
            if isinstance(item, (str, Path)):
                try:
                    chave = _hashlib.md5(Path(item).read_bytes()).hexdigest()
                except Exception:
                    chave = str(item)[:200]
            elif hasattr(item, "getvalue"):
                pos = item.tell() if hasattr(item, "tell") else None
                dados = item.getvalue()
                if pos is not None:
                    try:
                        item.seek(pos)
                    except Exception:
                        pass
                chave = _hashlib.md5(dados).hexdigest()
            elif hasattr(item, "read"):
                pos = item.tell() if hasattr(item, "tell") else None
                dados = item.read()
                if pos is not None:
                    try:
                        item.seek(pos)
                    except Exception:
                        pass
                chave = _hashlib.md5(dados).hexdigest()
            else:
                chave = str(item)
        except Exception:
            chave = str(item)

        if chave not in vistos:
            vistos.add(chave)
            resultado.append(item)

    return resultado


