def gerar_textos_automaticos_relatorio(analises: list[dict], avaliacao: dict) -> dict:
    observacoes = []
    recomendacoes = []
    detalhes = avaliacao.get("detalhes", [])
    informativos = [k for k in avaliacao.get("informativos", []) if k in ("tds", "temperatura")]
    nota_informativos = ("TDS e temperatura registrados para acompanhamento; não são classificados por leitura isolada."
                         if informativos else "")
    if avaliacao.get("status") == STATUS_NAO_AVALIADO:
        # Sem medição avaliável: não há diagnóstico, conformidade nem "ausência de desvios".
        observacoes.append("Sem medições físico-químicas válidas no período: não há base para apontar desvios nem conformidade.")
        observacoes.extend(avaliacao.get("atencoes", [])[:2])
        if nota_informativos:
            observacoes.append(nota_informativos)
        return {
            "diagnostico": (f"{TEXTO_NAO_AVALIADO}. Não há medições físico-químicas válidas registradas para o período de "
                            "referência; este relatório não emite diagnóstico da qualidade da água."),
            "observacoes": observacoes[:5],
            "recomendacoes": ["Registrar as medições físico-químicas do período (pH, CRL, CT, alcalinidade, dureza, CYA e "
                              "turbidez) para permitir a avaliação técnica."],
        }
    if detalhes:
        for detalhe in detalhes[:3]:
            observacoes.append(detalhe.replace("Linha", "Leitura"))
    if avaliacao.get("cloraminas_altas"):
        idx, valor = avaliacao["cloraminas_altas"][0]
        observacoes.append(f"Leitura {idx}: cloro combinado estimado em {str(valor).replace('.', ',')} mg/L, acima do limite de 0,6 mg/L da NBR 10818:2026, sugerindo formação de cloraminas e maior carga orgânica.")
        recomendacoes.append("Executar oxidação complementar / supercloração controlada e reavaliar CT, CL e cloro combinado.")
    if any("cloro total inferior" in d for d in detalhes):
        recomendacoes.append("Repetir as medições de cloro livre e total: cloro total inferior ao livre é inconsistente.")
    if any(d.split(": ", 1)[-1].lower().startswith("ph=") for d in detalhes):
        recomendacoes.append("Ajustar pH para o limite da NBR 10818:2026 (7,0–7,8; faixa ideal 7,4–7,6) e repetir a leitura após estabilização.")
    if any("cloro residual livre" in d for d in detalhes):
        recomendacoes.append("Revisar a dosagem de desinfetante e a demanda oxidante da água.")
    if any("ácido cianúrico" in d for d in detalhes):
        recomendacoes.append("Reavaliar o estabilizante e considerar renovação parcial de água quando tecnicamente indicada.")
    if any("alcalinidade total" in d for d in detalhes):
        recomendacoes.append("Corrigir alcalinidade total para aumentar a estabilidade do pH e reduzir flutuações operacionais.")
    if any("dureza cálcica" in d for d in detalhes):
        recomendacoes.append("Ajustar dureza cálcica para reduzir risco de corrosão ou incrustação.")
    if any(d.split(": ", 1)[-1].lower().startswith("turbidez=") for d in detalhes):
        recomendacoes.append("Verificar a filtração (retrolavagem e meio filtrante) e a clarificação; repetir a turbidez após a correção.")
    for atencao in avaliacao.get("atencoes", [])[:2]:
        observacoes.append(atencao)
    if avaliacao.get("atencoes"):
        from utils.normas_piscinas import RECOMENDACAO_ORP
        recomendacoes.append(RECOMENDACAO_ORP)
    if not detalhes and avaliacao.get("status") == "CONFORME":
        observacoes.insert(0, "Nenhuma leitura fora dos limites da ABNT NBR 10818:2026 nos parâmetros registrados no período.")
    if nota_informativos:
        observacoes.append(nota_informativos)
    if not recomendacoes:
        recomendacoes.append("Manter rotina de monitoramento, rastreabilidade de dosagens e controle técnico periódico.")

    diagnostico = []
    if avaliacao["status"] == "CONFORME":
        diagnostico.append("No período avaliado, as leituras registradas não apresentaram valores fora dos limites da ABNT NBR 10818:2026. A avaliação é parcial, limitada aos parâmetros e datas registrados, e não substitui o monitoramento operacional diário.")
    else:
        diagnostico.append("Foram observadas não conformidades físico-químicas que exigem ação corretiva e reavaliação técnica sequencial.")
    if avaliacao.get("cloraminas_altas"):
        diagnostico.append("A presença de cloro combinado acima do limite sugere formação de cloraminas, condição compatível com carga orgânica elevada, consumo do desinfetante e possível redução da eficiência sanitizante.")
    if detalhes:
        diagnostico.append("Resumo automático dos desvios: " + "; ".join(detalhes[:5]) + ".")

    return {
        "diagnostico": " ".join(diagnostico),
        "observacoes": observacoes[:5],
        "recomendacoes": recomendacoes[:5],
    }


_TEXTOS_AUTOMATICOS_AVALIACAO = (
    "O sistema registra fase operacional de correção",
    "No período avaliado, as leituras registradas",
    "Foram observadas não conformidades",
    "Parâmetros avaliados sem desvios críticos",
    "Nenhuma leitura fora dos limites",
)


def _texto_automatico_de_avaliacao(texto: str) -> bool:
    """Parecer/observação gerado automaticamente a partir de leituras (inválido sem dados)."""
    t = str(texto or "").strip()
    return any(t.startswith(p) for p in _TEXTOS_AUTOMATICOS_AVALIACAO)


def sincronizar_status_agua_widget(opcoes: list[str]) -> str:
    """Mantém o seletor "Status geral da água" igual a rel_status_agua.

    rel_status_agua é a fonte única (parecer automático, rascunho restaurado,
    limpeza). O seletor tem chave própria e o Streamlit ignora index= quando a
    chave já existe: o seletor mostrava o status antigo e, no fim da execução,
    sobrescrevia o status calculado. Uma escolha manual no seletor continua
    valendo, porque só se sincroniza quando rel_status_agua mudou por outra via
    desde a última execução. Chamar antes de criar o widget.
    """
    ss = st.session_state
    status = ss.get("rel_status_agua", "CONFORME")
    if status not in opcoes:
        status = opcoes[0]
    alterado_fora = ss.get("_rel_status_agua_sinc") != ss.get("rel_status_agua")
    if alterado_fora or ss.get("rel_status_agua_select") not in opcoes:
        ss["rel_status_agua_select"] = status
    ss["rel_status_agua"] = ss["rel_status_agua_select"]
    ss["_rel_status_agua_sinc"] = ss["rel_status_agua"]
    return ss["rel_status_agua"]


def aplicar_textos_automaticos_relatorio():
    analises = coletar_analises_relatorio()
    avaliacao = avaliar_conformidade_analises(analises)
    textos = gerar_textos_automaticos_relatorio(analises, avaliacao)

    # Nunca apaga parâmetros digitados. Só recalcula os campos textuais do parecer.
    st.session_state.rel_diagnostico = textos["diagnostico"]

    for i in range(5):
        chave_obs = f"rel_obs_{i}"
        texto_obs = textos["observacoes"][i] if i < len(textos["observacoes"]) else ""
        st.session_state[chave_obs] = texto_obs

    for i in range(5):
        chave_rec = f"rel_rec_texto_{i}"
        chave_prazo = f"rel_rec_prazo_{i}"
        chave_resp = f"rel_rec_resp_{i}"
        texto_rec = textos["recomendacoes"][i] if i < len(textos["recomendacoes"]) else ""
        st.session_state[chave_rec] = texto_rec
        st.session_state[chave_prazo] = "Imediato" if texto_rec and i == 0 else ("Próxima rotina" if texto_rec else "")
        st.session_state[chave_resp] = "Operação / RT" if texto_rec else ""

    # Não escrever diretamente na chave do selectbox após o widget existir.
    # EM CORREÇÃO manual é preservado só quando há medição avaliável.
    if avaliacao["status"] == STATUS_NAO_AVALIADO or st.session_state.get("rel_status_agua") != "EM CORREÇÃO":
        st.session_state["rel_status_agua"] = avaliacao["status"]


def montar_dados_relatorio() -> dict:
    nome_condominio = (st.session_state.get("rel_nome_condominio") or "").strip()
    representante = (st.session_state.get("rel_representante") or "").strip()
    dados_base = obter_snapshot_relatorio_independente()
    analises = coletar_analises_relatorio()
    avaliacao = avaliar_conformidade_analises(analises)
    status_manual = (st.session_state.get("rel_status_agua") or "CONFORME").strip()
    if avaliacao["status"] == STATUS_NAO_AVALIADO:
        status_final = STATUS_NAO_AVALIADO  # sem medição avaliável, nenhum status manual se aplica
    else:
        status_final = "EM CORREÇÃO" if status_manual == "EM CORREÇÃO" else avaliacao["status"]
    textos_auto = gerar_textos_automaticos_relatorio(analises, avaliacao)
    diagnostico_base = (st.session_state.get("rel_diagnostico") or "").strip() or textos_auto["diagnostico"]
    if status_final == STATUS_NAO_AVALIADO and _texto_automatico_de_avaliacao(diagnostico_base):
        diagnostico_base = textos_auto["diagnostico"]  # parecer automático antigo não vale sem dados

    recomendacoes = coletar_recomendacoes_relatorio()
    if not any(r["recomendacao"] for r in recomendacoes):
        recomendacoes = [{"recomendacao": t, "prazo": "Imediato" if i == 0 else "Próxima rotina", "responsavel": "Operação / RT"} for i, t in enumerate(textos_auto["recomendacoes"])]

    observacoes = coletar_observacoes_relatorio()
    if status_final == STATUS_NAO_AVALIADO:
        observacoes = [o for o in observacoes if not _texto_automatico_de_avaliacao(o)]
    if not any(observacoes):
        observacoes = textos_auto["observacoes"]

    # --- LÓGICA DE IDENTIDADE DINÂMICA ---
    empresa_atual = _empresa_ativa_nome()
    is_bem_star = "Bem Star" in empresa_atual

    from utils.rt_relatorio import MARCA_COMPLETA
    # Relatório RT usa a grafia ACQUA GESTÃO; EMPRESA_RT (contratos/aditivos) não muda.
    empresa_rt_dinamica = EMPRESA_BEM_STAR if is_bem_star else MARCA_COMPLETA
    _piscinas_rel = {"piscinas": [], "volume_total": None, "sem_distribuicao": False, "fonte": "bem_star"} if is_bem_star else _piscinas_relatorio_rt()
    _fotos_meta_rel = {} if is_bem_star else _metadados_fotos_contexto_rt()
    responsavel_dinamico = "Equipe Operacional" if is_bem_star else RESPONSAVEL_TÉCNICO
    assinatura_dinamica = "Bem Star Piscinas" if is_bem_star else RESPONSAVEL_TECNICO_ASSINATURA
    crq_dinamico = "N/A" if is_bem_star else CRQ
    qualificacao_dinamica = "Operação e Manutenção" if is_bem_star else QUALIFICACAO_RT
    _art_status_rel = normalizar_status_art(st.session_state.get("rel_art_status"))

    return {
        "empresa_rt": empresa_rt_dinamica,
        "responsavel_tecnico": responsavel_dinamico,
        "assinatura_rt_texto": assinatura_dinamica,
        "crq": crq_dinamico,
        "qualificacao": qualificacao_dinamica,
        "certificacoes": CERTIFICACOES_RT,
        "nome_condominio": nome_condominio,
        "cnpj_condominio": dados_base.get("cnpj_condominio", ""),
        "endereco_condominio": dados_base.get("endereco_condominio", ""),
        "representante": representante,
        "cpf_cnpj_representante": dados_base.get("cpf_sindico", ""),
        "tipo_atendimento": (st.session_state.get("rel_tipo_atendimento") or "Contrato ativo").strip(),
        "mes_referencia": (st.session_state.get("rel_mes_referencia") or "").strip(),
        "ano_referencia": (st.session_state.get("rel_ano_referencia") or "").strip(),
        "art_status": _art_status_rel,
        "art_numero": (st.session_state.get("rel_art_numero") or "").strip() if _art_status_rel == ART_EMITIDA else "N/A",
        "art_inicio": (st.session_state.get("rel_art_inicio") or "").strip() if _art_status_rel == ART_EMITIDA else "N/A",
        "art_fim": (st.session_state.get("rel_art_fim") or "").strip() if _art_status_rel == ART_EMITIDA else "N/A",
        "art_texto": "",
        "data_emissao": (st.session_state.get("rel_data_emissao") or hoje_br()).strip(),
        "status_agua": status_final,
        "diagnostico": diagnostico_base,
        "analises": analises,
        "dosagens": coletar_dosagens_relatorio(),
        "recomendacoes": recomendacoes,
        "observacoes": observacoes,
        "conformidades": coletar_conformidades_relatorio(),
        "epis": coletar_epis_relatorio(),
        "avaliacao_automatica": avaliacao,
        "piscinas_cadastro": _piscinas_rel,
        "fotos_meta": _fotos_meta_rel,
    }


def _metadados_fotos_contexto_rt() -> dict:
    """Legenda/piscina por SHA-256 das fotos do contexto atual (sem os bytes)."""
    from utils.rt_contexto import ler_fotos
    try:
        fotos = ler_fotos(st.session_state, str(st.session_state.get("rel_origem_dados") or ""))
    except (ValueError, KeyError, TypeError):
        return {}
    return {f["sha256"]: {k: v for k, v in f.items() if k != "bytes"} for f in fotos}


def validar_relatorio_mensal(dados_relatorio: dict) -> list[str]:
    erros = []
    if not dados_relatorio.get("nome_condominio"):
        erros.append("Informe o nome do condomínio/estabelecimento no próprio relatório antes de gerar.")
    if not dados_relatorio.get("mes_referencia"):
        erros.append("Informe o mês de referência do relatório.")
    if not dados_relatorio.get("ano_referencia"):
        erros.append("Informe o ano de referência do relatório.")
    if not TEMPLATE_RELATORIO.exists():
        erros.append("O arquivo relatorio_mensal.docx não foi localizado na pasta do projeto.")
    if not validar_data_br(dados_relatorio.get("data_emissao", "")):
        erros.append("Data de emissão do relatório inválida.")
    erros += validar_art(dados_relatorio.get("art_status"), dados_relatorio.get("art_numero"),
                         dados_relatorio.get("art_inicio"), dados_relatorio.get("art_fim"))
    return erros


def append_relatorio_fallback(doc: Document, dados_relatorio: dict):
    doc.add_page_break()
    doc.add_paragraph("COMPLEMENTO AUTOMÁTICO – DADOS ESTRUTURADOS DO RELATÓRIO MENSAL")
    doc.add_paragraph(f"Condomínio: {dados_relatorio['nome_condominio']}")
    doc.add_paragraph(f"Mês/Ano de referência: {dados_relatorio['mes_referencia']}/{dados_relatorio['ano_referencia']}")
    doc.add_paragraph(f"ART: {obter_status_art_texto(dados_relatorio)}")
    doc.add_paragraph(f"Data de emissão: {dados_relatorio['data_emissao']}")
    doc.add_paragraph(f"Responsável técnico: {dados_relatorio['assinatura_rt_texto']}")
    doc.add_paragraph(f"Certificações relevantes: {dados_relatorio['certificacoes']}")
    doc.add_paragraph(f"Status geral da água: {rotulo_status_agua(dados_relatorio['status_agua'])}")
    doc.add_paragraph(f"Diagnóstico técnico: {dados_relatorio['diagnostico']}")
    doc.add_paragraph("Base normativa referencial do relatório: Lei nº 2.800/1956; Decreto nº 85.877/1981; Lei nº 6.839/1980; Resolução CFQ nº 332/2025, alterada pela nº 345/2026; ABNT NBR 10339; NR-26; NR-06.")
    doc.add_paragraph("Nota técnica: análises microbiológicas não são realizadas no local e dependem de laboratório acreditado, sob responsabilidade de contratação do cliente.")

    doc.add_paragraph("Observações automáticas:")
    for obs in dados_relatorio["observacoes"]:
        if obs:
            doc.add_paragraph(f"• {obs}")

    doc.add_paragraph("Recomendações automáticas:")
    for item in dados_relatorio["recomendacoes"]:
        if item.get("recomendacao"):
            doc.add_paragraph(f"• {item['recomendacao']} | Prazo: {item.get('prazo','')} | Responsável: {item.get('responsavel','')}")


def _atualizar_tabela_limites_docx(doc: Document):
    """Substitui a tabela legada de faixas do modelo DOCX pelos limites da NBR 10818:2026."""
    from utils.normas_piscinas import texto_limite, texto_ideal
    linhas = {
        "ph": ["pH", texto_limite("ph"), texto_ideal("ph"), "—"],
        "cloro residual livre": ["Cloro Residual Livre (CRL)", texto_limite("crl"), texto_ideal("crl"), "mg/L"],
        "cloro total": ["Cloro Total", "Sem limite próprio", "Avaliar CC = CT - CRL (até 0,6)", "mg/L"],
        "alcalinidade": ["Alcalinidade Total", texto_limite("alcalinidade"), texto_ideal("alcalinidade"), "mg/L CaCO₃"],
        "dureza": ["Dureza Cálcica", texto_limite("dureza"), texto_ideal("dureza"), "mg/L CaCO₃"],
        "acido cianurico": ["Ácido Cianúrico (estabilizador)", texto_limite("cya"), texto_ideal("cya"), "mg/L"],
    }

    def _definir(cell, texto):
        pars = cell.paragraphs
        if not pars:
            cell.text = texto
            return
        runs = pars[0].runs
        if runs:
            runs[0].text = texto
            for r in runs[1:]:
                r.text = ""
        else:
            pars[0].add_run(texto)
        for extra in pars[1:]:
            for r in extra.runs:
                r.text = ""

    for tabela in doc.tables:
        if not tabela.rows or len(tabela.rows[0].cells) < 4:
            continue
        cab = normalizar_texto(tabela.rows[0].cells[0].text)
        if not cab.startswith("parametro (") or "nbr 10818" not in cab and "referencia operacional" not in cab:
            continue
        cab_cells = tabela.rows[0].cells
        for cell, texto in zip(cab_cells, ["Parâmetro (NBR 10818:2026)", "Limite aceitável", "Faixa ideal", "Unidade"]):
            _definir(cell, texto)
        for row in tabela.rows[1:]:
            nome = normalizar_texto(row.cells[0].text)
            for chave, valores in linhas.items():
                if nome.startswith(chave):
                    for cell, texto in zip(row.cells, valores):
                        _definir(cell, texto)
                    break


