def _materializar_fotos_remotas_bem_star(cliente: str, lancamentos: list[dict]) -> list:
    """Fotos das visitas sem arquivo local: Drive (original) e, na falta, base64.

    Grava cada imagem (JPEG, orientação EXIF corrigida) numa pasta persistente do
    cliente, nomeada pelo SHA-256 do conteúdo, para continuar disponível até o fim
    da montagem do PDF. Não altera visitas, Sheets ou Drive. Falhas ficam em
    st.session_state["_bs_fotos_avisos"] para a tela informar o usuário.
    """
    import base64 as _b64m
    import hashlib as _hl
    import io as _iom
    from PIL import Image as _PILm, ImageOps as _IOm

    categorias = ("antes", "depois", "cmaq", "extras")
    avisos = []
    caminhos = []
    if not lancamentos:
        st.session_state["_bs_fotos_avisos"] = avisos
        st.session_state["_bs_fotos_metadados_visitas"] = {}
        return caminhos
    pasta = GENERATED_DIR / slugify_nome(cliente) / "_fotos_relatorio_mensal_bs"

    def _gravar(dados: bytes) -> Path | None:
        try:
            pil = _IOm.exif_transpose(_PILm.open(_iom.BytesIO(dados)))
            buf = _iom.BytesIO()
            pil.convert("RGB").save(buf, format="JPEG", quality=88)
            conteudo = buf.getvalue()
        except Exception:
            return None
        pasta.mkdir(parents=True, exist_ok=True)
        destino = pasta / (_hl.sha256(conteudo).hexdigest() + ".jpg")
        if not destino.exists():
            destino.write_bytes(conteudo)
        return destino

    rotulos = {"antes": "Antes do tratamento", "depois": "Após o tratamento",
               "cmaq": "Casa de máquinas", "extras": "Outras fotos"}
    metadados = {}
    for lc in lancamentos:
        ident = str(lc.get("id_visita") or lc.get("data") or "visita").strip()
        data_lc = normalizar_data_visita(lc.get("data", ""))
        ids = []  # (id, categoria)
        for cat in categorias:
            ids.extend((i, cat) for i in (lc.get(f"fotos_{cat}_ids") or []))
        ids.extend((i, "antes") for i in (lc.get("fotos_drive_ids") or []))
        ids = list({str(i).strip(): (str(i).strip(), c) for i, c in ids if str(i or "").strip()}.values())
        obtidas = []
        falhas = 0

        def _registrar(caminho, cat):
            obtidas.append(caminho)
            legenda = f"Visita {ident} — {rotulos.get(cat, 'Foto')}" if lc.get("id_visita") else rotulos.get(cat, "Foto")
            metadados.setdefault(str(caminho), {"nome": caminho.name, "piscina": "", "data": data_lc, "legenda": legenda})

        for fid, cat in ids:
            try:
                dados = drive_baixar_foto(fid)
            except Exception:
                dados = None
            caminho = _gravar(dados) if dados else None
            if caminho:
                _registrar(caminho, cat)
            else:
                falhas += 1
        if not obtidas:
            # Cópia em base64 (lançamento local do modo campo): miniatura da mesma foto.
            for cat in categorias:
                for item in lc.get(f"fotos_{cat}_b64") or []:
                    try:
                        caminho = _gravar(_b64m.b64decode(item) if isinstance(item, str) else bytes(item))
                    except Exception:
                        caminho = None
                    if caminho:
                        _registrar(caminho, cat)
        if falhas and len(obtidas) < len(ids):
            avisos.append(f"{ident}: {falhas} foto(s) do Drive não puderam ser recuperadas.")
        caminhos.extend(obtidas)
    st.session_state["_bs_fotos_avisos"] = avisos
    st.session_state["_bs_fotos_metadados_visitas"] = metadados
    return caminhos


def _coletar_fotos_bem_star_preview(cliente: str, lancamentos: list[dict]) -> list:
    """Coleta as fotos de campo das visitas do relatório Bem Star.

    - fotos citadas nos lançamentos do período (nomes gravados pelo modo campo),
      procuradas na pasta fotos_campo do cliente; paths absolutos e uploads também valem;
    - sem nenhuma citada, usa as fotos de fotos_campo cujo nome traz a data (AAAAMMDD)
      de um dos lançamentos — nunca outros meses, assinaturas, fotos do relatório RT,
      pré-visualizações ou o rascunho, que ficam em outras pastas do mesmo cliente;
    - a mesma foto entra uma vez só (comparação pelo conteúdo).
    Não altera Sheets, Drive, dosagem ou modo operador.
    """
    fotos = []
    pasta_campo = GENERATED_DIR / slugify_nome(cliente) / "fotos_campo"

    def _add_foto(item):
        if not item:
            return

        # Uploads Streamlit ou objetos em memória: deixa o gerador tentar usar.
        if hasattr(item, "read") or hasattr(item, "getvalue") or hasattr(item, "getbuffer"):
            fotos.append(item)
            return

        try:
            p = Path(str(item))
            if not p.is_absolute():
                p = pasta_campo / p.name  # nomes gravados pelo modo campo
            if p.exists() and p.is_file():
                fotos.append(p)
        except Exception:
            pass

    datas_periodo = set()
    sem_arquivo_local = []  # visitas cujas fotos citadas não estão no disco deste servidor
    for lc in lancamentos or []:
        if not isinstance(lc, dict):
            continue
        _qtd_antes_lc = len(fotos)
        _data = normalizar_data_visita(lc.get("data", ""))
        if re.fullmatch(r"\d{2}/\d{2}/\d{4}", _data or ""):
            datas_periodo.add(_data[6:] + _data[3:5] + _data[:2])

        # Listas comuns dentro do payload.
        for chave_lista in (
            "fotos", "fotos_campo", "fotos_paths", "imagens",
            "fotos_antes", "fotos_depois", "fotos_casa_maquinas", "fotos_cmaq", "fotos_extras",
        ):
            valor = lc.get(chave_lista)
            if isinstance(valor, list):
                for item in valor:
                    _add_foto(item)
            else:
                _add_foto(valor)

        # Chaves individuais comuns.
        for chave in (
            "foto", "foto_antes", "foto_depois", "foto_casa_maquinas",
            "foto_casa_maquina", "imagem", "imagem_antes", "imagem_depois"
        ):
            _add_foto(lc.get(chave))
        if len(fotos) == _qtd_antes_lc:
            sem_arquivo_local.append(lc)

    # Visitas lidas do Sheets em outro servidor (Streamlit Cloud reinicia sem a
    # pasta fotos_campo): o payload traz só nomes e IDs do Drive. Antes nada era
    # buscado e o PDF mensal saía sem o registro fotográfico, sem aviso.
    fotos.extend(_materializar_fotos_remotas_bem_star(cliente, sem_arquivo_local))

    # Sem fotos citadas: fotos de campo gravadas nas datas das visitas do relatório.
    if not fotos and datas_periodo:
        try:
            if pasta_campo.exists():
                for p in sorted(pasta_campo.iterdir()):
                    m = re.match(r"^(?:antes|depois|cmaq|extras)_(\d{8})_\d{6}_", p.name)
                    if (p.is_file() and m and m.group(1) in datas_periodo
                            and p.suffix.lower() in (".jpg", ".jpeg", ".png", ".webp")):
                        fotos.append(p)
        except Exception:
            pass

    try:
        return deduplicar_fotos(fotos)
    except Exception:
        return fotos


def _bs_float(valor):
    """Converte valor textual em float, aceitando vírgula."""
    try:
        txt = str(valor or "").strip().replace(",", ".")
        txt = re.sub(r"[^0-9.\-]", "", txt)
        if txt in ("", "-", ".", "-."):
            return None
        return float(txt)
    except Exception:
        return None


def _bs_fmt_num(valor, casas=2):
    try:
        return f"{float(valor):.{casas}f}".replace(".", ",")
    except Exception:
        return "—"


def _bs_eh_segunda(data_visita: str) -> bool:
    """Indica se a visita ocorreu em uma segunda-feira."""
    try:
        data_normalizada = normalizar_data_visita(data_visita)
        return datetime.strptime(data_normalizada, "%d/%m/%Y").weekday() == 0
    except Exception:
        return False


def _bs_stats_valores(lancamentos, campo):
    vals = []
    for lc in lancamentos or []:
        if not isinstance(lc, dict):
            continue
        piscinas = lc.get("piscinas", [])
        base = piscinas[0] if piscinas and isinstance(piscinas[0], dict) else lc
        v = _bs_float(base.get(campo, lc.get(campo, "")))
        if v is not None:
            vals.append(v)

    if not vals:
        return {
            "n": 0,
            "min": None,
            "max": None,
            "media": None,
            "valores": [],
        }

    return {
        "n": len(vals),
        "min": min(vals),
        "max": max(vals),
        "media": sum(vals) / len(vals),
        "valores": vals,
    }


def _bs_conformidade(vals, minimo=None, maximo=None, menor_que=None):
    if not vals:
        return 0, 0, 0

    total = len(vals)
    ok = 0
    for v in vals:
        if menor_que is not None:
            if v < menor_que:
                ok += 1
        else:
            if minimo <= v <= maximo:
                ok += 1

    perc = round((ok / total) * 100) if total else 0
    return ok, total, perc


def _bs_dia_semana_resumo():
    dias = st.session_state.get("bs_rel_dias_semana", []) or []
    mapa = {
        "Segunda-feira": "segunda-feira",
        "Terça-feira": "terça-feira",
        "Quarta-feira": "quarta-feira",
        "Quinta-feira": "quinta-feira",
        "Sexta-feira": "sexta-feira",
        "Sábado": "sábado",
        "Domingo": "domingo",
    }
    if not dias:
        return "conforme cronograma operacional definido"
    return ", ".join(mapa.get(d, d.lower()) for d in dias)


def gerar_parecer_tecnico_bem_star(lancamentos: list[dict], cliente: str = "", mes: str = "", ano: str = "") -> str:
    """Resumo descritivo das leituras, sem diagnóstico ou declaração de conformidade."""
    from utils.bem_star_mensal import PARAMETROS, numero, expandir
    registros = expandir(lancamentos)
    linhas = [f"Registro operacional de {mes}/{ano} para {cliente}. "
              f"Foram identificadas {len({l['data'] for l in registros})} data(s) com registro nesta piscina. "
              "O resumo descreve os dados informados, sem atestar conformidade normativa ou condições de segurança."]
    for campo, label, unidade in PARAMETROS:
        vals = [numero(l.get(campo)) for l in registros if numero(l.get(campo)) is not None]
        if vals:
            fmt = lambda v: f"{v:.2f}".replace(".", ",")
            linhas.append(f"{label}: {len(vals)} medição(ões), mínimo {fmt(min(vals))}, "
                          f"média {fmt(sum(vals)/len(vals))} e máximo {fmt(max(vals))} {unidade}.".strip())
        else:
            linhas.append(f"{label}: sem medição informada para esta piscina no período.")
    linhas.append("Manter o registro das medições efetivamente realizadas e das dosagens aplicadas, com data e identificação da piscina. "
                  "Resultados ausentes ou divergentes devem ser conferidos; a interpretação técnica deve ser realizada por profissional habilitado no escopo próprio.")
    return "\n\n".join(linhas)


def _piscinas_cadastradas_cliente(cliente: dict | None) -> list[str]:
    """Nomes das piscinas do cadastro do cliente (vazio quando não configurado)."""
    try:
        from utils.rt_relatorio import piscinas_do_cliente
        return [p["nome"] for p in piscinas_do_cliente(cliente).get("piscinas", []) if p.get("nome")]
    except Exception:
        return []


def _coletar_contexto_relatorio_bem_star() -> dict:
    csr_sel = str(st.session_state.get("csr_sel_relatorio", "") or "").strip()
    csr_mes = str(st.session_state.get("csr_mes_rel", "") or "").strip()
    csr_ano = str(st.session_state.get("csr_ano_rel", "") or str(datetime.now().year)).strip()
    csr_operador_nome = str(st.session_state.get("csr_operador_rel", "") or "").strip()
    csr_obs_geral = str(st.session_state.get("csr_obs_rel", "") or "").strip()

    erros = []
    if not csr_sel:
        erros.append("Selecione o cliente Bem Star.")
    if not csr_mes:
        erros.append("Informe o mês do relatório Bem Star.")
    if not csr_ano:
        erros.append("Informe o ano do relatório Bem Star.")
    if erros:
        return {"ok": False, "erros": erros, "mensagem": " | ".join(erros)}

    clientes = _carregar_clientes_bem_star_relatorio()
    csr_dados_sel = clientes.get(csr_sel, {})

    pasta_csr = GENERATED_DIR / slugify_nome(csr_sel)
    pasta_csr.mkdir(parents=True, exist_ok=True)
    dados_rel_json = carregar_dados_condominio(pasta_csr) if pasta_csr.exists() else {}
    lancamentos_local = (dados_rel_json or {}).get("lancamentos_campo", [])
    _situacao_csr = situacao_visitas_condominio(csr_sel) if csr_sel else {"status": "ok", "visitas": [], "bloqueio": "", "aviso": ""}
    lancamentos_sheets = _situacao_csr["visitas"]
    if _situacao_csr["bloqueio"]:
        lancamentos_local = []  # a pasta local é identificada só pelo nome: não confirma o cadastro
    if _situacao_csr.get("status") == "falha":
        # Falha de consulta não é ausência de visitas: não gera relatório incompleto.
        return {"ok": False, "erros": [_situacao_csr["aviso"]], "mensagem": _situacao_csr["aviso"]}
    if not origem_validada(_situacao_csr, chave_validacao_origem("bem_star", csr_sel, csr_mes, csr_ano)):
        msg = (f"{_situacao_csr['aviso']} " + (
            "O cliente não pode ser identificado com segurança: diferencie os nomes no cadastro para gerar."
            if _situacao_csr.get("status") == "bloqueio" else
            "Confirme a origem dos dados na tela do relatório Bem Star para gerar com as visitas identificadas."))
        return {"ok": False, "erros": [msg], "mensagem": msg}

    from utils.bem_star_mensal import (unir_agenda, token_pool, materializar_fotos,
                                       deduplicar_lancamentos, canonizar_nomes_piscinas)
    # A mesma visita existe no JSON local e no Sheets com campos diferentes
    # (fotos em base64, horário de gravação): comparar o JSON inteiro deixava
    # as duas cópias e duplicava as leituras. A chave é o ID da visita.
    lancamentos_todos = deduplicar_lancamentos((lancamentos_local or []) + (lancamentos_sheets or []))

    lancamentos_csr = _filtrar_lancamentos_preview_por_mes(lancamentos_todos, csr_mes, csr_ano)

    piscinas_cadastradas = _piscinas_cadastradas_cliente(csr_dados_sel)
    lancamentos_agenda = _bs_coletar_lancamentos_agenda_manual()
    lanc_para_relatorio = unir_agenda(lancamentos_csr, lancamentos_agenda, piscinas_cadastradas)
    if not lanc_para_relatorio:
        msg = "Nenhum lançamento encontrado. Preencha a agenda mensal ou registre visitas no modo campo."
        if _situacao_csr["aviso"]:
            msg = f"{_situacao_csr['aviso']} {msg}"
        return {"ok": False, "erros": [msg], "mensagem": msg}
    tipos = {}
    for linha in lanc_para_relatorio:
        nome = linha["piscina"]
        tipo = st.session_state.get(f"bs_mensal_tipo_{token_pool(nome)}", linha["tipo_piscina"])
        linha["tipo_piscina"] = tipo
        tipos[nome] = tipo
    piscinas_sel = canonizar_nomes_piscinas(
        st.session_state.get("bs_mensal_piscinas", []) or [],
        piscinas_cadastradas + [l["piscina"] for l in lanc_para_relatorio],
    )
    for nome in piscinas_sel:
        tipos.setdefault(nome, st.session_state.get(f"bs_mensal_tipo_{token_pool(nome)}", "Não informado"))
    fotos_paths = _coletar_fotos_bem_star_preview(csr_sel, lancamentos_csr)
    # Anexos mensais só entram por manifesto do contexto exato; nenhuma varredura de pasta/Drive.
    fotos_mensais, metadados = materializar_fotos(
        st.session_state.get("bs_mensal_fotos", []) or [],
        st.session_state.get("_bs_rel_contexto"), GENERATED_DIR, baixar=drive_baixar_foto,
    ) if st.session_state.get("bs_mensal_fotos") else ([], {})
    fotos_paths = deduplicar_fotos(list(fotos_paths) + fotos_mensais)
    # Legendas das fotos das visitas recuperadas do Drive (anexos mensais prevalecem).
    metadados = {**(st.session_state.get("_bs_fotos_metadados_visitas") or {}), **(metadados or {})}
    return {
        "ok": True, "cliente": csr_sel, "mes": csr_mes, "ano": csr_ano,
        "operador": csr_operador_nome, "obs_geral": csr_obs_geral,
        "parecer_tecnico": st.session_state.get("bs_rel_parecer_tecnico", ""),
        "dados_cliente": csr_dados_sel, "pasta": pasta_csr,
        "lancamentos": lanc_para_relatorio, "fotos": fotos_paths,
        "fotos_metadados": metadados, "tipos_piscinas": tipos,
        "piscinas": piscinas_sel,
        "piscinas_cadastradas": piscinas_cadastradas,
        "origem_fotos": "visitas do período e anexos mensais isolados" if fotos_paths else "sem fotos",
    }


def preparar_contexto_rt():
    """Concilia a solicitação antes de qualquer prévia ou widget do relatório."""
    preservar_campos_rt()  # também protege widgets de um rerun cancelado no modo RT
    ss = st.session_state
    nome = str(ss.get("rel_nome_condominio") or "").strip()
    mes, ano = ss.get("rel_mes_referencia"), ss.get("rel_ano_referencia")
    if not nome or not periodo_relatorio_valido(mes, ano):
        return
    situacao = situacao_visitas_condominio(nome)
    # Uma falha de consulta não autoriza associar dados a um cliente desconhecido.
    if situacao.get("status") == "falha":
        return
    identidade = identidade_dados_rt(ss.get("empresa_ativa", "aqua_gestao"), situacao, nome, mes, ano)
    resultado = conciliar_identidade_tabela_rt(identidade)
    if resultado.get("guardada_de"):
        ss["_rel_tabela_guardada_msg"] = resultado["guardada_de"]
    if resultado.get("recuperada"):
        ss["_rel_contexto_recuperado"] = True
    if resultado.get("conflito") == "falha_salvamento":
        ss.pop("_rt_upload_hashes", None)  # cleanup de widget não é remoção explícita de foto
        if ss.get("_rt_cond_form") is not None or ss.get("rt_op_sel_cond") is not None:
            ss["_rt_cond_reverter"] = ss.get("rel_nome_condominio")
            ss["_rt_periodo_reverter"] = (ss.get("rel_mes_referencia"), ss.get("rel_ano_referencia"))
        st.rerun()  # a transação já recolocou nome/período da origem


def _piscinas_relatorio_rt() -> dict:
    """Piscinas do cliente identificado por ID estável (Aqua Gestão), lidas do cadastro.

    Relatório avulso (sem ID) ou cadastro indisponível: lista vazia, sem inferência
    por nome. A consulta usa o cache existente de sheets_listar_clientes_completo."""
    from utils.rt_relatorio import piscinas_do_cliente
    vazio = {"piscinas": [], "volume_total": None, "sem_distribuicao": False, "fonte": "avulso"}
    partes = str(st.session_state.get("rel_origem_dados") or "").split("|")
    if len(partes) != 3 or partes[0] != "aqua_gestao" or not partes[1].startswith("id:"):
        return vazio
    return _piscinas_cliente_por_id(partes[1][3:])


def _piscinas_cliente_por_id(id_cli: str) -> dict:
    from utils.rt_relatorio import piscinas_do_cliente
    vazio = {"piscinas": [], "volume_total": None, "sem_distribuicao": False}
    try:
        clientes = sheets_listar_clientes_completo() or []
    except Exception:
        return {**vazio, "fonte": "indisponivel"}
    cliente = next((c for c in clientes if str(c.get("id") or "").strip() == str(id_cli).strip()), None)
    if not cliente:
        return {**vazio, "fonte": "nao_encontrado"}
    return {**piscinas_do_cliente(cliente), "fonte": "cadastro",
            "aviso": cliente.get("erro_cadastro_piscinas", "")}


def gerar_relatorio_consolidado_rt(tipo: str, indice: int, ano: int, art: dict, parecer: str = "") -> dict:
    """Consolidado trimestral/semestral/anual a partir das visitas identificadas.

    Somente leitura: consulta as visitas já validadas por cliente (ID estável) e
    grava o PDF em pasta própria da identidade + período. Não altera rascunhos,
    análises mensais, ART mensal nem cadastros."""
    import hashlib
    from utils.rt_relatorio import (consolidar, data_leitura, graficos_consolidados, linhas_de_lancamentos,
                                    meses_do_periodo, rotulo_periodo)
    from utils.pdf_rt_consolidado import gerar_pdf_consolidado
    ss = st.session_state
    if ss.get("empresa_ativa", "aqua_gestao") != "aqua_gestao":
        return {"ok": False, "erros": ["Relatório consolidado RT é exclusivo da ACQUA GESTÃO."]}
    nome = str(ss.get("rel_nome_condominio") or "").strip()
    if not nome:
        return {"ok": False, "erros": ["Carregue o cliente cadastrado antes de gerar o consolidado."]}
    try:
        meses = meses_do_periodo(tipo, indice, ano)
    except (ValueError, TypeError) as e:
        return {"ok": False, "erros": [str(e)]}
    erros = validar_art(art.get("status"), art.get("numero"), art.get("inicio"), art.get("fim"))
    situacao = situacao_visitas_condominio(nome)
    if situacao.get("status") != "ok":
        erros.append("Consulta das visitas indisponível ou cliente sem identificação segura; consolidado suspenso.")
    id_cli = str(situacao.get("id_cliente") or "").strip()
    if not id_cli:
        erros.append("O consolidado exige cliente cadastrado com ID estável (relatório avulso não é aceito).")
    if erros:
        return {"ok": False, "erros": erros}
    permitidos = set(meses)
    visitas = [v for v in situacao.get("visitas", []) if (lambda d: d and (d.month, d.year) in permitidos)(data_leitura(v.get("data")))]
    linhas = []
    for item in linhas_de_lancamentos(visitas):
        dados = item["dados"]
        linhas.append({"data": item["lancamento"].get("data", ""), "piscina": item["piscina"],
                       **{k: str(dados.get(k, item["lancamento"].get(k, "")) or "") for k in
                          ("ph", "cloro_livre", "cloro_total", "alcalinidade", "dureza", "cianurico")}})
    cons = consolidar(linhas, meses)
    rotulo = rotulo_periodo(tipo, indice, ano)
    chave = f"aqua_gestao|id:{id_cli}|{tipo}|{indice}|{ano}"
    pasta = GENERATED_DIR / "_rt_consolidados" / hashlib.sha256(chave.encode()).hexdigest()
    pasta.mkdir(parents=True, exist_ok=True)
    graficos = graficos_consolidados(cons, pasta, nome, rotulo)
    ctx = {"tipo": tipo, "periodo_rotulo": rotulo, "meses": cons["meses"], "nome_condominio": nome,
           "endereco": ss.get("rel_endereco_condominio", ""), "consolidado": cons,
           "piscinas_cadastro": _piscinas_cliente_por_id(id_cli), "art": art, "graficos": graficos,
           "responsavel": RESPONSAVEL_TÉCNICO, "crq": "CRQ 024025748", "data_emissao": hoje_br(),
           "parecer": str(parecer or "").strip()}
    pdf = pasta / limpar_nome_arquivo(f"{datetime.now():%Y%m%d}_{nome}_RT_CONSOLIDADO_{tipo}_{indice}_{ano}.pdf")
    ok, erro = gerar_pdf_consolidado(ctx, pdf, garantir_logo_aqua_oficial())
    return {"ok": ok, "pdf": pdf, "erros": [erro] if erro else [], "visitas": len(visitas),
            "piscinas": list(cons["piscinas"]), "rotulo": rotulo}


def validar_contexto_rt(relatorio: str = "rt") -> list[str]:
    """Porta única para DOCX/PDF de prévia e final, antes de qualquer escrita."""
    from utils.rt_contexto import ler_fotos
    ss = st.session_state
    erros = []
    nome = str(ss.get("rel_nome_condominio") or "").strip()
    mes, ano = ss.get("rel_mes_referencia"), ss.get("rel_ano_referencia")
    if ss.get("empresa_ativa", "aqua_gestao") != "aqua_gestao":
        erros.append("Relatório RT não pode usar o contexto de outra empresa.")
    if not nome or not periodo_relatorio_valido(mes, ano):
        return erros + ["Informe condomínio e período válido antes de gerar prévia ou relatório."]
    situacao = situacao_visitas_condominio(nome)
    identidade = identidade_dados_rt(ss.get("empresa_ativa", "aqua_gestao"), situacao, nome, mes, ano)
    if not origem_validada(situacao, chave_validacao_origem(relatorio, nome, mes, ano)):
        erros.append("Consulta ou identidade das visitas não validada; prévia e relatório suspensos.")
    if not identidade["comprovada"] or ss.get("rel_origem_dados") != identidade["chave"]:
        erros.append("Os dados não pertencem comprovadamente ao condomínio e período atuais.")
    if ss.get("_rt_contexto_erro"):
        erros.append(ss["_rt_contexto_erro"])
    if fotos_rt_de_outra_identidade(identidade["chave"], bool(ss.get(chave_fotos_rt()))):
        erros.append("Fotografias anexadas em outro condomínio ou período.")
    try:
        ler_fotos(ss, identidade["chave"])
    except (ValueError, KeyError, TypeError) as e:
        erros.append(f"Integridade das fotografias: {e}")
    return erros


def _renderizar_relatorio_rt(preview: bool = False) -> dict:
    erros_contexto = validar_contexto_rt()
    if erros_contexto:
        return {"ok": False, "preview": preview, "empresa": "Aqua Gestão", "erros": erros_contexto, "mensagem": " | ".join(erros_contexto)}
    dados_relatorio = montar_dados_relatorio()
    erros = validar_relatorio_mensal(dados_relatorio)
    if erros:
        return {
            "ok": False,
            "empresa": "Aqua Gestão",
            "preview": preview,
            "erros": erros,
            "mensagem": " | ".join(erros),
        }

    snapshot_ultimos = obter_snapshot_relatorio_independente() if not preview else None
    chave_ultimos = st.session_state.get("rel_origem_dados")
    nome_condominio = dados_relatorio["nome_condominio"]
    import hashlib
    pasta_condominio = GENERATED_DIR / "_rt_contextos" / hashlib.sha256(st.session_state["rel_origem_dados"].encode()).hexdigest()
    pasta_condominio.mkdir(parents=True, exist_ok=True)

    if not preview:
        if st.session_state.get("rel_salvar_alteracoes_cadastro"):
            salvar_relatorio_no_cadastro_principal()
            salvar_dados_condominio(pasta_condominio, salvar_snapshot_formulario())
        else:
            salvar_dados_condominio(pasta_condominio, obter_snapshot_relatorio_independente())

    fotos_salvas, origem_fotos = _resolver_fotos_relatorio_rt(
        pasta_condominio,
        nome_condominio,
        dados_relatorio.get("mes_referencia", ""),
        dados_relatorio.get("ano_referencia", ""),
        preview=preview,
    )

    pasta_saida = pasta_condominio / "_previa_exata_relatorio" if preview else pasta_condominio
    pasta_saida.mkdir(parents=True, exist_ok=True)
    data_nome = datetime.now().strftime("%Y%m%d_%H%M%S" if preview else "%Y%m%d")
    sufixo = "PREVIA_EXATA_RELATORIO_RT" if preview else "RELATORIO_RT"
    base_nome = limpar_nome_arquivo(f"{data_nome}_{nome_condominio}_{sufixo}")
    relatorio_docx = pasta_saida / f"{base_nome}.docx"
    relatorio_pdf = pasta_saida / f"{base_nome}.pdf"

    preencher_relatorio_mensal_docx(TEMPLATE_RELATORIO, relatorio_docx, dados_relatorio, fotos=fotos_salvas)

    # PDF oficial premium Aqua Gestão: gerado diretamente por ReportLab para manter
    # cores, tabelas, logo e fotos mesmo quando Word/LibreOffice não estiver disponível.
    ok_pdf, erro_pdf = gerar_pdf_relatorio_rt_premium_reportlab(dados_relatorio, fotos_salvas, relatorio_pdf)

    # Fallback técnico: se o PDF premium falhar, tenta converter o DOCX.
    if not ok_pdf:
        ok_pdf, erro_pdf = converter_docx_para_pdf(relatorio_docx, relatorio_pdf)

    if not preview:
        registrar_documento_manifest(
            pasta_condominio=pasta_condominio,
            nome_condominio=nome_condominio,
            tipo="Relatório",
            arquivo_docx=relatorio_docx,
            arquivo_pdf=relatorio_pdf,
            pdf_gerado=ok_pdf,
            erro_pdf=erro_pdf,
            dados_utilizados={
                "TIPO_ATENDIMENTO": dados_relatorio.get("tipo_atendimento"),
                "REPRESENTANTE": dados_relatorio.get("representante"),
                "CPF_CNPJ_REPRESENTANTE": dados_relatorio.get("cpf_cnpj_representante"),
                "ART_STATUS": dados_relatorio.get("art_status"),
                "ART_TEXTO": obter_status_art_texto(dados_relatorio),
            },
            extras={"fotos": [p.name for p in fotos_salvas]},
        )
        if ok_pdf and relatorio_docx.is_file() and relatorio_pdf.is_file():
            try:
                from utils.ultimos_sheets import registrar_ultimos
                registrar_ultimos(GENERATED_DIR, chave_ultimos, snapshot_ultimos, conectar_sheets)
            except Exception as e:
                st.warning(f"Documentos gerados, mas os últimos valores não foram atualizados: {e}")
        st.session_state.ultimos_docs_gerados = st.session_state.get("ultimos_docs_gerados") or {}
        st.session_state.ultimos_docs_gerados.update({
            "relatorio_docx": str(relatorio_docx) if relatorio_docx.exists() else None,
            "relatorio_pdf": str(relatorio_pdf) if ok_pdf and relatorio_pdf.exists() else None,
        })

    return {
        "ok": True,
        "empresa": "Aqua Gestão",
        "preview": preview,
        "mensagem": (
            f"Prévia exata Aqua Gestão atualizada com {len(fotos_salvas)} foto(s), usando o mesmo gerador DOCX/PDF do relatório final."
            if preview else
            f"Relatório mensal registrado com sucesso para {nome_condominio}."
        ),
        "docx": relatorio_docx,
        "pdf": relatorio_pdf,
        "pdf_ok": ok_pdf,
        "erro_pdf": erro_pdf,
        "fotos": fotos_salvas,
        "origem_fotos": origem_fotos,
        "dados": dados_relatorio,
        "pasta": pasta_condominio,
    }



def gerar_pdf_relatorio_mensal_bem_star_modelo(output_path: Path, ctx: dict) -> tuple[bool, str]:
    """PDF operacional Bem Star, sem interferir no gerador RT Aqua Gestão."""
    from utils.pdf_bem_star_mensal import gerar_pdf
    return gerar_pdf(output_path, ctx, cnpj=CNPJ_BEM_STAR, responsavel=RESPONSAVEL_TÉCNICO,
                     logo_path=Path(__file__).parent / "bem_star_logo.png")


def gerar_docx_placeholder_bem_star(output_path: Path, ctx: dict) -> tuple[bool, str]:
    """Cria DOCX simples apenas para manter compatibilidade com downloads/manifest."""
    try:
        from docx import Document as _DocxDoc
        doc = _DocxDoc()
        doc.add_heading("Relatório Mensal de Manutenção — Bem Star Piscinas", 0)
        doc.add_paragraph("O relatório principal foi gerado em PDF no padrão mensal Bem Star.")
        doc.add_paragraph(f"Cliente: {ctx.get('cliente','')}")
        doc.add_paragraph(f"Mês/Ano: {ctx.get('mes','')}/{ctx.get('ano','')}")
        doc.add_paragraph(f"Total de visitas: {len(ctx.get('lancamentos', []) or [])}")
        doc.add_paragraph("Use o arquivo PDF gerado para envio ao cliente.")
        doc.save(str(output_path))
        return True, ""
    except Exception as e:
        return False, str(e)


def _renderizar_relatorio_bem_star(preview: bool = False) -> dict:
    ctx = _coletar_contexto_relatorio_bem_star()
    if not ctx.get("ok"):
        return {
            "ok": False,
            "empresa": "Bem Star Piscinas",
            "preview": preview,
            "erros": ctx.get("erros", []),
            "mensagem": ctx.get("mensagem", "Não foi possível montar o relatório Bem Star."),
        }

    pasta_saida = ctx["pasta"] / "_previa_exata_relatorio" if preview else ctx["pasta"]
    pasta_saida.mkdir(parents=True, exist_ok=True)

    ts = datetime.now().strftime("%Y%m%d_%H%M%S")
    sufixo = "PREVIA_RELATORIO_MENSAL_BS" if preview else "RELATORIO_MENSAL_BS"
    base_nome = limpar_nome_arquivo(f"{ts}_{ctx['cliente']}_{sufixo}")

    docx_path = pasta_saida / f"{base_nome}.docx"
    pdf_path = pasta_saida / f"{base_nome}.pdf"

    ok_docx, erro_docx = gerar_docx_placeholder_bem_star(docx_path, ctx)
    ok_pdf, erro_pdf = gerar_pdf_relatorio_mensal_bem_star_modelo(pdf_path, ctx)

    if not ok_pdf:
        msg = f"Erro ao gerar PDF mensal Bem Star: {erro_pdf}"
        return {
            "ok": False,
            "empresa": "Bem Star Piscinas",
            "preview": preview,
            "erros": [erro_pdf],
            "mensagem": msg,
            "docx": docx_path,
            "pdf": pdf_path,
            "pdf_ok": False,
            "erro_pdf": erro_pdf,
            "fotos": ctx.get("fotos", []),
            "origem_fotos": ctx.get("origem_fotos", ""),
            "dados": ctx,
            "pasta": ctx["pasta"],
        }

    if not preview:
        registrar_documento_manifest(ctx["pasta"], ctx["cliente"], "Relatório Bem Star", docx_path, pdf_path, ok_pdf, erro_pdf)

    return {
        "ok": True,
        "empresa": "Bem Star Piscinas",
        "preview": preview,
        "mensagem": (
            f"Prévia Bem Star mensal atualizada com {len({l['data'] for l in ctx['lancamentos']})} data(s) de visita."
            if preview else
            f"Relatório mensal Bem Star gerado com {len({l['data'] for l in ctx['lancamentos']})} data(s) de visita."
        ),
        "docx": docx_path,
        "pdf": pdf_path,
        "pdf_ok": ok_pdf,
        "erro_pdf": erro_pdf,
        "fotos": ctx.get("fotos", []),
        "origem_fotos": ctx.get("origem_fotos", ""),
        "dados": ctx,
        "pasta": ctx["pasta"],
    }


def renderizar_relatorio_oficial(empresa: str = "Aqua Gestão", preview: bool = False) -> dict:
    empresa = str(empresa or "Aqua Gestão").strip()
    if empresa == "Bem Star Piscinas":
        return _renderizar_relatorio_bem_star(preview=preview)
    return _renderizar_relatorio_rt(preview=preview)


def gerar_relatorio_mensal() -> tuple[bool, str]:
    resultado = renderizar_relatorio_oficial("Aqua Gestão", preview=False)
    if not resultado.get("ok"):
        return False, resultado.get("mensagem", "Não foi possível gerar o relatório mensal.")

    dados_relatorio = resultado["dados"]
    relatorio_docx = Path(resultado["docx"])
    relatorio_pdf = Path(resultado["pdf"])
    ok_pdf = bool(resultado.get("pdf_ok"))
    erro_pdf = resultado.get("erro_pdf")
    pasta_condominio = Path(resultado["pasta"])

    st.markdown('<div class="section-card">', unsafe_allow_html=True)
    if dados_relatorio["avaliacao_automatica"]["detalhes"]:
        st.warning("Diagnóstico automático marcou NÃO CONFORME com base nos parâmetros fora de faixa.")
        for item in dados_relatorio["avaliacao_automatica"]["detalhes"]:
            st.write(f"- {item}")
    if dados_relatorio["avaliacao_automatica"].get("cloraminas_altas"):
        for idx, valor in dados_relatorio["avaliacao_automatica"]["cloraminas_altas"]:
            st.write(f"- Linha {idx}: cloro combinado estimado em {str(valor).replace('.', ',')} mg/L (limite NBR 10818:2026: até 0,6 mg/L).")
    c1, c2, c3 = st.columns(3)
    with c1:
        if relatorio_docx.exists():
            with open(relatorio_docx, "rb") as f:
                st.download_button("Baixar DOCX do relatório", data=f, file_name=relatorio_docx.name, mime="application/vnd.openxmlformats-officedocument.wordprocessingml.document", use_container_width=True)
    with c2:
        if ok_pdf and relatorio_pdf.exists():
            with open(relatorio_pdf, "rb") as f:
                st.download_button("Baixar PDF do relatório", data=f, file_name=relatorio_pdf.name, mime="application/pdf", use_container_width=True)
        else:
            st.warning(f"PDF do relatório não gerado. Erro: {erro_pdf}")
    with c3:
        if st.button("Abrir pasta do condomínio", key="abrir_pasta_relatorio", use_container_width=True):
            abrir_pasta_windows(pasta_condominio)
    st.markdown("</div>", unsafe_allow_html=True)
    return True, resultado["mensagem"]


def gerar_previa_exata_relatorio(empresa: str = "Aqua Gestão") -> dict:
    return renderizar_relatorio_oficial(empresa, preview=True)


def exibir_pdf_previa_exata(pdf_path: Path, height: int = 1200):
    """Exibe a prévia do PDF dentro do Streamlit de forma confiável.

    O visual anterior usava iframe/base64. Em algumas versões do Chrome/Streamlit
    isso aparece como uma folha branca, mesmo quando o PDF foi gerado corretamente.

    Esta versão renderiza o PDF como imagem usando PyMuPDF quando disponível.
    """
    pdf_path = Path(pdf_path) if pdf_path else None
    if not pdf_path or not pdf_path.exists():
        st.warning("O PDF da prévia ainda não está disponível.")
        return

    # Botão sempre disponível, mesmo se a visualização interna falhar.
    try:
        with open(pdf_path, "rb") as _f_prev_pdf:
            st.download_button(
                "⬇️ Baixar PDF da prévia para conferir",
                data=_f_prev_pdf,
                file_name=pdf_path.name,
                mime="application/pdf",
                use_container_width=True,
                key=f"btn_download_previa_pdf_inline_{chave_segura(str(pdf_path))}",
            )
    except Exception:
        pass

    # Principal: renderiza páginas do PDF como imagens PNG.
    try:
        import fitz  # PyMuPDF
        import io as _io

        doc_pdf = fitz.open(str(pdf_path))
        total_paginas = len(doc_pdf)
        if total_paginas == 0:
            st.warning("O PDF foi gerado, mas não possui páginas.")
            doc_pdf.close()
            return

        max_paginas = min(total_paginas, 6)
        st.caption(f"Prévia renderizada em imagem: {max_paginas} de {total_paginas} página(s).")

        for idx in range(max_paginas):
            pagina = doc_pdf.load_page(idx)
            matriz = fitz.Matrix(1.45, 1.45)
            pix = pagina.get_pixmap(matrix=matriz, alpha=False)
            img_bytes = pix.tobytes("png")
            st.image(_io.BytesIO(img_bytes), use_container_width=True)
            if idx < max_paginas - 1:
                st.markdown("---")

        if total_paginas > max_paginas:
            st.info(
                f"Prévia limitada às {max_paginas} primeiras páginas para manter o sistema leve. "
                "Baixe o PDF para ver o relatório completo."
            )
        doc_pdf.close()
        return

    except Exception as e:
        st.warning(
            "A prévia visual em imagem não pôde ser carregada. "
            "O PDF foi gerado; use o botão de download acima para conferir. "
            "Para exibir dentro do sistema, inclua `PyMuPDF` no requirements.txt."
        )
        st.caption(f"Detalhe técnico: {type(e).__name__}: {e}")
    # Fallback seguro: evitar components.html no Streamlit 1.56.
    st.info(
        "A visualização embutida do PDF foi desativada nesta versão para evitar rerun infinito. "
        "Use o botão de download acima para abrir o arquivo localmente."
    )


