def carregar_rascunho_relatorio(pasta_condominio: Path) -> dict | None:
    caminho = pasta_condominio / RASCUNHO_JSON_NAME
    if not caminho.exists():
        return None
    try:
        return json.loads(caminho.read_text(encoding="utf-8"))
    except Exception:
        return None


def aplicar_rascunho_no_formulario(rascunho: dict):
    """Restaura todos os campos do relatório a partir do rascunho salvo."""
    campos_simples = [
        "rel_nome_condominio", "rel_cnpj_condominio", "rel_endereco_condominio",
        "rel_representante", "rel_cpf_cnpj_representante", "rel_tipo_atendimento",
        "rel_mes_referencia", "rel_ano_referencia", "rel_data_emissao",
        "rel_art_status", "rel_art_numero", "rel_art_inicio", "rel_art_fim",
        "rel_status_agua", "rel_diagnostico", "rel_nbr_11238", "rel_nr_26", "rel_nr_06",
        "rel_nbr11238_profundidade", "rel_nbr11238_retrolavagem", "rel_nbr11238_skimmers", "rel_nbr11238_circulacao", "rel_nbr11238_chuveiro",
        "rel_epi_luvas_status", "rel_epi_luvas_ca", "rel_epi_oculos_status", "rel_epi_oculos_ca",
        "rel_epi_respirador_status", "rel_epi_respirador_ca", "rel_epi_botas_status", "rel_epi_botas_ca",
    ]
    for c in campos_simples:
        if c in rascunho:
            st.session_state[c] = rascunho[c]

    analises = rascunho.get("analises", [])
    qtd = max(len(analises), ANALISES_PADRAO)
    garantir_campos_analises(qtd)
    st.session_state.rel_analises_total = qtd
    for i, a in enumerate(analises):
        st.session_state[f"rel_analise_data_{i}"] = a.get("data", "")
        st.session_state[f"rel_analise_ph_{i}"] = a.get("ph", "")
        st.session_state[f"rel_analise_cl_{i}"] = a.get("cl", "")
        st.session_state[f"rel_analise_ct_{i}"] = a.get("ct", "")
        st.session_state[f"rel_analise_alc_{i}"] = a.get("alc", "")
        st.session_state[f"rel_analise_dc_{i}"] = a.get("dc", "")
        st.session_state[f"rel_analise_cya_{i}"] = a.get("cya", "")
        st.session_state[f"rel_analise_operador_{i}"] = a.get("operador", "")

    dosagens = rascunho.get("dosagens", [])
    for i in range(7):
        d = dosagens[i] if i < len(dosagens) else {}
        st.session_state[f"rel_dos_produto_{i}"] = d.get("produto", "")
        st.session_state[f"rel_dos_lote_{i}"] = d.get("fabricante_lote", "")
        st.session_state[f"rel_dos_qtd_{i}"] = d.get("quantidade", "")
        st.session_state[f"rel_dos_un_{i}"] = d.get("unidade", "")
        st.session_state[f"rel_dos_finalidade_{i}"] = d.get("finalidade", "")

    for i, obs in enumerate(rascunho.get("observacoes", [])[:5]):
        st.session_state[f"rel_obs_{i}"] = obs

    for i, rec in enumerate(rascunho.get("recomendacoes", [])[:5]):
        st.session_state[f"rel_rec_texto_{i}"] = rec.get("texto", "")
        st.session_state[f"rel_rec_prazo_{i}"] = rec.get("prazo", "")
        st.session_state[f"rel_rec_resp_{i}"] = rec.get("responsavel", "")


def excluir_rascunho_relatorio(pasta_condominio: Path):
    caminho = pasta_condominio / RASCUNHO_JSON_NAME
    if caminho.exists():
        caminho.unlink()


inicializar_campos()
sincronizar_relatorio_com_cadastro()

# Rascunhos legados exigem restauração explícita e revisão de identidade.

# _EMERGENCIA_RELATORIO_RT_FUNCOES_V1_
# =========================================
# EMERGÊNCIA — PROTEÇÃO DO RELATÓRIO RT
# =========================================
def _relatorio_rt_rascunho_path() -> Path:
    try:
        GENERATED_DIR.mkdir(exist_ok=True)
    except Exception:
        pass
    return GENERATED_DIR / "_rascunho_relatorio_rt_em_andamento.json"


# Rascunho RT na aba _Rascunhos_RT: uma linha por sessão de edição.
#   A = chave ("thyago#s#<sessão>"; a linha antiga "thyago" continua legível)
#   B = salvo em | C = JSON, ou "__PARTES__:<n>:<sha256>" quando dividido
#   D = status ("" ou "descartado em ...") | E em diante = partes do JSON
# Cada sessão só grava a própria linha; linhas novas entram por append_row.
RASCUNHO_RT_USUARIO = "thyago"
RASCUNHO_RT_TAMANHO_PARTE = 40000  # célula do Sheets aceita até 50.000 caracteres
RASCUNHO_RT_MAX_PARTES = 40
_RASCUNHO_RT_MARCA_PARTES = "__PARTES__"
_RASCUNHO_RT_COL_PARTES = 4  # índice (0-based) da coluna E
# Preenchidos pelo próprio app a cada execução: não indicam edição do usuário.
_RASCUNHO_RT_CAMPOS_AUTOMATICOS = {"rel_status_agua", "rel_verificacoes_semanais", "rel_analises_total"}
# Campos digitados pelo usuário que caracterizam um rascunho com conteúdo.
_RASCUNHO_RT_PREFIXOS_CONTEUDO = ("rel_analise_", "rel_dos_", "rel_obs_")
_RASCUNHO_RT_CAMPOS_CONTEUDO = (
    "rel_nome_condominio", "nome_condominio", "rel_diagnostico", "rel_observacoes_gerais", "csr_obs_rel",
)
# Uploads não aceitam valor via session_state; seleções temporárias não devem voltar.
_RASCUNHO_RT_NAO_RESTAURAR = {"rel_fotos_upload", "rel_pdf_visita_importador", "csr_sel_relatorio", "rel_regerar_pdf_visita_idx"}


def _rascunho_pg_ativo() -> bool:
    """PostgreSQL somente por configuração explícita de homologação:
    ACQUA_RT_RASCUNHO_BACKEND=postgres e ACQUA_RT_PG_CONFIG (TOML fora do repositório
    com ambiente="homologacao", validado em _rt_pg_repositorio)."""
    return os.environ.get("ACQUA_RT_RASCUNHO_BACKEND", "").strip().lower() == "postgres"


def _rascunho_usa_sheets() -> bool:
    """Rascunhos usam a planilha só em produção. No GitHub Codespaces (CODESPACES=true)
    ficam apenas no disco local, sem ler nem gravar a planilha real; em homologação com
    PostgreSQL a planilha de rascunhos também não é usada."""
    return not _rascunho_pg_ativo() and os.environ.get("CODESPACES", "").strip().lower() != "true"


def _rascunho_backend() -> str:
    """"sheets" (padrão, produção) | "local" (Codespaces: só disco) | "postgres" (homologação)."""
    if _rascunho_pg_ativo():
        return "postgres"
    return "sheets" if _rascunho_usa_sheets() else "local"


def _rascunho_destino(forma: str = "") -> str:
    """Destino com artigo: forma "a" (à/ao), "em" (na/no), "o" (A/O); vazia = só o nome."""
    pg = _rascunho_pg_ativo()
    nome = "PostgreSQL de homologação" if pg else "planilha"
    artigo = {"a": ("ao", "à"), "em": ("no", "na"), "o": ("O", "A"), "o_min": ("o", "a")}.get(forma)
    return f"{artigo[0 if pg else 1]} {nome}" if artigo else nome


def _rt_pg_repositorio():
    """Repositório do contrato rt_persist; recusa qualquer configuração fora de homologação."""
    import sys
    import tomllib
    from utils import rt_postgres
    caminho = os.environ.get("ACQUA_RT_PG_CONFIG", "").strip()
    if not caminho or not Path(caminho).is_absolute() or not Path(caminho).is_file():
        raise rt_postgres.RepositorioIndisponivel("Configuração PostgreSQL de homologação ausente.")
    with open(caminho, "rb") as f:
        cfg = tomllib.load(f)
    if cfg.get("ambiente") != "homologacao":
        raise rt_postgres.RepositorioIndisponivel("PostgreSQL de rascunhos só é permitido em homologação.")
    conexao = cfg.get("conexao")
    if conexao == "executor_homologacao":
        # Mesmo executor validado nos 15 cenários: TLS verify-full, marcador, identidade real, JIT/DPAPI.
        pasta = str(Path(__file__).resolve().parent / "database" / "rt")
        if pasta not in sys.path:
            sys.path.insert(0, pasta)
        import supabase_runner
        supabase_runner.load_config(str(cfg.get("manifesto") or ""))
        conectar = supabase_runner.connect
    elif conexao == "fabrica_teste" and "teste" in rt_postgres.FABRICAS:
        conectar = rt_postgres.FABRICAS["teste"]  # registrada apenas por testes locais
    else:
        raise rt_postgres.RepositorioIndisponivel("Conexão PostgreSQL de homologação não configurada.")
    return rt_postgres.Repositorio(cfg, conectar)


def _relatorio_rt_tem_conteudo(campos: dict) -> bool:
    for k, v in (campos or {}).items():
        k = str(k)
        if (k.startswith(_RASCUNHO_RT_PREFIXOS_CONTEUDO) or k in _RASCUNHO_RT_CAMPOS_CONTEUDO) and str(v or "").strip():
            return True
    return False


def _relatorio_rt_tem_dados_em_tela() -> bool:
    return _relatorio_rt_tem_conteudo(dict(st.session_state))


def _perfil_acesso_rascunho() -> str:
    """Perfil autenticado desta sessão, gravado no rascunho RT ("origem_acesso").

    Vem só da autenticação: sessão de operador com op_dados_atual["is_rt"] → "rt_campo";
    sem is_rt → "operador"; relatório RT do escritório (login administrativo da Aqua
    Gestão) → "escritorio_rt". Nome, campo "operador" ou contrato não contam."""
    ss = st.session_state
    if ss.get("op_pin_ok") and isinstance(ss.get("op_dados_atual"), dict):
        return "rt_campo" if ss["op_dados_atual"].get("is_rt") is True else "operador"
    if ss.get("admin_logado") and ss.get("empresa_ativa", "aqua_gestao") == "aqua_gestao":
        return "escritorio_rt"
    return "desconhecido"


def _relatorio_rt_coletar_rascunho() -> dict:
    total = int(st.session_state.get("rel_analises_total", ANALISES_PADRAO) or ANALISES_PADRAO)
    dados = {
        "salvo_em": _agora_brasilia() if "_agora_brasilia" in globals() else datetime.now().isoformat(),
        "_salvo_iso": datetime.now().isoformat(timespec="microseconds"),
        "empresa_ativa": st.session_state.get("empresa_ativa", "aqua_gestao"),
        "origem_acesso": _perfil_acesso_rascunho(),
        "rel_analises_total": max(total, ANALISES_PADRAO),
        "campos": {},
    }
    for k, v in st.session_state.items():
        if str(k).startswith("rel_"):
            try:
                if isinstance(v, (str, int, float, bool)) or v is None:
                    dados["campos"][k] = v
                else:
                    dados["campos"][k] = str(v)
            except Exception:
                pass
    return dados


def _relatorio_rt_chave_sessao(nova: bool = False) -> str:
    """Chave da linha desta sessão; estável entre reruns, nova após descarte."""
    if nova or not st.session_state.get("_rt_rasc_chave"):
        st.session_state["_rt_rasc_chave"] = f"{RASCUNHO_RT_USUARIO}#s#{os.urandom(6).hex()}"
    return st.session_state["_rt_rasc_chave"]


def _relatorio_rt_arquivo_local(chave: str) -> Path:
    if chave == RASCUNHO_RT_USUARIO:
        return _relatorio_rt_rascunho_path()
    return _relatorio_rt_rascunho_path().with_name(f"_rascunho_relatorio_rt_{slugify_nome(chave)}.json")


def _relatorio_rt_aba(criar: bool = False):
    """Aba _Rascunhos_RT, ou None fora de produção / sem conexão."""
    if not _rascunho_usa_sheets():
        return None
    sh = conectar_sheets()
    if not sh:
        return None
    aba = obter_aba_sheets("_Rascunhos_RT")
    if aba is not None:
        return aba
    try:
        return sh.worksheet("_Rascunhos_RT")  # obter_aba_sheets devolve None (em cache) se a aba faltar
    except Exception:
        if not criar:
            return None
    try:
        aba = sh.add_worksheet(title="_Rascunhos_RT", rows=100, cols=4)
        aba.update("A1:D1", [["Usuario", "Salvo em", "Dados JSON", "Status"]])
        return aba
    except Exception:
        return None


def _relatorio_rt_ler_json(texto: str):
    try:
        dados = json.loads(texto)
        return dados if isinstance(dados, dict) else None
    except Exception:
        return None  # JSON inválido (ex.: rascunho antigo truncado) não é usado


def _relatorio_rt_serializar(dados: dict) -> list[str]:
    """[coluna C, partes...]. JSON pequeno vai inteiro em C; grande vira partes com hash."""
    payload = json.dumps(dados, ensure_ascii=False)
    if len(payload) <= RASCUNHO_RT_TAMANHO_PARTE:
        return [payload]
    partes = [payload[i:i + RASCUNHO_RT_TAMANHO_PARTE] for i in range(0, len(payload), RASCUNHO_RT_TAMANHO_PARTE)]
    if len(partes) > RASCUNHO_RT_MAX_PARTES:
        raise ValueError(f"rascunho com {len(payload)} caracteres excede o limite de {RASCUNHO_RT_MAX_PARTES} partes")
    sha = hashlib.sha256(payload.encode("utf-8")).hexdigest()
    return [f"{_RASCUNHO_RT_MARCA_PARTES}:{len(partes)}:{sha}"] + partes


def _relatorio_rt_desserializar(row: list) -> dict | None:
    """Reconstrói o rascunho de uma linha. Partes ausentes ou hash divergente -> None."""
    c = row[2] if len(row) > 2 else ""
    if not str(c).startswith(_RASCUNHO_RT_MARCA_PARTES + ":"):
        return _relatorio_rt_ler_json(c) if str(c).strip() else None
    try:
        _, n, sha = str(c).split(":", 2)
        n = int(n)
        partes = row[_RASCUNHO_RT_COL_PARTES:_RASCUNHO_RT_COL_PARTES + n]
        if n < 1 or len(partes) != n or any(not p for p in partes):
            return None
        payload = "".join(partes)
        if hashlib.sha256(payload.encode("utf-8")).hexdigest() != sha:
            return None
        return _relatorio_rt_ler_json(payload)
    except Exception:
        return None


def _relatorio_rt_eh_chave(chave: str) -> bool:
    return chave == RASCUNHO_RT_USUARIO or chave.startswith(f"{RASCUNHO_RT_USUARIO}#")


def _relatorio_rt_ordem(dados: dict, posicao: int = 0) -> tuple:
    iso = str(dados.get("_salvo_iso") or "")
    if not iso:  # rascunho antigo: "dd/mm/aaaa HH:MM:SS"
        m = re.match(r"(\d{2})/(\d{2})/(\d{4}) (\d{2}:\d{2}:\d{2})", str(dados.get("salvo_em", "")))
        iso = f"{m.group(3)}-{m.group(2)}-{m.group(1)}T{m.group(4)}" if m else ""
    return (iso, posicao)


def _relatorio_rt_gestor_sync():
    from utils.rascunho_sync import GestorRascunhos
    return GestorRascunhos(_relatorio_rt_rascunho_path().parent,
        st.session_state.get("empresa_ativa", "aqua_gestao"), st.session_state,
        _relatorio_rt_arquivo_local, _relatorio_rt_desserializar,
        _relatorio_rt_gravar_linha, _relatorio_rt_eh_chave, _relatorio_rt_ordem, _relatorio_rt_serializar)


def _relatorio_rt_listar_rascunhos(incluir_descartados: bool = False) -> dict:
    gestor = _relatorio_rt_gestor_sync()
    gestor.reconstruir()  # só controles de sincronização; não altera campos ativos
    if _rascunho_backend() == "postgres":
        return _relatorio_rt_listar_postgres(gestor, incluir_descartados)
    return gestor.listar(_relatorio_rt_aba(), incluir_descartados)


def _relatorio_rt_listar_postgres(gestor, incluir_descartados: bool = False) -> dict:
    """Pendências locais + revisão mais recente no PostgreSQL das identidades em uso.

    O contrato não oferece listagem global: consultam-se a identidade da tela e as das
    pendências locais. Falha de consulta vira aviso, nunca ausência.
    """
    from utils.rascunho_sync import hash_conteudo
    ss = st.session_state
    empresa = ss.get("empresa_ativa", "aqua_gestao")
    base = gestor.listar(None, incluir_descartados)
    locais = [v for v in base["versoes"] if v.get("pendente")]  # confirmadas já estão no banco
    avisos = [a for a in base["avisos"] if "planilha" not in a]
    origens = {str(ss.get("rel_origem_dados") or "")}
    origens |= {str((v["dados"].get("campos") or {}).get("rel_origem_dados") or "") for v in base["versoes"]}
    remotas = []
    try:
        repo = _rt_pg_repositorio()
    except Exception as e:
        repo = None
        avisos.append(f"PostgreSQL de homologação indisponível ({type(e).__name__}); pendências locais preservadas.")
    for origem in sorted(o for o in origens if o.startswith(empresa + "|")):
        if repo is None:
            break
        try:
            achado = repo.ultima(empresa, origem)
        except PermissionError:
            avisos.append(f"Sem acesso no PostgreSQL de homologação para {origem.split('|')[-1]} deste cliente; "
                          "nada foi lido nem gravado nesse período.")
            continue
        except ValueError:
            continue  # identidade não comprovável (sem cliente/período): nada a consultar
        except Exception as e:
            avisos.append(f"Consulta ao PostgreSQL falhou para {origem.split('|')[-1]} ({type(e).__name__}); ausência não confirmada.")
            continue
        if achado:
            dados, revisao = achado
            remotas.append({"chave": f"pg:{dados['_pg']['doc']}", "dados": dados, "linha": revisao,
                            "origem": "postgres", "hash": hash_conteudo(dados), "pendente": False,
                            "descartado": False, "conflito": False, "revisao": revisao})
    versoes = locais + remotas
    versoes.sort(key=lambda v: (bool(v["pendente"]), _relatorio_rt_ordem(v["dados"], 0)), reverse=True)
    return {"versoes": versoes, "ignorados": base["ignorados"], "avisos": avisos, "empresa": empresa}


def _relatorio_rt_enviar_postgres(chave: str, dados: dict) -> bool:
    """Grava a cópia local íntegra desta chave como nova revisão; conflito nunca sobrescreve."""
    from utils.rascunho_sync import ConflitoRascunho, escrever_atomico, hash_conteudo
    from utils.rt_postgres import ConflitoVersao
    ss = st.session_state
    gestor = _relatorio_rt_gestor_sync()
    r = gestor.ler(chave)
    if r is None or r["hash"] != hash_conteudo(dados):
        raise ValueError("Envio sem cópia local íntegra persistida")
    if r["estado"] == "descartado":
        return False
    repo = _rt_pg_repositorio()
    ident = repo.identidade(ss.get("empresa_ativa", "aqua_gestao"), (dados.get("campos") or {}).get("rel_origem_dados"))
    bases = ss.setdefault("_rt_pg_base", {})
    if r.get("pg_base") is None:
        # A base é a revisão que esta sessão viu ao editar; fica na cópia local para reenvio idempotente.
        r["pg_base"] = int(bases.get(ident.doc, 0))
        escrever_atomico(gestor.caminho(chave), r)
    try:
        resultado = repo.salvar(chave, r["dados"], int(r["pg_base"]))
    except ConflitoVersao as e:
        gestor.estado(chave, "conflito", str(e))
        raise ConflitoRascunho(f"{e} As duas cópias foram preservadas; restaure a versão desejada.") from None
    bases[ident.doc] = resultado["revision"]
    gestor.estado(chave, "confirmado")
    ss["_rt_pg_ultima_revisao"] = resultado["revision"]
    return True

def _relatorio_rt_descartada(row: list) -> bool:
    return len(row) > 3 and str(row[3]).strip().lower().startswith("descartado")


def _relatorio_rt_gravar_linha(aba, chave: str, dados: dict) -> bool:
    """Grava/atualiza somente a linha desta sessão.

    A coluna D (status) nunca é escrita aqui, então um descarte feito por outro acesso
    não é desfeito. Conteúdo e partes vão numa única chamada (batch_update).
    Retorna False se a linha está ou ficou descartada: o chamador grava em linha nova.
    """
    celulas = _relatorio_rt_serializar(dados)
    todas = aba.get_all_values()
    indice = next((i for i, row in enumerate(todas[1:], start=2) if row and str(row[0]).strip() == chave), None)
    if indice is None:
        aba.append_row([chave, dados.get("salvo_em", ""), celulas[0], ""] + celulas[1:],
                       value_input_option="RAW", insert_data_option="INSERT_ROWS", table_range="A1")
        return True
    if _relatorio_rt_descartada(todas[indice - 1]):
        return False
    partes = celulas[1:]
    largura = max(_RASCUNHO_RT_COL_PARTES + len(partes), len(todas[indice - 1]))
    if aba.col_count < largura:
        aba.add_cols(largura - aba.col_count)
    blocos = [{"range": f"A{indice}:C{indice}", "values": [[chave, dados.get("salvo_em", ""), celulas[0]]]}]
    resto = partes + [""] * (largura - _RASCUNHO_RT_COL_PARTES - len(partes))  # limpa partes antigas que sobrarem
    if resto:
        blocos.append({"range": f"E{indice}:{_relatorio_rt_coluna(largura)}{indice}", "values": [resto]})
    aba.batch_update(blocos, value_input_option="RAW")
    depois = aba.get_all_values()
    return len(depois) >= indice and not _relatorio_rt_descartada(depois[indice - 1])


def _relatorio_rt_coluna(n: int) -> str:
    letras = ""
    while n:
        n, r = divmod(n - 1, 26)
        letras = chr(65 + r) + letras
    return letras


RASCUNHO_RT_INTERVALO_REENVIO = 15  # segundos entre tentativas de sincronizar com a planilha


def _relatorio_rt_enviar_planilha(aba, chave: str, dados: dict, retentativa: bool = True) -> str:
    gestor = _relatorio_rt_gestor_sync()
    if gestor.enviar(aba, chave, dados, retentativa=retentativa):
        return chave
    if retentativa:
        raise ValueError("Rascunho descartado: reenvio cancelado.")
    # Uma edição ativa posterior a descarte segue em nova chave, sem reviver a antiga.
    nova = _relatorio_rt_chave_sessao(nova=True) if chave == st.session_state.get("_rt_rasc_chave") else f"{RASCUNHO_RT_USUARIO}#s#{os.urandom(6).hex()}"
    dados = dict(dados, _chave=nova)
    gestor.preparar(nova, dados)
    from utils.rascunho_sync import escrever_atomico
    escrever_atomico(_relatorio_rt_arquivo_local(nova), dados)
    if not gestor.enviar(aba, nova, dados, retentativa=True):
        raise ValueError("Nova chave foi descartada; cópia local preservada.")
    return nova

def _relatorio_rt_sincronizar_pendentes() -> bool:
    gestor = _relatorio_rt_gestor_sync()
    ss = st.session_state
    pendentes = gestor.reconstruir()
    if not pendentes:
        return not bool(ss.get("_rt_rasc_aviso"))
    agora = datetime.now().timestamp()
    if agora < ss.get("_rt_rasc_proxima_tentativa", 0):
        return False
    pg = _rascunho_backend() == "postgres"
    aba = None if pg else _relatorio_rt_aba(criar=True)
    erros = []
    for chave in pendentes:
        try:
            r = gestor.ler(chave)
            if pg:
                if r["estado"] == "conflito":
                    continue  # conflito exige restauração explícita; reenviar não resolve
                _relatorio_rt_enviar_postgres(chave, r["dados"])
                continue
            if not gestor.enviar(aba, chave, r["dados"], retentativa=True):
                continue  # descarte confirmado; nunca cria nova chave em retentativa
        except Exception as e:
            erros.append(f"{type(e).__name__}: {e}")
    restantes = gestor.reconstruir()
    ss.pop("_rt_rasc_lista_cache", None)
    if restantes or erros:
        ss["_rt_rasc_aviso"] = "; ".join(erros) or ss.get("_rt_rasc_aviso", "Cópia local pendente")
        ss["_rt_rasc_proxima_tentativa"] = agora + RASCUNHO_RT_INTERVALO_REENVIO
        return False
    ss.pop("_rt_rasc_proxima_tentativa", None)
    return True

def _relatorio_rt_salvar_rascunho(motivo: str = "autosave") -> bool:
    """Salva o rascunho RT somente quando o usuário alterou algo.

    - 1ª execução da sessão (ou logo após restaurar/descartar): só registra a referência.
    - Widgets criados depois (com seu valor padrão) entram na referência sem contar
      como edição; edição é mudança de valor de um campo já conhecido, ou um campo de
      conteúdo (análise, dosagem, observação) que já surge preenchido.
    - Formulário sem conteúdo do usuário nunca é gravado.
    - Grava somente a linha desta sessão; outras sessões e versões não são tocadas.
    - Se a gravação na planilha falhar, a última versão válida dela é preservada, a
      versão fica pendente de sincronização (reenviada automaticamente nos próximos
      reruns, sem nova edição) e um aviso explícito permanece até ela ser persistida.
    - Retorna True somente quando a versão foi persistida (planilha em produção; disco
      local no Codespaces).
    """
    ss = st.session_state
    if ss.get("_rt_rasc_gravando"):
        return False  # gravação desta sessão em andamento: a referência não muda, o próximo rerun grava
    ss["_rt_rasc_gravando"] = True
    try:
        dados = _relatorio_rt_coletar_rascunho()
        dados["motivo"] = motivo
        campos = dados["campos"]
        referencia = ss.get("_rt_rasc_ref")
        if referencia is None:
            ss["_rt_rasc_ref"] = dict(campos)
            return False  # abrir a tela não é edição
        mudou = any(
            (k in referencia and referencia[k] != v)
            or (k not in referencia and _relatorio_rt_tem_conteudo({k: v}))
            for k, v in campos.items() if k not in _RASCUNHO_RT_CAMPOS_AUTOMATICOS
        )
        for k, v in campos.items():
            referencia.setdefault(k, v)  # widget recém-criado: valor padrão não é edição
        if not mudou or not _relatorio_rt_tem_conteudo(campos):
            if mudou:
                ss["_rt_rasc_ref"] = dict(campos)  # formulário vazio não vira rascunho
            if _rascunho_backend() != "local":
                _relatorio_rt_sincronizar_pendentes()  # reenvio sem nova edição (só há pendência após edição real)
            return False

        chave = _relatorio_rt_chave_sessao()
        dados["_chave"] = chave
        from utils.rascunho_sync import escrever_atomico
        gestor = _relatorio_rt_gestor_sync()
        registro_anterior = gestor.ler(chave)
        if (registro_anterior and registro_anterior["estado"] in ("pendente", "conflito")
                and _rascunho_backend() == "postgres"
                and (registro_anterior["dados"].get("campos") or {}).get("rel_origem_dados") != campos.get("rel_origem_dados")):
            # Pendência de OUTRO documento (outro condomínio/período, p.ex. sem escopo no banco):
            # continua preservada e listada; a edição atual segue em chave nova, sem ser bloqueada.
            chave = _relatorio_rt_chave_sessao(nova=True)
            dados["_chave"] = chave
            registro_anterior = None
        if (registro_anterior and registro_anterior["estado"] == "pendente"
                and _rascunho_backend() == "postgres"):
            # Pendência de envio (falha de conexão) desta chave: conclui antes da edição nova.
            from utils.rascunho_sync import hash_conteudo as _hash_rt
            if registro_anterior["hash"] != _hash_rt(dados):
                try:
                    _relatorio_rt_enviar_postgres(chave, registro_anterior["dados"])
                except Exception:
                    pass
                registro_anterior = gestor.ler(chave)
        if (registro_anterior and registro_anterior["estado"] in ("pendente", "conflito")
                and _rascunho_usa_sheets()):
            # Pendência desta chave com conteúdo anterior: tenta concluir o envio
            # antes de gravar a edição nova. Com a planilha de volta, a versão
            # anterior é confirmada (ou reconhecida em outra chave) e a nova segue
            # normalmente; sem conexão ou com conflito real, nada é sobrescrito.
            from utils.rascunho_sync import hash_conteudo as _hash_rt
            if registro_anterior["hash"] != _hash_rt(dados):
                try:
                    gestor.enviar(_relatorio_rt_aba(criar=True), chave, registro_anterior["dados"], retentativa=True)
                except Exception:
                    pass
                registro_anterior = gestor.ler(chave)
        if registro_anterior and registro_anterior["estado"] in ("descartado", "sincronizado"):
            chave = _relatorio_rt_chave_sessao(nova=True)
            dados["_chave"] = chave
            registro_anterior = None
        registro = gestor.preparar(chave, dados, local_apenas=_rascunho_backend() == "local")
        dados = registro["dados"]
        escrever_atomico(_relatorio_rt_arquivo_local(chave), dados)
        ss["_rt_rasc_ref"] = dict(campos)  # a edição está guardada (local); a sincronização segue abaixo
        ss.pop("_rt_rasc_lista_cache", None)
        if _rascunho_backend() == "local":
            ss["_relatorio_rt_ultimo_autosave"] = dados.get("salvo_em", "")
            ss.pop("_rt_contexto_erro", None)
            ss.pop("_relatorio_rt_autosave_erro", None)
            return True  # Codespaces: o disco local é o armazenamento
        try:
            if _rascunho_backend() == "postgres":
                _relatorio_rt_enviar_postgres(chave, dados)
            else:
                _relatorio_rt_enviar_planilha(_relatorio_rt_aba(criar=True), chave, dados,
                    retentativa=bool(registro_anterior and registro_anterior["estado"] in ("pendente", "conflito")))
        except Exception as e:
            pendentes = list(ss.get("_rt_rasc_sync_pendente") or [])
            if chave not in pendentes:
                pendentes.append(chave)
            ss["_rt_rasc_sync_pendente"] = pendentes
            ss["_rt_rasc_proxima_tentativa"] = datetime.now().timestamp() + RASCUNHO_RT_INTERVALO_REENVIO
            ss["_rt_rasc_aviso"] = f"{type(e).__name__}: {e}"
            return False
        ss["_relatorio_rt_ultimo_autosave"] = dados.get("salvo_em", "")
        restantes = [c for c in (ss.get("_rt_rasc_sync_pendente") or []) if c != chave]  # versão atual já persistida
        if restantes:
            ss["_rt_rasc_sync_pendente"] = restantes
            ss["_rt_rasc_proxima_tentativa"] = 0
            _relatorio_rt_sincronizar_pendentes()
        else:
            for k in ("_rt_rasc_sync_pendente", "_rt_rasc_proxima_tentativa", "_rt_rasc_aviso"):
                ss.pop(k, None)
        ss.pop("_rt_contexto_erro", None)
        ss.pop("_relatorio_rt_autosave_erro", None)
        return True
    except Exception as e:
        ss["_relatorio_rt_autosave_erro"] = f"{type(e).__name__}: {e}"
        ss["_rt_rasc_aviso"] = f"Salvamento não concluído; cópia anterior preservada: {type(e).__name__}: {e}"
        return False
    finally:
        ss["_rt_rasc_gravando"] = False


def _relatorio_rt_carregar_rascunho() -> dict:
    versoes = _relatorio_rt_listar_rascunhos()["versoes"]
    return versoes[0]["dados"] if versoes and not any(v.get("conflito") for v in versoes) else {}


def _relatorio_rt_descartar(chave: str) -> bool:
    """Marca somente esta versão como descartada. O conteúdo permanece na planilha.

    Em produção só conclui se a marca foi gravada na planilha; caso contrário o
    rascunho é preservado, nada muda e o usuário pode tentar de novo. No Codespaces
    a marca fica no arquivo local.
    """
    ss = st.session_state
    marca = f"descartado em {_agora_brasilia() if '_agora_brasilia' in globals() else datetime.now().isoformat()}"
    local = _relatorio_rt_arquivo_local(chave)
    if _rascunho_usa_sheets():
        aba = _relatorio_rt_aba()
        if aba is None:
            ss["_rt_rasc_erro_descarte"] = (
                "A planilha de rascunhos está indisponível: o rascunho NÃO foi descartado e continua guardado. "
                "Tente novamente em instantes."
            )
            return False
        try:
            todas = aba.get_all_values()
            indices = [i for i, row in enumerate(todas[1:], start=2) if row and str(row[0]).strip() == chave]
            from utils.rascunho_sync import empresa_dados
            empresa = ss.get("empresa_ativa", "aqua_gestao")
            for i in indices:
                remoto = _relatorio_rt_desserializar(todas[i - 1])
                if remoto is not None and empresa_dados(remoto) != empresa:
                    raise ValueError("Rascunho remoto de outra empresa: descarte bloqueado")
            if not indices and not local.exists():
                raise LookupError("versão não encontrada")
            if indices and aba.col_count < 4:
                aba.add_cols(4 - aba.col_count)
            for i in indices:
                aba.update(range_name=f"D{i}:D{i}", values=[[marca]], value_input_option="RAW")
        except Exception as e:
            ss["_rt_rasc_erro_descarte"] = (
                f"Não foi possível descartar o rascunho ({type(e).__name__}). Ele continua guardado; tente novamente."
            )
            return False
    try:
        if local.exists():
            dados = _relatorio_rt_ler_json(local.read_text(encoding="utf-8")) or {}
            dados["_descartado"] = marca
            from utils.rascunho_sync import escrever_atomico
            _relatorio_rt_gestor_sync().descartar(chave, marca)
            escrever_atomico(local, dados)
        else:
            _relatorio_rt_gestor_sync().descartar(chave, marca)
    except Exception as e:
        ss["_rt_rasc_erro_descarte"] = f"Não foi possível confirmar o descarte no disco local: {e}. A marca remota, se confirmada, continua válida."
        return False
    if chave == ss.get("_rt_rasc_chave"):
        _relatorio_rt_chave_sessao(nova=True)
    ss["_rt_rasc_ref"] = None  # nada é regravado sem nova edição
    ss.pop("_rt_rasc_erro_descarte", None)
    ss.pop("_rt_rasc_lista_cache", None)
    return True


def _relatorio_rt_aplicar_rascunho(dados: dict) -> bool:
    """Aplica um rascunho ao session_state. Deve rodar antes da criação dos widgets
    (ver _relatorio_rt_aplicar_pendente), senão o Streamlit recusa a alteração."""
    anterior = dict(st.session_state)
    if isinstance(anterior.get("_rel_por_identidade"), dict):
        anterior["_rel_por_identidade"] = dict(anterior["_rel_por_identidade"])
    try:
        from utils.rt_contexto import normalizar_rascunho, limpar
        campos, total = normalizar_rascunho(dados, st.session_state.get("empresa_ativa", "aqua_gestao"), ANALISES_PADRAO)
        origem_atual = st.session_state.get("rel_origem_dados")
        if origem_atual and not guardar_tabela_rt(origem_atual, restauracao_explicita=True):
            raise ValueError(st.session_state.get("_rt_contexto_erro") or "Não foi possível guardar o contexto atual.")
        limpar(st.session_state)
        st.session_state["rel_analises_total"] = max(total, ANALISES_PADRAO)
        for k, v in campos.items():
            if not str(k).startswith("rel_") or str(k) in _RASCUNHO_RT_NAO_RESTAURAR or k == "rel_analises_total":
                continue
            st.session_state[k] = v
        st.session_state["_rt_origem_desconhecida"] = not bool(campos.get("rel_origem_dados"))
        if "rel_origem_dados" not in campos:
            # Rascunho anterior à identidade dos dados: origem desconhecida, revisão obrigatória.
            st.session_state.pop("rel_origem_dados", None)
            st.session_state.pop("rel_origem_rotulo", None)
            st.session_state.pop("rel_origem_nome_periodo", None)
        st.session_state["_rt_contexto_identificacao"] = {k: st.session_state.get(k) for k in ("rel_nome_condominio", "rel_mes_referencia", "rel_ano_referencia")}
        # O seletor "Carregar dados de cliente cadastrado" passa a mostrar o
        # condomínio restaurado: antes continuava no cliente anterior e um
        # "Carregar" seguinte misturava a tabela restaurada com outro cliente.
        st.session_state["sel_cliente_rel"] = (str(st.session_state.get("rel_nome_condominio") or "").strip()
                                               or "— Selecionar cliente cadastrado —")
        if st.session_state.get("rt_op_sel_cond") is not None:
            st.session_state["_rt_cond_reverter"] = st.session_state.get("rel_nome_condominio")
            if periodo_relatorio_valido(st.session_state.get("rel_mes_referencia"), st.session_state.get("rel_ano_referencia")):
                st.session_state["_rt_periodo_reverter"] = (st.session_state["rel_mes_referencia"], st.session_state["rel_ano_referencia"])
        st.session_state["_relatorio_rt_rascunho_restaurado"] = True
        return True
    except Exception as e:
        for k in list(st.session_state):
            if k not in anterior:
                st.session_state.pop(k, None)
        for k, v in anterior.items():
            # Uploaders e widgets intactos não podem ser reatribuídos no Streamlit.
            if k not in st.session_state or (st.session_state[k] is not v and st.session_state[k] != v):
                st.session_state[k] = v
        st.session_state["_relatorio_rt_restore_erro"] = f"{type(e).__name__}: {e}"
        return False


def _relatorio_rt_aplicar_pendente():
    """Executado no topo do script, antes de qualquer widget rel_/csr_."""
    pendente = st.session_state.get("_rt_rasc_pendente")
    if not pendente:
        return
    if _relatorio_rt_aplicar_rascunho(pendente.get("dados") or {}):
        meta_pg = (pendente.get("dados") or {}).get("_pg")
        if isinstance(meta_pg, dict) and meta_pg.get("doc") and isinstance(meta_pg.get("revision"), int):
            # Revisão restaurada vira a base das próximas gravações desta sessão.
            st.session_state.setdefault("_rt_pg_base", {})[meta_pg["doc"]] = meta_pg["revision"]
        st.session_state.pop("_rt_rasc_pendente", None)
        _relatorio_rt_chave_sessao(nova=True)  # edições a partir daqui viram nova versão; nenhuma linha existente muda
        st.session_state["_rt_rasc_ref"] = None  # próxima execução só registra referência
        st.session_state.pop("_relatorio_rt_restore_erro", None)
        st.session_state.pop("_rt_rasc_lista_cache", None)


def _relatorio_rt_resumo(dados: dict) -> str:
    campos = dados.get("campos", {}) or {}
    cond = str(campos.get("rel_nome_condominio") or campos.get("nome_condominio") or "").strip() or "sem condomínio"
    analises = len({k.rsplit("_", 1)[-1] for k, v in campos.items()
                    if str(k).startswith("rel_analise_") and not str(k).startswith("rel_analise_operador_") and str(v or "").strip()})
    return f"{cond} | salvo em {dados.get('salvo_em', 'horário não informado')} | {analises} linha(s) de análise preenchida(s)"


# Callbacks dos botões do painel: rodam antes do script, então dispensam st.rerun()
# no meio da página (que interromperia a execução antes da tabela de análises).
def _relatorio_rt_cb_restaurar(dados: dict):
    from utils.rt_contexto import motivo_rascunho_oculto
    motivo = motivo_rascunho_oculto(dados, st.session_state.get("empresa_ativa", "aqua_gestao"),
                                    str(st.session_state.get("rel_origem_dados") or ""))
    if motivo:
        st.session_state["_relatorio_rt_restore_erro"] = {
            "sem_identidade": "carregue o condomínio e o período antes de restaurar.",
            "outra_identidade": "o rascunho é de outro condomínio ou período.",
            "origem_nao_rt": "o rascunho não tem origem RT comprovada.",
        }.get(motivo, motivo)
        return
    anterior = st.session_state.get("_rt_rasc_pendente")
    tinha_pendente = "_rt_rasc_pendente" in st.session_state
    st.session_state["_rt_rasc_pendente"] = {"dados": dados}
    _relatorio_rt_aplicar_pendente()
    if "_relatorio_rt_restore_erro" in st.session_state:
        if tinha_pendente:
            st.session_state["_rt_rasc_pendente"] = anterior
        else:
            st.session_state.pop("_rt_rasc_pendente", None)


def _relatorio_rt_cb_pedir_descarte(chave: str):
    st.session_state["_rt_rasc_confirmar_descarte"] = chave


def _relatorio_rt_cb_cancelar_descarte():
    st.session_state.pop("_rt_rasc_confirmar_descarte", None)


def _relatorio_rt_cb_confirmar_descarte(chave: str):
    if _relatorio_rt_descartar(chave):
        st.session_state.pop("_rt_rasc_confirmar_descarte", None)
        st.session_state["_rt_rasc_msg"] = "Rascunho descartado."
    # em caso de falha a confirmação continua aberta para nova tentativa


def _relatorio_rt_renderizar_painel_rascunho():
    try:
        ss = st.session_state
        agora = datetime.now().timestamp()
        cache = ss.get("_rt_rasc_lista_cache")
        if cache and agora - cache[0] < 20 and cache[1].get("empresa") == ss.get("empresa_ativa", "aqua_gestao"):
            lista = cache[1]  # evita ler a planilha a cada rerun
        else:
            lista = _relatorio_rt_listar_rascunhos()
            ss["_rt_rasc_lista_cache"] = (agora, lista)
        for aviso in lista.get("avisos", []):
            st.warning(aviso)
        from utils.rt_contexto import motivo_rascunho_oculto
        _identidade_rasc = str(ss.get("rel_origem_dados") or "")
        _empresa_rasc = ss.get("empresa_ativa", "aqua_gestao")
        _motivos = [motivo_rascunho_oculto(v["dados"], _empresa_rasc, _identidade_rasc) for v in lista["versoes"]]
        # Filtro aplicado a cada execução: trocar de condomínio/período atualiza a lista na hora.
        versoes = [v for v, m in zip(lista["versoes"], _motivos) if not m]
        if not _identidade_rasc:
            st.caption("Carregue o condomínio e o período para ver os rascunhos RT deste relatório.")
        elif _motivos.count("origem_nao_rt"):
            st.caption(f"{_motivos.count('origem_nao_rt')} rascunho(s) deste condomínio e período sem origem RT comprovada "
                       "(acesso de operador ou registro antigo) não são listados; continuam preservados.")
        minha = ss.get("_rt_rasc_chave")
        if versoes:
            st.warning("🛡️ Rascunhos de Relatório RT disponíveis (do mais recente para o mais antigo):")
        descartes_exibidos = set()
        por_chave = {}
        for v in versoes:
            por_chave[v["chave"]] = por_chave.get(v["chave"], 0) + 1
        for v in versoes:
            chave, rasc = v["chave"], v["dados"]
            if v["origem"] == "postgres":
                selo = f" — PostgreSQL de homologação, revisão {v.get('revisao')}"
            elif v.get("pendente") and not v.get("conflito"):
                selo = f" — cópia deste servidor com envio {_rascunho_destino('a')} pendente (reenvio automático)"
            else:
                selo = " — este acesso" if chave == minha else (" — cópia temporária deste servidor, NÃO salva na planilha" if v["origem"] == "local" else "")
            st.markdown(f"- **{_relatorio_rt_resumo(rasc)}**{selo}")
            id_btn = re.sub(r"\W", "_", chave)
            if v.get("conflito") or por_chave.get(chave, 0) > 1:
                id_btn += "_" + v["origem"] + "_" + v["hash"][:12]
            if v.get("conflito"):
                st.warning("Cópias divergentes: " + ("local pendente" if v.get("pendente") else v["origem"]) + ". Restaure explicitamente para continuar em nova chave.")
            c_r1, c_r2, _ = st.columns([1, 1, 2])
            with c_r1:
                st.button("♻️ Restaurar", key=f"btn_restaurar_rascunho_rt_{id_btn}", use_container_width=True,
                          on_click=_relatorio_rt_cb_restaurar, args=(rasc,))
            with c_r2:
                if v["origem"] == "postgres":
                    st.caption("Revisões no PostgreSQL são imutáveis.")
                elif chave not in descartes_exibidos:
                    st.button("🗑️ Descartar", key=f"btn_descartar_rascunho_rt_{id_btn}", use_container_width=True,
                              on_click=_relatorio_rt_cb_pedir_descarte, args=(chave,))
            mostrar_descarte = chave not in descartes_exibidos
            descartes_exibidos.add(chave)
            if mostrar_descarte and ss.get("_rt_rasc_confirmar_descarte") == chave:
                st.error(
                    f"Descartar este rascunho? **{_relatorio_rt_resumo(rasc)}**. Ele deixará de ser oferecido para restauração; "
                    "O descarte se aplica às cópias local e remota desta chave. O conteúdo é preservado; outras chaves não são afetadas."
                )
                c_c1, c_c2, _ = st.columns([1, 1, 2])
                with c_c1:
                    st.button("Sim, descartar este rascunho", key=f"btn_confirmar_descarte_rt_{id_btn}", use_container_width=True,
                              on_click=_relatorio_rt_cb_confirmar_descarte, args=(chave,))
                with c_c2:
                    st.button("Cancelar", key=f"btn_cancelar_descarte_rt_{id_btn}", use_container_width=True,
                              on_click=_relatorio_rt_cb_cancelar_descarte)
        if lista["ignorados"]:
            st.caption(f"{lista['ignorados']} versão(ões) ignorada(s) por estarem incompletas ou corrompidas.")
        if ss.get("_relatorio_rt_restore_erro"):
            st.error(f"Não foi possível restaurar o rascunho: {ss['_relatorio_rt_restore_erro']}")
        if ss.get("_relatorio_rt_rascunho_restaurado"):
            st.success("✅ Rascunho do relatório RT restaurado nesta sessão.")
            ss["_relatorio_rt_rascunho_restaurado"] = False
        if ss.get("_rt_rasc_msg"):
            st.success(ss.pop("_rt_rasc_msg"))
        if ss.get("_rt_rasc_erro_descarte"):
            st.error(ss.pop("_rt_rasc_erro_descarte"))
        if ss.get("_relatorio_rt_autosave_erro"):
            st.error("Salvamento do rascunho não concluído; a cópia anterior foi preservada. " + ss["_relatorio_rt_autosave_erro"])
        if ss.get("_rt_rasc_aviso"):
            st.error(
                f"⚠️ Há alterações do rascunho RT que AINDA NÃO foram salvas {_rascunho_destino('em')} e podem ser perdidas se o "
                "disco local for perdido. A pendência sobrevive à reabertura neste disco; conteúdo remoto divergente não será sobrescrito. "
                f"A última versão salva {_rascunho_destino('em')} foi preservada. Motivo: {ss['_rt_rasc_aviso']}"
            )
        if _rascunho_backend() == "postgres":
            st.caption("🧪 Homologação: rascunhos RT gravados no PostgreSQL de homologação, sem usar a planilha de produção.")
        elif not _rascunho_usa_sheets():
            st.caption("🧪 Ambiente de desenvolvimento: rascunhos RT ficam só neste computador, sem usar a planilha de produção.")
        ultimo = ss.get("_relatorio_rt_ultimo_autosave", "")
        if ultimo and not ss.get("_rt_rasc_aviso"):
            st.caption(f"🛡️ Autosave do relatório RT ativo. Último salvamento: {ultimo}")
    except Exception as e:
        st.caption(f"Painel de rascunho RT indisponível: {e}")



